# =====================================================================
#  Scrcpy Flow  -  smooth wireless phone mirroring, powered by scrcpy
#  (unofficial; scrcpy is made by Genymobile)
#  Windows PowerShell 5.1 + WPF. No install needed.
#  Start it with "Start Scrcpy Flow.bat".
# =====================================================================

$ErrorActionPreference = 'Stop'
$Here = $PSScriptRoot
$MyScript = $PSCommandPath
$LogFile = Join-Path $Here 'scrcpy-flow.log'

function Write-Crash($err) {
    try {
        $text = "[{0}] {1}`r`n{2}`r`n" -f (Get-Date -Format 's'), ($err | Out-String), $(if ($err.InvocationInfo) { $err.InvocationInfo.PositionMessage } else { '' })
        Add-Content -Path $LogFile -Value $text
    } catch {}
}

# WPF needs a single-threaded apartment
if ([System.Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA') {
    Start-Process powershell.exe -ArgumentList @('-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', "`"$PSCommandPath`"")
    exit
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms, System.Drawing, Microsoft.VisualBasic

try {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class StudioNative {
    [DllImport("dwmapi.dll")]
    public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);
}
"@
} catch {}

$Dot = [string][char]0x00B7
$Bullet = [string][char]0x25CF
$StatePath = Join-Path $Here 'scrcpy-flow.json'
# Bring settings over from the old name (scrcpy Studio)
$OldStatePath = Join-Path $Here 'scrcpy-studio.json'
if (-not (Test-Path -LiteralPath $StatePath) -and (Test-Path -LiteralPath $OldStatePath)) {
    try { Copy-Item -LiteralPath $OldStatePath -Destination $StatePath } catch {}
}

# App icon (gradient phone + play), embedded so the app stays a single file
$FlowIconPng = ''
$FlowIconIco = ''

# Pairing QR codes are generated fresh (random name + password) every time
# you click "Show QR code", so no pairing secret is stored in this file.
$QrSource = @'
using System;
using System.Text;

/// Minimal QR Code encoder (byte mode, error correction M, versions 1-10) for Scrcpy Flow pairing codes.
public static class StudioQr
{
    // ---- Minimal QR Code encoder: byte mode, error correction level M, versions 1-10 ----
    // Written for scrcpy Studio. Algorithm follows the QR Code specification (ISO/IEC 18004).

    // Level M tables, index = version (0 unused)
    private static int[] ECC_PER_BLOCK = { -1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26 };
    private static int[] NUM_BLOCKS    = { -1,  1,  1,  1,  2,  2,  4,  4,  4,  5,  5 };

    private static int Size;
    private static bool[] Modules;
    private static bool[] IsFunction;

    public static bool[] EncodeBytes(int[] data) {
        int version = 0;
        for (int v = 1; v <= 10; v++) {
            int capacityBits = NumDataCodewords(v) * 8;
            int ccBits = v <= 9 ? 8 : 16;
            if (4 + ccBits + data.Length * 8 <= capacityBits) { version = v; break; }
        }
        if (version == 0) throw new ArgumentException("Text too long for QR code");

        // Bit stream
        int dataCap = NumDataCodewords(version);
        int[] bits = new int[dataCap * 8];
        int bitLen = 0;
        bitLen = AppendBits(bits, bitLen, 4, 4);
        bitLen = AppendBits(bits, bitLen, data.Length, version <= 9 ? 8 : 16);
        for (int i = 0; i < data.Length; i++) bitLen = AppendBits(bits, bitLen, data[i] & 0xFF, 8);
        int term = Math.Min(4, dataCap * 8 - bitLen);
        bitLen = AppendBits(bits, bitLen, 0, term);
        while (bitLen % 8 != 0) bitLen = AppendBits(bits, bitLen, 0, 1);
        int[] dataCodewords = new int[dataCap];
        int count = bitLen / 8;
        for (int i = 0; i < count; i++) {
            int b = 0;
            for (int j = 0; j < 8; j++) b = (b << 1) | bits[i * 8 + j];
            dataCodewords[i] = b;
        }
        for (int i = count, pad = 0xEC; i < dataCap; i++, pad ^= 0xEC ^ 0x11) dataCodewords[i] = pad;

        int[] allCodewords = AddEccAndInterleave(version, dataCodewords);

        Size = version * 4 + 17;
        Modules = new bool[Size * Size];
        IsFunction = new bool[Size * Size];
        DrawFunctionPatterns(version);
        DrawCodewords(allCodewords);

        int bestMask = 0;
        int bestPenalty = 2147483647;
        for (int mask = 0; mask < 8; mask++) {
            ApplyMask(mask);
            DrawFormatBits(mask);
            int p = Penalty();
            if (p < bestPenalty) { bestPenalty = p; bestMask = mask; }
            ApplyMask(mask); // undo (XOR)
        }
        ApplyMask(bestMask);
        DrawFormatBits(bestMask);
        return Modules;
    }

    public static int SizeOf() { return Size; }

    private static int AppendBits(int[] bits, int len, int val, int n) {
        for (int i = n - 1; i >= 0; i--) { bits[len] = (val >> i) & 1; len++; }
        return len;
    }

    private static int NumRawDataModules(int ver) {
        int result = (16 * ver + 128) * ver + 64;
        if (ver >= 2) {
            int numAlign = ver / 7 + 2;
            result -= (25 * numAlign - 10) * numAlign - 55;
            if (ver >= 7) result -= 36;
        }
        return result;
    }

    private static int NumDataCodewords(int ver) {
        return NumRawDataModules(ver) / 8 - ECC_PER_BLOCK[ver] * NUM_BLOCKS[ver];
    }

    // ---- Reed-Solomon over GF(2^8) with polynomial 0x11D ----
    private static int GfMul(int x, int y) {
        int z = 0;
        for (int i = 7; i >= 0; i--) {
            z = (z << 1) ^ ((z >> 7) * 0x11D);
            z ^= ((y >> i) & 1) * x;
        }
        return z & 0xFF;
    }

    private static int[] RsDivisor(int degree) {
        int[] result = new int[degree];
        result[degree - 1] = 1;
        int root = 1;
        for (int i = 0; i < degree; i++) {
            for (int j = 0; j < degree; j++) {
                result[j] = GfMul(result[j], root);
                if (j + 1 < degree) result[j] ^= result[j + 1];
            }
            root = GfMul(root, 0x02);
        }
        return result;
    }

    private static int[] RsRemainder(int[] data, int dataLen, int[] divisor) {
        int[] result = new int[divisor.Length];
        for (int k = 0; k < dataLen; k++) {
            int factor = data[k] ^ result[0];
            for (int i = 0; i + 1 < result.Length; i++) result[i] = result[i + 1];
            result[result.Length - 1] = 0;
            for (int i = 0; i < result.Length; i++) result[i] ^= GfMul(divisor[i], factor);
        }
        return result;
    }

    private static int[] AddEccAndInterleave(int ver, int[] data) {
        int numBlocks = NUM_BLOCKS[ver];
        int blockEccLen = ECC_PER_BLOCK[ver];
        int rawCodewords = NumRawDataModules(ver) / 8;
        int numShortBlocks = numBlocks - rawCodewords % numBlocks;
        int shortBlockLen = rawCodewords / numBlocks;
        int[] divisor = RsDivisor(blockEccLen);

        // blocks[i] has length shortBlockLen + 1; short blocks leave a gap before the ECC part
        int[] blocks = new int[numBlocks * (shortBlockLen + 1)];
        int stride = shortBlockLen + 1;
        int k = 0;
        for (int i = 0; i < numBlocks; i++) {
            int datLen = shortBlockLen - blockEccLen + (i < numShortBlocks ? 0 : 1);
            int[] dat = new int[datLen];
            for (int j = 0; j < datLen; j++) dat[j] = data[k + j];
            k += datLen;
            int[] ecc = RsRemainder(dat, datLen, divisor);
            int pos = 0;
            for (int j = 0; j < datLen; j++) { blocks[i * stride + pos] = dat[j]; pos++; }
            if (i < numShortBlocks) pos++; // gap
            for (int j = 0; j < ecc.Length; j++) { blocks[i * stride + pos] = ecc[j]; pos++; }
        }

        int[] result = new int[rawCodewords];
        int r = 0;
        for (int i = 0; i < stride; i++) {
            for (int j = 0; j < numBlocks; j++) {
                if (i != shortBlockLen - blockEccLen || j >= numShortBlocks) {
                    result[r] = blocks[j * stride + i];
                    r++;
                }
            }
        }
        return result;
    }

    // ---- Module drawing ----
    private static void SetFunction(int x, int y, bool dark) {
        Modules[y * Size + x] = dark;
        IsFunction[y * Size + x] = true;
    }

    private static void DrawFunctionPatterns(int ver) {
        for (int i = 0; i < Size; i++) {
            SetFunction(6, i, i % 2 == 0);
            SetFunction(i, 6, i % 2 == 0);
        }
        DrawFinder(3, 3);
        DrawFinder(Size - 4, 3);
        DrawFinder(3, Size - 4);

        int[] align = AlignmentPositions(ver);
        int n = align.Length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i == 0 && j == 0) || (i == 0 && j == n - 1) || (i == n - 1 && j == 0)) continue;
                DrawAlignment(align[i], align[j]);
            }
        }
        DrawFormatBits(0); // reserve the area; real bits are drawn after masking
        DrawVersion(ver);
    }

    private static void DrawFinder(int x, int y) {
        for (int dy = -4; dy <= 4; dy++) {
            for (int dx = -4; dx <= 4; dx++) {
                int dist = Math.Max(Math.Abs(dx), Math.Abs(dy));
                int xx = x + dx, yy = y + dy;
                if (0 <= xx && xx < Size && 0 <= yy && yy < Size) SetFunction(xx, yy, dist != 2 && dist != 4);
            }
        }
    }

    private static void DrawAlignment(int x, int y) {
        for (int dy = -2; dy <= 2; dy++)
            for (int dx = -2; dx <= 2; dx++)
                SetFunction(x + dx, y + dy, Math.Max(Math.Abs(dx), Math.Abs(dy)) != 1);
    }

    private static int[] AlignmentPositions(int ver) {
        if (ver == 1) return new int[0];
        int numAlign = ver / 7 + 2;
        int step = (ver * 4 + numAlign * 2 + 1) / (numAlign * 2 - 2) * 2;
        int[] result = new int[numAlign];
        result[0] = 6;
        int pos = ver * 4 + 10;
        for (int i = numAlign - 1; i >= 1; i--) { result[i] = pos; pos -= step; }
        return result;
    }

    private static void DrawFormatBits(int mask) {
        int data = (0 << 3) | mask; // level M = 00
        int rem = data;
        for (int i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >> 9) * 0x537);
        int bits = ((data << 10) | rem) ^ 0x5412;

        for (int i = 0; i <= 5; i++) SetFunction(8, i, ((bits >> i) & 1) != 0);
        SetFunction(8, 7, ((bits >> 6) & 1) != 0);
        SetFunction(8, 8, ((bits >> 7) & 1) != 0);
        SetFunction(7, 8, ((bits >> 8) & 1) != 0);
        for (int i = 9; i < 15; i++) SetFunction(14 - i, 8, ((bits >> i) & 1) != 0);

        for (int i = 0; i < 8; i++) SetFunction(Size - 1 - i, 8, ((bits >> i) & 1) != 0);
        for (int i = 8; i < 15; i++) SetFunction(8, Size - 15 + i, ((bits >> i) & 1) != 0);
        SetFunction(8, Size - 8, true);
    }

    private static void DrawVersion(int ver) {
        if (ver < 7) return;
        int rem = ver;
        for (int i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >> 11) * 0x1F25);
        int bits = (ver << 12) | rem;
        for (int i = 0; i < 18; i++) {
            bool bit = ((bits >> i) & 1) != 0;
            int a = Size - 11 + i % 3, b = i / 3;
            SetFunction(a, b, bit);
            SetFunction(b, a, bit);
        }
    }

    private static void DrawCodewords(int[] data) {
        int i = 0;
        int total = data.Length * 8;
        for (int right = Size - 1; right >= 1; right -= 2) {
            if (right == 6) right = 5;
            for (int vert = 0; vert < Size; vert++) {
                for (int j = 0; j < 2; j++) {
                    int x = right - j;
                    bool upward = ((right + 1) & 2) == 0;
                    int y = upward ? Size - 1 - vert : vert;
                    if (!IsFunction[y * Size + x] && i < total) {
                        Modules[y * Size + x] = ((data[i >> 3] >> (7 - (i & 7))) & 1) != 0;
                        i++;
                    }
                }
            }
        }
    }

    private static void ApplyMask(int mask) {
        for (int y = 0; y < Size; y++) {
            for (int x = 0; x < Size; x++) {
                bool invert;
                switch (mask) {
                    case 0: invert = (x + y) % 2 == 0; break;
                    case 1: invert = y % 2 == 0; break;
                    case 2: invert = x % 3 == 0; break;
                    case 3: invert = (x + y) % 3 == 0; break;
                    case 4: invert = (x / 3 + y / 2) % 2 == 0; break;
                    case 5: invert = x * y % 2 + x * y % 3 == 0; break;
                    case 6: invert = (x * y % 2 + x * y % 3) % 2 == 0; break;
                    default: invert = ((x + y) % 2 + x * y % 3) % 2 == 0; break;
                }
                if (invert && !IsFunction[y * Size + x]) Modules[y * Size + x] = !Modules[y * Size + x];
            }
        }
    }

    private static bool M(int x, int y) { return Modules[y * Size + x]; }

    private static int Penalty() {
        int result = 0;
        // Rule 1: runs of 5+ same-colour modules in rows and columns
        for (int pass = 0; pass < 2; pass++) {
            for (int a = 0; a < Size; a++) {
                int run = 1;
                for (int b = 1; b < Size; b++) {
                    bool cur = pass == 0 ? M(b, a) : M(a, b);
                    bool prev = pass == 0 ? M(b - 1, a) : M(a, b - 1);
                    if (cur == prev) {
                        run++;
                        if (run == 5) result += 3;
                        else if (run > 5) result++;
                    } else run = 1;
                }
            }
        }
        // Rule 2: 2x2 blocks
        for (int y = 0; y < Size - 1; y++)
            for (int x = 0; x < Size - 1; x++) {
                bool c = M(x, y);
                if (c == M(x + 1, y) && c == M(x, y + 1) && c == M(x + 1, y + 1)) result += 3;
            }
        // Rule 3: finder-like patterns 1011101 with 4 light modules on one side
        for (int pass = 0; pass < 2; pass++) {
            for (int a = 0; a < Size; a++) {
                for (int b = 0; b + 10 < Size; b++) {
                    bool p1 = true, p2 = true;
                    for (int k = 0; k < 11; k++) {
                        bool v = pass == 0 ? M(b + k, a) : M(a, b + k);
                        bool e1 = k == 0 || (k >= 2 && k <= 4) || k == 6; // 10111010000
                        bool e2 = k == 4 || k == 6 || (k >= 8 && k <= 10) || k == 10; // 00001011101
                        if (k >= 7) e1 = false;
                        if (k <= 3) e2 = false;
                        if (k == 5 || k == 7) e2 = false;
                        if (v != e1) p1 = false;
                        if (v != e2) p2 = false;
                    }
                    if (p1) result += 40;
                    if (p2) result += 40;
                }
            }
        }
        // Rule 4: dark/light balance
        int dark = 0;
        for (int i = 0; i < Size * Size; i++) if (Modules[i]) dark++;
        int total = Size * Size;
        int kk = (Math.Abs(dark * 20 - total * 10) + total - 1) / total - 1;
        if (kk < 0) kk = 0;
        result += kk * 10;
        return result;
    }

    public static bool[] EncodeText(string text) {
        byte[] b = Encoding.UTF8.GetBytes(text);
        int[] d = new int[b.Length];
        for (int i = 0; i < b.Length; i++) d[i] = b[i];
        return EncodeBytes(d);
    }

    /// Gray8 pixels: black modules on white, with a quiet zone.
    public static byte[] Render(bool[] modules, int size, int scale, int quiet) {
        int w = (size + quiet * 2) * scale;
        byte[] px = new byte[w * w];
        for (int i = 0; i < px.Length; i++) px[i] = 255;
        for (int y = 0; y < size; y++) {
            for (int x = 0; x < size; x++) {
                if (!modules[y * size + x]) continue;
                int ox = (x + quiet) * scale, oy = (y + quiet) * scale;
                for (int dy = 0; dy < scale; dy++)
                    for (int dx = 0; dx < scale; dx++)
                        px[(oy + dy) * w + ox + dx] = 0;
            }
        }
        return px;
    }
}
'@
$QrReady = $false
try {
    Add-Type -TypeDefinition $QrSource -Language CSharp
    $QrReady = $true
} catch { Write-Crash $_ }

$App = @{
    Scrcpy         = $null
    ScrcpyDir      = $null
    Adb            = $null
    ScrcpyMajor    = 4
    ScrcpyVersion  = '?'
    Sessions       = (New-Object System.Collections.ArrayList)
    Detected       = @()
    Loading        = $false
    Syncing        = $false
    EditingProfile = 'Balanced'
    InTick         = $false
    DlgFrame       = $null
    DlgResult      = $null
    BusyDepth      = 0
}

# =====================================================================
#  Option lists (value, label)
# =====================================================================
$Opt = @{
    Size     = @(@(0, 'Native (full resolution)'), @(1024, '1024 px (lightest)'), @(1280, '1280 px'), @(1600, '1600 px'), @(1920, '1920 px'), @(2400, '2400 px'))
    GSize    = @(@(1280, '1280 px (smoothest)'), @(1600, '1600 px'), @(1920, '1920 px (sharp)'), @(0, 'Native (full resolution)'))
    Fps      = @(@(0, 'No limit'), @(30, '30 fps'), @(60, '60 fps'), @(90, '90 fps'), @(120, '120 fps'), @(144, '144 fps'))
    GFps     = @(@(60, '60 fps'), @(90, '90 fps'), @(120, '120 fps'), @(144, '144 fps'), @(0, 'No limit'))
    Codec    = @(@('h264', 'H.264 (lowest latency)'), @('h265', 'H.265 (sharper, less data)'), @('av1', 'AV1 (newest phones only)'))
    Source   = @(@('display', 'Phone screen'), @('camera-back', 'Back camera (Android 12+)'), @('camera-front', 'Front camera (Android 12+)'))
    AudioSrc = @(@('output', 'Phone sound'), @('playback', 'App sound only (Android 13+)'), @('mic', 'Microphone'))
    AudioBuf = @(@(0, 'Normal (50 ms)'), @(30, 'Low (30 ms, may crackle)'), @(120, 'Smooth (120 ms)'))
    Keyboard = @(@('sdk', 'Normal'), @('uhid', 'Physical keyboard (UHID)'), @('disabled', 'Off'))
    Mouse    = @(@('sdk', 'Normal (acts like touch)'), @('uhid', 'Physical mouse (UHID, captured)'), @('disabled', 'Off'))
    Gamepad  = @(@('disabled', 'Off'), @('uhid', 'Controller (UHID)'))
    VdSize   = @(@('', 'Same as phone'), @('1280x720', '1280 x 720'), @('1920x1080', '1920 x 1080'), @('2560x1440', '2560 x 1440'))
    VdDpi    = @(@(0, 'Default'), @(160, '160 (small UI)'), @(240, '240'), @(320, '320'), @(420, '420 (large UI)'))
    Format   = @(@('mp4', 'MP4 (plays everywhere)'), @('mkv', 'MKV (safer if stopped early)'))
    Limit    = @(@(0, 'Never'), @(60, '1 minute'), @(300, '5 minutes'), @(600, '10 minutes'), @(1800, '30 minutes'), @(3600, '1 hour'))
}

# =====================================================================
#  Profiles, devices, state
# =====================================================================
function Merge-Into($target, $src) {
    if ($null -eq $src) { return }
    if ($src -is [System.Collections.IDictionary]) {
        foreach ($k in @($src.Keys)) { if ($target.Contains($k)) { $target[$k] = $src[$k] } }
    } else {
        foreach ($pr in $src.PSObject.Properties) { if ($target.Contains($pr.Name)) { $target[$pr.Name] = $pr.Value } }
    }
}

function New-ProfileData([string]$Name, [bool]$BuiltIn, $Over) {
    $p = [ordered]@{
        Name = $Name; BuiltIn = $BuiltIn
        MaxSize = 1600; BitRate = 8; MaxFps = 0; Codec = 'h264'; Source = 'display'; RotationLock = $false
        Audio = $true; AudioSource = 'output'; AudioBuffer = 0
        Keyboard = 'sdk'; Mouse = 'sdk'; Gamepad = 'disabled'; NoControl = $false
        ScreenOff = $false; KeepActive = $true; StayAwake = $false; ShowTouches = $false; PowerOffOnClose = $false
        OnTop = $false; Fullscreen = $false; Borderless = $false; PrintFps = $false
        VirtualDisplay = $false; VdSize = ''; VdDpi = 0; FlexDisplay = $false; StartApp = ''
        ExtraArgs = ''
    }
    Merge-Into $p $Over
    $p.Name = $Name
    $p.BuiltIn = $BuiltIn
    return [pscustomobject]$p
}

function Get-BuiltInProfiles {
    return @(
        (New-ProfileData 'Balanced' $true @{}),
        (New-ProfileData 'Best quality' $true @{ MaxSize = 0; BitRate = 16 }),
        (New-ProfileData 'Smooth (Wi-Fi)' $true @{ MaxSize = 1024; BitRate = 4; MaxFps = 60 }),
        (New-ProfileData 'Gaming' $true @{ MaxSize = 1920; BitRate = 12; MaxFps = 120; AudioBuffer = 30; PrintFps = $true })
    )
}

function New-DeviceObj($Over) {
    $d = [ordered]@{ Id = [guid]::NewGuid().ToString(); Name = 'Phone'; Address = ''; HwSerial = ''; Model = ''; Profile = 'Balanced'; Companion = $false }
    Merge-Into $d $Over
    if (-not $d.Id) { $d.Id = [guid]::NewGuid().ToString() }
    return [pscustomobject]$d
}

function New-DefaultState {
    return [pscustomobject]@{
        ScrcpyPath    = ''
        RecordDir     = (Join-Path ([Environment]::GetFolderPath('MyVideos')) 'scrcpy')
        ShotDir       = (Join-Path ([Environment]::GetFolderPath('MyPictures')) 'scrcpy')
        RecordFormat  = 'mp4'
        TimeLimit     = 0
        AutoConnect   = $false
        Theme         = 'Midnight'
        DefaultDevice = ''
        LastDevice    = ''
        Devices       = @()
        Profiles      = @(Get-BuiltInProfiles)
    }
}

function Load-State {
    $s = New-DefaultState
    if (Test-Path -LiteralPath $StatePath) {
        try {
            $j = Get-Content -LiteralPath $StatePath -Raw | ConvertFrom-Json
            foreach ($k in 'ScrcpyPath', 'RecordDir', 'ShotDir', 'RecordFormat', 'TimeLimit', 'AutoConnect', 'DefaultDevice', 'LastDevice', 'Theme') {
                if ($null -ne $j.$k -and "$($j.$k)" -ne '') { $s.$k = $j.$k }
            }
            $devs = @()
            foreach ($d in @($j.Devices)) { if ($d) { $devs += New-DeviceObj $d } }
            $s.Devices = $devs
            $profs = @()
            foreach ($p in @($j.Profiles)) { if ($p -and $p.Name) { $profs += New-ProfileData ([string]$p.Name) ([bool]$p.BuiltIn) $p } }
            foreach ($b in (Get-BuiltInProfiles)) {
                if (-not ($profs | Where-Object { $_.Name -eq $b.Name })) { $profs += $b }
            }
            $s.Profiles = $profs
        } catch { Write-Crash $_ }
    } else {
        # First run: bring over settings from the simple launcher if it is here
        $old = Join-Path $Here 'scrcpy-launcher.json'
        if (Test-Path -LiteralPath $old) {
            try {
                $o = Get-Content -LiteralPath $old -Raw | ConvertFrom-Json
                if ($o.ScrcpyPath) { $s.ScrcpyPath = [string]$o.ScrcpyPath }
                if ($o.Address) {
                    $q = 1
                    if ($null -ne $o.Quality) { $q = [int]$o.Quality }
                    $pn = @('Best quality', 'Balanced', 'Smooth (Wi-Fi)')[[math]::Max(0, [math]::Min(2, $q))]
                    $dev = New-DeviceObj @{ Name = 'My phone'; Address = [string]$o.Address; Profile = $pn }
                    $s.Devices = @($dev)
                    $s.DefaultDevice = $dev.Id
                }
            } catch { Write-Crash $_ }
        }
    }
    return $s
}

function Save-State {
    try {
        $State | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $StatePath -Encoding UTF8
    } catch { Write-Crash $_ }
}

function Get-Profile([string]$Name) {
    $p = $State.Profiles | Where-Object { $_.Name -eq $Name } | Select-Object -First 1
    if (-not $p) { $p = $State.Profiles | Where-Object { $_.Name -eq 'Balanced' } | Select-Object -First 1 }
    if (-not $p) { $p = $State.Profiles | Select-Object -First 1 }
    return $p
}

function Get-Device([string]$Id) {
    return ($State.Devices | Where-Object { $_.Id -eq $Id } | Select-Object -First 1)
}

# =====================================================================
#  Process helpers (keep the window responsive while waiting)
# =====================================================================
$ExitFrameCallback = [System.Windows.Threading.DispatcherOperationCallback] {
    param($f)
    $f.Continue = $false
    return $null
}

function Invoke-UIEvents {
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    [void][System.Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke(
        [System.Windows.Threading.DispatcherPriority]::Background, $ExitFrameCallback, $frame)
    [System.Windows.Threading.Dispatcher]::PushFrame($frame)
}

function Wait-UI([int]$Ms) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    while ($sw.ElapsedMilliseconds -lt $Ms) {
        Invoke-UIEvents
        Start-Sleep -Milliseconds 25
    }
}

function New-Psi([string]$Exe, [string]$Arguments, [bool]$Redirect) {
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe
    $psi.Arguments = $Arguments
    $psi.WorkingDirectory = $App.ScrcpyDir
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    if ($Redirect) {
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
    }
    return $psi
}

function Invoke-Tool([string]$Exe, [string]$Arguments, [int]$TimeoutSec = 15) {
    $p = [System.Diagnostics.Process]::Start((New-Psi $Exe $Arguments $true))
    $out = $p.StandardOutput.ReadToEndAsync()
    $err = $p.StandardError.ReadToEndAsync()
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $timedOut = $false
    while (-not $p.HasExited) {
        Invoke-UIEvents
        Start-Sleep -Milliseconds 25
        if ($sw.Elapsed.TotalSeconds -gt $TimeoutSec) {
            $timedOut = $true
            try { $p.Kill() } catch {}
            break
        }
    }
    $o = ''; $e = ''
    if ($out.Wait(1500)) { $o = $out.Result }
    if ($err.Wait(1500)) { $e = $err.Result }
    $code = -1
    if ($p.HasExited) { $code = $p.ExitCode }
    return [pscustomobject]@{ Out = "$o"; Err = "$e"; Text = ("$o`n$e").Trim(); Code = $code; TimedOut = $timedOut }
}

function Invoke-Adb([string]$Arguments, [int]$TimeoutSec = 15) {
    return (Invoke-Tool $App.Adb $Arguments $TimeoutSec)
}

function Start-AdbServer {
    try {
        $p = [System.Diagnostics.Process]::Start((New-Psi $App.Adb 'start-server' $false))
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        while (-not $p.HasExited -and $sw.Elapsed.TotalSeconds -lt 20) {
            Invoke-UIEvents
            Start-Sleep -Milliseconds 30
        }
        return $true
    } catch {
        Write-Crash $_
        return $false
    }
}

function Quote-Token([string]$t) {
    if ($t -match '[\s"]') { return '"' + ($t -replace '"', '\"') + '"' }
    return $t
}

function Safe-Name([string]$s) {
    $n = ($s -replace '[\\/:*?"<>|]', '') -replace '\s+', '_'
    if (-not $n) { $n = 'phone' }
    return $n
}

function Normalize-Address([string]$s) {
    if ($null -eq $s) { return $null }
    $s = $s.Trim().TrimEnd(':')
    if (-not $s) { return $null }
    if ($s -notmatch ':\d+$') { $s = "${s}:5555" }
    return $s
}

function Get-IpOf([string]$addr) {
    if (-not $addr) { return '' }
    return ($addr -split ':')[0]
}

# =====================================================================
#  adb: devices, info, wireless
# =====================================================================
function Get-AdbDevices {
    $r = Invoke-Adb 'devices -l' 15
    $list = @()
    foreach ($line in ($r.Out -split "\r?\n")) {
        if ($line -match '^(\S+)\s+(device|unauthorized|offline|authorizing|recovery|sideload)\b(.*)$') {
            $serial = $Matches[1]; $st = $Matches[2]; $rest = $Matches[3]
            $model = ''
            if ($rest -match 'model:(\S+)') { $model = $Matches[1] -replace '_', ' ' }
            $type = 'USB'
            if ($serial -match '^\d{1,3}(\.\d{1,3}){3}:\d+$' -or $serial -match '_adb-tls-connect') { $type = 'Wi-Fi' }
            $list += [pscustomobject]@{ Serial = $serial; State = $st; Model = $model; Type = $type }
        }
    }
    return $list
}

function Get-MdnsServices {
    $r = Invoke-Adb 'mdns services' 8
    $list = @()
    foreach ($line in ($r.Out -split "\r?\n")) {
        if ($line -match '^(\S+)\s+_adb-tls-connect\._tcp\.?\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d+)') {
            $list += [pscustomobject]@{ Name = $Matches[1]; Ip = $Matches[2]; Port = $Matches[3] }
        }
    }
    return $list
}

function Get-MdnsPairing {
    $r = Invoke-Adb 'mdns services' 8
    $list = @()
    foreach ($line in ($r.Out -split "\r?\n")) {
        if ($line -match '^(\S+)\s+_adb-tls-pairing\._tcp\.?\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d+)') {
            $list += [pscustomobject]@{ Name = $Matches[1]; Ip = $Matches[2]; Port = $Matches[3] }
        }
    }
    return $list
}

function Get-HwFromName([string]$n) {
    if ($n -match '^adb-(.+)-[^-.]+(\._adb-tls.*)?$') { return $Matches[1] }
    return ''
}

function Get-PhoneInfo([string]$Serial) {
    $r = Invoke-Adb "-s $Serial shell `"getprop ro.product.model;getprop ro.build.version.release;getprop ro.serialno;getprop ro.product.manufacturer;dumpsys battery`"" 12
    $lines = @($r.Out -split "\r?\n")
    if ($lines.Count -lt 3 -or -not $lines[0].Trim() -or $r.Text -match '^error') { return $null }
    $bat = ''
    $charging = $false
    if ($r.Out -match 'level:\s*(\d+)') { $bat = $Matches[1] }
    if ($r.Out -match '(?m)^\s*status:\s*(\d+)') { $charging = @('2', '5') -contains $Matches[1] }
    $brand = ''
    if ($lines.Count -ge 4) { $brand = $lines[3].Trim() }
    return [pscustomobject]@{
        Model    = $lines[0].Trim()
        Android  = $lines[1].Trim()
        HwSerial = $lines[2].Trim()
        Brand    = $brand
        Battery  = $bat
        Charging = $charging
    }
}

function Get-PhoneWifiIp([string]$Serial) {
    $r = Invoke-Adb "-s $Serial shell ip route" 10
    foreach ($line in ($r.Out -split "\r?\n")) {
        if ($line -match 'dev\s+(\S+).*\bsrc\s+(\d{1,3}(\.\d{1,3}){3})') {
            if ($Matches[1] -like 'wlan*') { return $Matches[2] }
        }
    }
    $r = Invoke-Adb "-s $Serial shell ip -f inet addr show wlan0" 10
    if ($r.Out -match 'inet\s+(\d{1,3}(\.\d{1,3}){3})') { return $Matches[1] }
    return $null
}

function Find-SavedMatch([string]$Serial, [string]$Hw) {
    foreach ($d in $State.Devices) {
        if ($Hw -and $d.HwSerial -and $d.HwSerial -eq $Hw) { return $d }
    }
    foreach ($d in $State.Devices) {
        if ($d.Address) {
            $ip = Get-IpOf $d.Address
            if ($Serial -eq $d.Address -or $Serial -like "${ip}:*") { return $d }
        }
    }
    return $null
}

