try {
    Add-Type -TypeDefinition @"
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
public static class StudioLibs {
    static string _dir;
    [ThreadStatic] static HashSet<string> _busy;
    [DllImport("kernel32", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern IntPtr LoadLibrary(string path);

    public static void Install(string dir) {
        if (_dir != null) return;
        _dir = dir;
        AppDomain.CurrentDomain.AssemblyResolve += Resolve;
    }

    public static bool LoadNative(string path) {
        return LoadLibrary(path) != IntPtr.Zero;
    }

    static Assembly Resolve(object sender, ResolveEventArgs e) {
        string name = new AssemblyName(e.Name).Name;
        if (name.EndsWith(".resources") || name.EndsWith(".XmlSerializers")) return null;
        if (_busy == null) _busy = new HashSet<string>();
        if (_busy.Contains(name)) return null;
        _busy.Add(name);
        try {
            foreach (Assembly a in AppDomain.CurrentDomain.GetAssemblies()) {
                if (a.GetName().Name == name) return a;
            }
            string p = Path.Combine(_dir, name + ".dll");
            if (File.Exists(p)) return Assembly.LoadFrom(p);
#pragma warning disable 618
            try { return Assembly.LoadWithPartialName(name); } catch { return null; }
#pragma warning restore 618
        } finally {
            _busy.Remove(name);
        }
    }
}
"@
} catch { Write-Crash $_ }

function Import-AddOns {
    # A finished download waits in libs.new until the next start (loaded DLLs can't be replaced)
    $pending = Join-Path $Here 'libs.new'
    if (Test-Path -LiteralPath $pending) {
        for ($i = 0; $i -lt 12; $i++) {
            try {
                if (Test-Path -LiteralPath $LibDir) { Remove-Item -LiteralPath $LibDir -Recurse -Force }
                Rename-Item -LiteralPath $pending -NewName 'libs'
                break
            } catch { Start-Sleep -Milliseconds 500 }
        }
    }
    if (-not (Test-Path -LiteralPath $LibDir)) { return }
    try { [StudioLibs]::Install($LibDir) } catch { Write-Crash $_; return }
    $native = Join-Path $LibDir 'native'
    if (Test-Path -LiteralPath $native) {
        $env:Path = $native + ';' + $env:Path
        foreach ($n in @(Get-ChildItem -LiteralPath $native -Filter '*.dll' -ErrorAction SilentlyContinue)) {
            try { [void][StudioLibs]::LoadNative($n.FullName) } catch {}
        }
    }
    $flair = Join-Path $LibDir 'XamlFlair.WPF.dll'
    if (Test-Path -LiteralPath $flair) {
        try {
            [void][System.Reflection.Assembly]::LoadFrom($flair)
            if (-not ('XamlFlair.Animations' -as [type])) { throw 'XamlFlair.Animations type not found' }
            $App.HasFlair = $true
        } catch { Write-Crash $_ }
    }
    $lottie = Join-Path $LibDir 'LottieSharp.dll'
    if (Test-Path -LiteralPath $lottie) {
        try {
            foreach ($dep in 'SkiaSharp.dll', 'SkiaSharp.Views.WPF.dll', 'SkiaSharp.Skottie.dll') {
                $dp = Join-Path $LibDir $dep
                if (Test-Path -LiteralPath $dp) { [void][System.Reflection.Assembly]::LoadFrom($dp) }
            }
            [void][System.Reflection.Assembly]::LoadFrom($lottie)
            if (-not ('LottieSharp.WPF.LottieAnimationView' -as [type])) { throw 'LottieAnimationView type not found' }
            $App.HasLottie = $true
        } catch { Write-Crash $_ }
    }
}


