function Ensure-DefaultAnimations {
    try {
        if (-not (Test-Path -LiteralPath $AnimDir)) { [void](New-Item -ItemType Directory -Path $AnimDir -Force) }
        foreach ($k in $DefaultAnimations.Keys) {
            $p = Join-Path $AnimDir $k
            if (-not (Test-Path -LiteralPath $p)) { Set-Content -LiteralPath $p -Value $DefaultAnimations[$k] -Encoding ASCII }
        }
    } catch { Write-Crash $_ }
}

function Resolve-Scrcpy {
    $cands = @((Join-Path $Here 'scrcpy.exe'))
    if ($State.ScrcpyPath) { $cands += [string]$State.ScrcpyPath }
    foreach ($c in $cands) {
        if ($c -and (Test-Path -LiteralPath $c)) { return (Resolve-Path -LiteralPath $c).Path }
    }
    try {
        $parent = Split-Path $Here -Parent
        $f = Get-ChildItem -Path $parent -Filter 'scrcpy.exe' -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($f) { return $f.FullName }
    } catch {}
    $dlg = New-Object Microsoft.Win32.OpenFileDialog
    $dlg.Title = 'Where is scrcpy.exe? (inside your scrcpy-win64 folder)'
    $dlg.Filter = 'scrcpy.exe|scrcpy.exe'
    if ($dlg.ShowDialog() -eq $true) { return $dlg.FileName }
    return $null
}

