      <GradientStop Color="#1B1F28" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="GrStat" StartPoint="0,0" EndPoint="1,1">
      <GradientStop Color="#232A3A" Offset="0"/>
      <GradientStop Color="#1B1F28" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="GrIcon" StartPoint="0,0" EndPoint="1,1">
      <GradientStop Color="#33456F" Offset="0"/>
      <GradientStop Color="#2E2A52" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="GrSide" StartPoint="0,0" EndPoint="0,1">
      <GradientStop Color="#171B28" Offset="0"/>
      <GradientStop Color="#111318" Offset="1"/>
    </LinearGradientBrush>
    <LinearGradientBrush x:Key="GrNavSel" StartPoint="0,0" EndPoint="1,0">
      <GradientStop Color="#2A3A6C" Offset="0"/>
      <GradientStop Color="#232B4A" Offset="1"/>
    </LinearGradientBrush>
    <!-- XamlFlair entrance animations (only used when the add-on is installed) -->
    <xf:AnimationSettings x:Key="AnimFadeUp" Kind="FadeFrom,TranslateYFrom" Opacity="0" OffsetY="8" Duration="240"/>
    <xf:AnimationSettings x:Key="AnimPop" Kind="FadeFrom,ScaleXFrom,ScaleYFrom" Opacity="0" ScaleX="0.98" ScaleY="0.98" Duration="260"/>
    <xf:AnimationSettings x:Key="AnimFade" Kind="FadeFrom" Opacity="0" Duration="200"/>

    <LinearGradientBrush x:Key="GrBanner" StartPoint="0,0" EndPoint="1,1">
      <GradientStop Color="#26365F" Offset="0"/>
      <GradientStop Color="#2B2456" Offset="1"/>
    </LinearGradientBrush>

    <!-- Text -->
    <Style x:Key="H2" TargetType="TextBlock">
      <Setter Property="FontSize" Value="16"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
    </Style>
    <Style x:Key="Hint" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{StaticResource BrSub}"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="LineHeight" Value="19"/>
      <Setter Property="TextWrapping" Value="Wrap"/>
      <Setter Property="MaxWidth" Value="760"/>
      <Setter Property="HorizontalAlignment" Value="Left"/>
      <Setter Property="Margin" Value="0,4,0,0"/>
    </Style>
    <Style x:Key="Label" TargetType="TextBlock">
      <Setter Property="Foreground" Value="#B7BFCB"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
      <Setter Property="Margin" Value="0,14,0,6"/>
    </Style>
    <Style x:Key="IconText" TargetType="TextBlock">
      <Setter Property="FontFamily" Value="{StaticResource Icons}"/>
      <Setter Property="VerticalAlignment" Value="Center"/>
      <Setter Property="Margin" Value="0,1,8,0"/>
    </Style>

    <!-- =============================================================
         MOLECULES: single controls built from atoms
         (focus ring, buttons, nav item, switch, text box, combo box,
         slider, scrollbar, tooltip)
         ============================================================= -->
    <!-- Keyboard focus ring (shows only when using Tab / arrow keys) -->
    <Style x:Key="FocusRing">
      <Setter Property="Control.Template">
        <Setter.Value>
          <ControlTemplate>
            <Border Margin="-3" CornerRadius="11" BorderThickness="2" BorderBrush="#8FB0FF" SnapsToDevicePixels="True"/>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Buttons: smooth hover glow and press "squish" -->
    <Style x:Key="BtnBase" TargetType="Button">
      <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
      <Setter Property="Background" Value="{StaticResource BrCard2}"/>
      <Setter Property="BorderBrush" Value="{StaticResource BrLine}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="14,8"/>
      <Setter Property="FontWeight" Value="SemiBold"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Grid x:Name="root" RenderTransformOrigin="0.5,0.5">
              <Grid.RenderTransform>
                <ScaleTransform ScaleX="1" ScaleY="1"/>
              </Grid.RenderTransform>
              <Border x:Name="bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                      BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="9"/>
              <Border x:Name="hl" Background="White" CornerRadius="9" Opacity="0" IsHitTestVisible="False"/>
              <ContentPresenter Margin="{TemplateBinding Padding}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hl" Storyboard.TargetProperty="Opacity" To="0.09" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hl" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="root" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.97" Duration="0:0:0.08"/>
                      <DoubleAnimation Storyboard.TargetName="root" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.97" Duration="0:0:0.08"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="root" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.2">
                        <DoubleAnimation.EasingFunction>
                          <CubicEase EasingMode="EaseOut"/>
                        </DoubleAnimation.EasingFunction>
                      </DoubleAnimation>
                      <DoubleAnimation Storyboard.TargetName="root" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.2">
                        <DoubleAnimation.EasingFunction>
                          <CubicEase EasingMode="EaseOut"/>
                        </DoubleAnimation.EasingFunction>
                      </DoubleAnimation>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter TargetName="root" Property="Opacity" Value="0.4"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
      <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True">
          <Setter Property="BorderBrush" Value="#3C4454"/>
        </Trigger>
      </Style.Triggers>
    </Style>
    <Style x:Key="AccentBtn" TargetType="Button" BasedOn="{StaticResource BtnBase}">
      <Setter Property="Background" Value="{StaticResource GrAccent}"/>
      <Setter Property="BorderBrush" Value="#00000000"/>
      <Setter Property="Foreground" Value="#FFFFFE"/>
      <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True">
          <Setter Property="BorderBrush" Value="#00000000"/>
        </Trigger>
      </Style.Triggers>
    </Style>
    <Style x:Key="BigAccentBtn" TargetType="Button" BasedOn="{StaticResource AccentBtn}">
      <Setter Property="Padding" Value="22,12"/>
      <Setter Property="FontSize" Value="14"/>
    </Style>
    <Style x:Key="DangerBtn" TargetType="Button" BasedOn="{StaticResource BtnBase}">
      <Setter Property="Background" Value="#33FF5C6C"/>
      <Setter Property="BorderBrush" Value="#55FF5C6C"/>
      <Setter Property="Foreground" Value="#FF8A95"/>
    </Style>
    <Style x:Key="GhostBtn" TargetType="Button" BasedOn="{StaticResource BtnBase}">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="BorderBrush" Value="Transparent"/>
      <Setter Property="Padding" Value="10,6"/>
      <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True">
          <Setter Property="BorderBrush" Value="Transparent"/>
        </Trigger>
      </Style.Triggers>
    </Style>
    <Style x:Key="IconBtn" TargetType="Button" BasedOn="{StaticResource GhostBtn}">
      <Setter Property="FontFamily" Value="{StaticResource Icons}"/>
      <Setter Property="FontWeight" Value="Normal"/>
      <Setter Property="FontSize" Value="14"/>
      <Setter Property="Padding" Value="9"/>
      <Setter Property="Foreground" Value="{StaticResource BrSub}"/>
    </Style>

    <!-- Sidebar navigation: selection fades in, accent bar grows -->
    <Style x:Key="NavBtn" TargetType="RadioButton">
      <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
      <Setter Property="Foreground" Value="{StaticResource BrSub}"/>
      <Setter Property="FontSize" Value="14"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Margin" Value="12,2"/>
      <Setter Property="GroupName" Value="nav"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="RadioButton">
            <Grid>
              <Border x:Name="sel" Background="{StaticResource GrNavSel}" CornerRadius="9" Opacity="0"/>
              <Border x:Name="hl" Background="White" CornerRadius="9" Opacity="0"/>
              <Border Background="Transparent" Padding="14,10">
                <Grid>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock x:Name="ico" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" FontSize="16" VerticalAlignment="Center" Margin="0,0,14,0"
                               Text="{Binding Tag, RelativeSource={RelativeSource TemplatedParent}}"/>
                    <ContentPresenter VerticalAlignment="Center"/>
                  </StackPanel>
                </Grid>
              </Border>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hl" Storyboard.TargetProperty="Opacity" To="0.05" Duration="0:0:0.15"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="hl" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsChecked" Value="True">
                <Setter Property="Foreground" Value="#FFFFFF"/>
                <Setter TargetName="ico" Property="Foreground" Value="#9DB8FF"/>
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="sel" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="sel" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.15"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Toggle switch: knob slides, colour fades -->
    <Style TargetType="CheckBox">
      <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Margin" Value="0,7"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="CheckBox">
            <Grid Background="Transparent">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Grid Width="40" Height="22" VerticalAlignment="Center">
                <Border CornerRadius="11" Background="#252B36" BorderBrush="#3A4150" BorderThickness="1"/>
                <Border x:Name="on" CornerRadius="11" Background="{StaticResource GrAccent}" Opacity="0"/>
                <Grid x:Name="knob" Width="14" Height="14" HorizontalAlignment="Left" Margin="4,0,0,0">
                  <Grid.RenderTransform>
                    <TranslateTransform X="0"/>
                  </Grid.RenderTransform>
                  <Ellipse Fill="#9AA3AF"/>
                  <Ellipse x:Name="knobOn" Fill="White" Opacity="0"/>
                </Grid>
              </Grid>
              <ContentPresenter Grid.Column="1" Margin="12,0,0,0" VerticalAlignment="Center"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Trigger.EnterActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="knob" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="18" Duration="0:0:0.2">
                        <DoubleAnimation.EasingFunction>
                          <CubicEase EasingMode="EaseOut"/>
                        </DoubleAnimation.EasingFunction>
                      </DoubleAnimation>
                      <DoubleAnimation Storyboard.TargetName="on" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.2"/>
                      <DoubleAnimation Storyboard.TargetName="knobOn" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.2"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.EnterActions>
                <Trigger.ExitActions>
                  <BeginStoryboard>
                    <Storyboard>
                      <DoubleAnimation Storyboard.TargetName="knob" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="0" Duration="0:0:0.18">
                        <DoubleAnimation.EasingFunction>
                          <CubicEase EasingMode="EaseOut"/>
                        </DoubleAnimation.EasingFunction>
                      </DoubleAnimation>
                      <DoubleAnimation Storyboard.TargetName="on" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.18"/>
                      <DoubleAnimation Storyboard.TargetName="knobOn" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.18"/>
                    </Storyboard>
                  </BeginStoryboard>
                </Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.4"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Text box -->
    <Style TargetType="TextBox">
      <Setter Property="Background" Value="{StaticResource BrField}"/>
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
      <Setter Property="BorderBrush" Value="{StaticResource BrLine}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="9,7"/>
      <Setter Property="CaretBrush" Value="{StaticResource BrText}"/>
      <Setter Property="SelectionBrush" Value="{StaticResource BrAccent}"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TextBox">
            <Border x:Name="bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="9">
              <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}"
                            VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="bd" Property="BorderBrush" Value="#3C4454"/>
              </Trigger>
              <Trigger Property="IsKeyboardFocused" Value="True">
                <Setter TargetName="bd" Property="BorderBrush" Value="#5B8CFF"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter TargetName="bd" Property="Opacity" Value="0.5"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Combo box -->
    <Style TargetType="ComboBoxItem">
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
      <Setter Property="Padding" Value="10,7"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ComboBoxItem">
            <Border x:Name="bd" Background="Transparent" CornerRadius="6" Padding="{TemplateBinding Padding}" Margin="4,1">
              <ContentPresenter/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsSelected" Value="True">
                <Setter TargetName="bd" Property="Background" Value="#24304A"/>
              </Trigger>
              <Trigger Property="IsHighlighted" Value="True">
                <Setter TargetName="bd" Property="Background" Value="#2A3140"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style TargetType="ComboBox">
      <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
      <Setter Property="Foreground" Value="{StaticResource BrText}"/>
      <Setter Property="Height" Value="36"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ComboBox">
            <Grid>
              <ToggleButton Focusable="False" ClickMode="Press"
                            IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                <ToggleButton.Template>
                  <ControlTemplate TargetType="ToggleButton">
                    <Border x:Name="b" Background="#11141A" BorderBrush="#2A303B" BorderThickness="1" CornerRadius="9">
                      <TextBlock FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" Text="&#xE70D;" FontSize="10" Foreground="#9AA3AF"
                                 HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,12,0"/>
                    </Border>
                    <ControlTemplate.Triggers>
                      <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="b" Property="BorderBrush" Value="#3C4454"/>
                      </Trigger>
                      <Trigger Property="IsChecked" Value="True">
                        <Setter TargetName="b" Property="BorderBrush" Value="#5B8CFF"/>
                      </Trigger>
                    </ControlTemplate.Triggers>
                  </ControlTemplate>
                </ToggleButton.Template>
              </ToggleButton>
              <ContentPresenter IsHitTestVisible="False" Margin="11,0,30,0" VerticalAlignment="Center" HorizontalAlignment="Left"
                                Content="{TemplateBinding SelectionBoxItem}"
                                ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"/>
              <Popup x:Name="PART_Popup" Placement="Bottom" AllowsTransparency="True" Focusable="False" PopupAnimation="Slide"
                     IsOpen="{Binding IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}}">
                <Border Background="#1B1F27" BorderBrush="#2F3642" BorderThickness="1" CornerRadius="9" Margin="0,4,0,0" Padding="0,4"
                        MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}" MaxHeight="340">
                  <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                    <ItemsPresenter/>
                  </ScrollViewer>
                </Border>
              </Popup>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.45"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Slider -->
    <Style TargetType="Slider">
      <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Slider">
            <Grid Height="24">
              <Border Height="4" CornerRadius="2" Background="#2A303B" VerticalAlignment="Center"/>
              <Track x:Name="PART_Track" Orientation="Horizontal">
                <Track.DecreaseRepeatButton>
                  <RepeatButton Command="{x:Static Slider.DecreaseLarge}">
                    <RepeatButton.Template>
                      <ControlTemplate TargetType="RepeatButton">
                        <Border Height="4" CornerRadius="2" Background="{StaticResource GrAccent}" VerticalAlignment="Center"/>
                      </ControlTemplate>
                    </RepeatButton.Template>
                  </RepeatButton>
                </Track.DecreaseRepeatButton>
                <Track.IncreaseRepeatButton>
                  <RepeatButton Command="{x:Static Slider.IncreaseLarge}">
                    <RepeatButton.Template>
                      <ControlTemplate TargetType="RepeatButton">
                        <Border Background="Transparent"/>
                      </ControlTemplate>
                    </RepeatButton.Template>
                  </RepeatButton>
                </Track.IncreaseRepeatButton>
                <Track.Thumb>
                  <Thumb>
                    <Thumb.Template>
                      <ControlTemplate TargetType="Thumb">
                        <Ellipse Width="18" Height="18" Fill="White" Stroke="#8B7CFF" StrokeThickness="4"/>
                      </ControlTemplate>
                    </Thumb.Template>
                  </Thumb>
                </Track.Thumb>
              </Track>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- Thin scrollbars -->
    <Style TargetType="ScrollBar">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Width" Value="10"/>
      <Setter Property="MinWidth" Value="10"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollBar">
            <Track x:Name="PART_Track" Orientation="Vertical" IsDirectionReversed="True">
              <Track.Thumb>
                <Thumb>
                  <Thumb.Template>
                    <ControlTemplate TargetType="Thumb">
                      <Border Background="#343B48" CornerRadius="4" Margin="2"/>
                    </ControlTemplate>
                  </Thumb.Template>
                </Thumb>
              </Track.Thumb>
            </Track>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
      <Style.Triggers>
        <Trigger Property="Orientation" Value="Horizontal">
          <Setter Property="Width" Value="Auto"/>
          <Setter Property="MinWidth" Value="0"/>
          <Setter Property="Height" Value="10"/>
          <Setter Property="MinHeight" Value="10"/>
          <Setter Property="Template">
            <Setter.Value>
              <ControlTemplate TargetType="ScrollBar">
                <Track x:Name="PART_Track" Orientation="Horizontal">
                  <Track.Thumb>
                    <Thumb>
                      <Thumb.Template>
                        <ControlTemplate TargetType="Thumb">
                          <Border Background="#343B48" CornerRadius="4" Margin="2"/>
                        </ControlTemplate>
                      </Thumb.Template>
                    </Thumb>
                  </Track.Thumb>
                </Track>
              </ControlTemplate>
            </Setter.Value>
          </Setter>
        </Trigger>
      </Style.Triggers>
    </Style>

    <Style TargetType="ToolTip">
      <Setter Property="Foreground" Value="#E8EAED"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="MaxWidth" Value="320"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ToolTip">
            <Border Background="#262C38" BorderBrush="#3A4150" BorderThickness="1" CornerRadius="8" Padding="10,6">
              <ContentPresenter>
                <ContentPresenter.Resources>
                  <Style TargetType="TextBlock">
                    <Setter Property="TextWrapping" Value="Wrap"/>
                  </Style>
                </ContentPresenter.Resources>
              </ContentPresenter>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <!-- =============================================================
         ORGANISMS: groups of molecules. CardBox is the section card;
         rows, session rows and media tiles are built in code
         (New-Row, Add-SessionRow, Render-Saved, Render-Detected).
         TEMPLATE: sidebar (236) + page header + scrolling page (32 padding).
         PAGES: PageHome, PageDevices, PageGaming, PageMedia, PageSettings.
         ============================================================= -->
    <!-- Card -->
    <Style x:Key="CardBox" TargetType="Border">
      <Setter Property="Background" Value="{StaticResource GrCard}"/>
      <Setter Property="BorderBrush" Value="{StaticResource GrCardLine}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="CornerRadius" Value="14"/>
      <Setter Property="Padding" Value="20"/>
      <Setter Property="Margin" Value="0,0,0,16"/>
    </Style>
  </Window.Resources>

  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="236"/>
      <ColumnDefinition Width="*"/>
    </Grid.ColumnDefinitions>

    <!-- Background glows -->
    <Border Grid.ColumnSpan="2" IsHitTestVisible="False">
      <Border.Background>
        <RadialGradientBrush Center="0.95,0" GradientOrigin="0.95,0" RadiusX="0.6" RadiusY="0.75">
          <GradientStop Color="#336A4CFF" Offset="0"/>
          <GradientStop Color="#006A4CFF" Offset="1"/>
        </RadialGradientBrush>
      </Border.Background>
    </Border>
    <Border Grid.ColumnSpan="2" IsHitTestVisible="False">
      <Border.Background>
        <RadialGradientBrush Center="0.35,1.05" GradientOrigin="0.35,1.05" RadiusX="0.55" RadiusY="0.6">
          <GradientStop Color="#2A3D7BFF" Offset="0"/>
          <GradientStop Color="#003D7BFF" Offset="1"/>
        </RadialGradientBrush>
      </Border.Background>
    </Border>

    <!-- ===================== SIDEBAR ===================== -->
    <Border Background="{StaticResource GrSide}" BorderBrush="{StaticResource BrLine}" BorderThickness="0,0,1,0">
      <DockPanel>
        <StackPanel DockPanel.Dock="Top" Orientation="Horizontal" Margin="22,24,16,28">
          <Border Width="40" Height="40" CornerRadius="11" Background="{StaticResource GrAccent}">
            <Grid>
              <TextBlock x:Name="LogoGlyph" FontFamily="{StaticResource Icons}" Text="&#xE8EA;" FontSize="19" Foreground="#FFFFFE"
                         HorizontalAlignment="Center" VerticalAlignment="Center"/>
              <Image x:Name="LogoImg" Width="26" Height="26"/>
            </Grid>
          </Border>
          <StackPanel Margin="12,0,0,0" VerticalAlignment="Center">
            <TextBlock Text="Scrcpy Flow" FontSize="16" FontWeight="SemiBold"/>
            <TextBlock x:Name="SideVersion" Text="starting..." FontSize="12" Foreground="{StaticResource BrSub}" Margin="0,2,0,0"/>
          </StackPanel>
        </StackPanel>

        <Border DockPanel.Dock="Bottom" Margin="14,0,14,16" Padding="14,12" CornerRadius="11" Background="#171B22"
                BorderBrush="{StaticResource BrLine}" BorderThickness="1">
          <StackPanel>
            <StackPanel Orientation="Horizontal">
              <Ellipse x:Name="AdbDot" Width="8" Height="8" Fill="#9AA3AF" VerticalAlignment="Center"/>
              <TextBlock x:Name="AdbText" Text="Starting adb..." Margin="9,0,0,0" FontSize="12" Foreground="{StaticResource BrSub}"/>
            </StackPanel>
            <StackPanel Orientation="Horizontal" Margin="0,6,0,0">
              <Ellipse x:Name="MirrorDot" Width="8" Height="8" Fill="#6B7380" VerticalAlignment="Center"/>
              <TextBlock x:Name="SideSessions" Text="Nothing running" Margin="9,0,0,0" FontSize="12" Foreground="{StaticResource BrSub}"/>
            </StackPanel>
          </StackPanel>
        </Border>

        <StackPanel>
          <RadioButton x:Name="NavHome" Style="{StaticResource NavBtn}" Tag="&#xE80F;" Content="Home" IsChecked="True"/>
          <RadioButton x:Name="NavDevices" Style="{StaticResource NavBtn}" Tag="&#xE8EA;" Content="Devices"/>
          <RadioButton x:Name="NavGaming" Style="{StaticResource NavBtn}" Tag="&#xE7FC;" Content="Game Mode"/>
          <RadioButton x:Name="NavMedia" Style="{StaticResource NavBtn}" Tag="&#xE714;" Content="Recordings"/>
          <RadioButton x:Name="NavSettings" Style="{StaticResource NavBtn}" Tag="&#xE713;" Content="Settings"/>
        </StackPanel>
      </DockPanel>
    </Border>

    <!-- ===================== MAIN ===================== -->
    <Grid Grid.Column="1">
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
      </Grid.RowDefinitions>

      <Grid Margin="32,24,32,14">
        <StackPanel>
          <TextBlock x:Name="PageTitle" Text="Home" FontSize="28" FontWeight="SemiBold" Foreground="#FFFFFC"/>
          <TextBlock x:Name="PageSub" Text="" FontSize="14" Foreground="#FFFFFB" Margin="0,4,0,0"/>
        </StackPanel>
        <Border HorizontalAlignment="Right" VerticalAlignment="Center" CornerRadius="16" Padding="14,7"
                Background="#181C23" BorderBrush="{StaticResource BrLine}" BorderThickness="1">
          <StackPanel Orientation="Horizontal">
            <Ellipse x:Name="StatusDot" Width="8" Height="8" Fill="#9AA3AF" VerticalAlignment="Center"/>
            <TextBlock x:Name="StatusText" Text="Starting..." Margin="9,0,0,0" FontSize="12" MaxWidth="320" TextTrimming="CharacterEllipsis"/>
          </StackPanel>
        </Border>
      </Grid>

      <Grid Grid.Row="1">

        <!-- ===================== HOME ===================== -->
        <ScrollViewer x:Name="PageHome" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel Margin="32,4,32,32">
            <Border x:Name="HomeEmptyBanner" Background="{StaticResource GrBanner}" BorderBrush="#3A4F8A" BorderThickness="1" CornerRadius="14" Padding="16,14" Margin="0,0,0,16" Visibility="Collapsed">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="Auto"/>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock FontFamily="{StaticResource Icons}" Text="&#xED14;" FontSize="22" Foreground="#9DB8FF" VerticalAlignment="Center" Margin="0,0,14,0"/>
                <StackPanel Grid.Column="1" VerticalAlignment="Center">
                  <TextBlock Text="No phone added yet" FontWeight="SemiBold"/>
                  <TextBlock Text="Add your phone by scanning a QR code. No cable needed." Style="{StaticResource Hint}"/>
                </StackPanel>
                <Button x:Name="BtnHomeAdd" Grid.Column="2" Style="{StaticResource AccentBtn}" Content="Add phone" Margin="12,0,0,0" VerticalAlignment="Center"/>
              </Grid>
            </Border>

            <!-- Hero: current phone + big start button -->
            <Border CornerRadius="18" Padding="26,24" Margin="0,0,0,16" BorderBrush="#3A4A7A" BorderThickness="1"
                    xf:Animations.Primary="{StaticResource AnimPop}">
              <Border.Background>
                <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                  <GradientStop Color="#263866" Offset="0"/>
                  <GradientStop Color="#1D2344" Offset="0.55"/>
                  <GradientStop Color="#2C2052" Offset="1"/>
                </LinearGradientBrush>
              </Border.Background>
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <Border Width="54" Height="54" CornerRadius="15" Background="{StaticResource GrAccent}">
                      <TextBlock FontFamily="{StaticResource Icons}" Text="&#xE8EA;" FontSize="25" Foreground="#FFFFFE"
                                 HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <StackPanel Margin="16,0,0,0" VerticalAlignment="Center">
                      <TextBlock x:Name="InfoName" Text="No phone" FontSize="24" FontWeight="SemiBold" Foreground="#FFFFFD"
                                 TextTrimming="CharacterEllipsis" MaxWidth="440"/>
                      <TextBlock x:Name="InfoAddr" Text="" Foreground="#B9C3E6" FontSize="12" Margin="0,3,0,0"
                                 TextTrimming="CharacterEllipsis" MaxWidth="460"/>
                    </StackPanel>
                    <Button x:Name="BtnRefreshInfo" Style="{StaticResource IconBtn}" Content="&#xE72C;" Foreground="#B9C3E6"
                            Margin="8,0,0,0" VerticalAlignment="Center" ToolTip="Refresh phone info"/>
                  </StackPanel>
                  <WrapPanel Margin="0,20,0,0">
                    <Border Background="#1FFFFFFF" CornerRadius="12" Padding="14,9" Margin="0,0,10,10" MinWidth="110">
                      <StackPanel>
                        <TextBlock Text="Battery" FontSize="12" Foreground="#B4C0E6"/>
                        <TextBlock x:Name="InfoBattery" Text="-" FontSize="16" FontWeight="SemiBold" Foreground="#FFFFFD" Margin="0,2,0,0"/>
                      </StackPanel>
                    </Border>
                    <Border Background="#1FFFFFFF" CornerRadius="12" Padding="14,9" Margin="0,0,10,10" MinWidth="110">
                      <StackPanel>
                        <TextBlock Text="Android" FontSize="12" Foreground="#B4C0E6"/>
                        <TextBlock x:Name="InfoAndroid" Text="-" FontSize="16" FontWeight="SemiBold" Foreground="#FFFFFD" Margin="0,2,0,0"/>
                      </StackPanel>
                    </Border>
                    <Border Background="#1FFFFFFF" CornerRadius="12" Padding="14,9" Margin="0,0,10,10" MinWidth="110">
                      <StackPanel>
                        <TextBlock Text="Connection" FontSize="12" Foreground="#B4C0E6"/>
                        <TextBlock x:Name="InfoConn" Text="-" FontSize="16" FontWeight="SemiBold" Foreground="#FFFFFD" Margin="0,2,0,0"/>
                      </StackPanel>
                    </Border>
                    <Border Background="#1FFFFFFF" CornerRadius="12" Padding="14,9" Margin="0,0,10,10" MinWidth="110">
                      <StackPanel>
                        <TextBlock Text="Profile" FontSize="12" Foreground="#B4C0E6"/>
                        <TextBlock x:Name="InfoProfile" Text="-" FontSize="16" FontWeight="SemiBold" Foreground="#FFFFFD" Margin="0,2,0,0"
                                   TextTrimming="CharacterEllipsis" MaxWidth="160"/>
                      </StackPanel>
                    </Border>
                  </WrapPanel>
                </StackPanel>
                <StackPanel Grid.Column="1" VerticalAlignment="Center" Margin="24,0,0,0">
                  <Button x:Name="BtnStart" Style="{StaticResource BigAccentBtn}" Padding="30,16">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Style="{StaticResource IconText}" Text="&#xE768;" FontSize="16"/>
                      <TextBlock Text="Start mirroring" FontSize="15"/>
                    </StackPanel>
                  </Button>
                  <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,10,0,0">
                    <Button x:Name="BtnShot" Style="{StaticResource GhostBtn}" Foreground="#D6DCF5" ToolTip="Save a screenshot of the phone">
                      <StackPanel Orientation="Horizontal">
                        <TextBlock Style="{StaticResource IconText}" Text="&#xE722;"/>
                        <TextBlock Text="Screenshot"/>
                      </StackPanel>
                    </Button>
                    <Button x:Name="BtnWireless" Style="{StaticResource GhostBtn}" Foreground="#D6DCF5"
                            ToolTip="Plug in by USB first. Switches the phone to Wi-Fi and starts mirroring.">
                      <StackPanel Orientation="Horizontal">
                        <TextBlock Style="{StaticResource IconText}" Text="&#xE701;"/>
                        <TextBlock Text="USB to Wi-Fi"/>
                      </StackPanel>
                    </Button>
                  </StackPanel>
                </StackPanel>
              </Grid>
            </Border>

            <!-- Pickers -->
            <Border Style="{StaticResource CardBox}" Padding="20,8,20,18" xf:Animations.Primary="{StaticResource AnimFadeUp}">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="16"/>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="20"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel>
                  <TextBlock Text="Phone" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="HomeDevice"/>
                </StackPanel>
                <StackPanel Grid.Column="2">
                  <TextBlock Text="Profile" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="HomeProfile"/>
                </StackPanel>
                <StackPanel Grid.Column="4" VerticalAlignment="Bottom">
                  <CheckBox x:Name="HomeRecord" Content="Record this session" Margin="0,4,0,4"/>
                  <CheckBox x:Name="HomeBackground" Content="Record in background" IsEnabled="False" Margin="0,4,0,0"
                            ToolTip="Records without opening a phone window. Saved as MKV."/>
                </StackPanel>
              </Grid>
            </Border>

            <Border Style="{StaticResource CardBox}" xf:Animations.Primary="{StaticResource AnimFadeUp}">
              <StackPanel>
                <StackPanel Orientation="Horizontal">
                  <TextBlock Style="{StaticResource IconText}" Text="&#xE7F4;" Foreground="#3DDC97" FontSize="15"/>
                  <TextBlock Text="Running now" Style="{StaticResource H2}"/>
                  <Border x:Name="SessionCountBadge" Background="{StaticResource GrAccent}" CornerRadius="8" Padding="8,1" Margin="10,0,0,0" VerticalAlignment="Center">
                    <TextBlock x:Name="SessionCount" Text="0" FontSize="11" FontWeight="SemiBold" Foreground="#FFFFFE"/>
                  </Border>
                </StackPanel>
                <StackPanel x:Name="SessionEmpty" Orientation="Horizontal" Margin="0,8,0,0">
                  <Grid x:Name="SessionIdleHost" Width="64" Height="64" Margin="0,0,12,0" Visibility="Collapsed"/>
                  <TextBlock Text="Nothing is mirroring. Press Start mirroring above, or start from Flow Connect on your phone." Style="{StaticResource Hint}" VerticalAlignment="Center" Margin="0"/>
                </StackPanel>
                <StackPanel x:Name="SessionList" Margin="0,4,0,0"/>
              </StackPanel>
            </Border>

            <Border Style="{StaticResource CardBox}" xf:Animations.Primary="{StaticResource AnimFadeUp}">
              <StackPanel>
                <Grid>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE9D9;" Foreground="#9DB8FF" FontSize="15"/>
                    <TextBlock Text="Activity" Style="{StaticResource H2}"/>
                  </StackPanel>
                  <Button x:Name="BtnClearLog" Style="{StaticResource GhostBtn}" Content="Clear" HorizontalAlignment="Right" Margin="0,-6,-6,0"/>
                </Grid>
                <TextBox x:Name="LogBox" Height="190" Margin="0,10,0,0" IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True"
                         VerticalScrollBarVisibility="Auto" VerticalContentAlignment="Top" Background="#0E1116"
                         FontFamily="Cascadia Mono, Consolas" FontSize="12" Foreground="#B9C0CA"/>
              </StackPanel>
            </Border>
          </StackPanel>
        </ScrollViewer>

        <!-- ===================== DEVICES ===================== -->
        <ScrollViewer x:Name="PageDevices" Visibility="Collapsed" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel Margin="32,4,32,32">
            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <TextBlock Text="Saved phones" Style="{StaticResource H2}"/>
                <TextBlock Text="Each phone has its own profile. The star marks your default phone. The download button installs Flow Connect, which turns Wireless debugging on with one tap and keeps it on after restarts." Style="{StaticResource Hint}"/>
                <TextBlock x:Name="SavedEmpty" Text="No saved phones yet. Use the QR code below to add one." Style="{StaticResource Hint}" Margin="0,12,0,0"/>
                <StackPanel x:Name="SavedList" Margin="0,6,0,0"/>
              </StackPanel>
            </Border>

            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <Grid>
                  <StackPanel Margin="0,0,140,0">
                    <TextBlock Text="Found right now" Style="{StaticResource H2}"/>
                    <TextBlock Text="Phones plugged in by USB, connected over Wi-Fi, or nearby with Wireless debugging turned on." Style="{StaticResource Hint}"/>
                  </StackPanel>
                  <Button x:Name="BtnScan" Style="{StaticResource BtnBase}" HorizontalAlignment="Right" VerticalAlignment="Top">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Style="{StaticResource IconText}" Text="&#xE72C;"/>
                      <TextBlock Text="Scan"/>
                    </StackPanel>
                  </Button>
                </Grid>
                <TextBlock x:Name="DetectEmpty" Text="No phones found. Plug one in by USB, or turn on Wireless debugging, then click Scan." Style="{StaticResource Hint}" Margin="0,12,0,0"/>
                <StackPanel x:Name="DetectList" Margin="0,6,0,0"/>
              </StackPanel>
            </Border>

            <Border x:Name="QrCard" Style="{StaticResource CardBox}">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="Auto"/>
                  <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <Border Width="216" Height="216" CornerRadius="14" Background="{StaticResource GrStat}" BorderBrush="{StaticResource BrLine}" BorderThickness="1" VerticalAlignment="Top">
                  <Grid>
                    <StackPanel x:Name="QrPlaceholder" VerticalAlignment="Center" HorizontalAlignment="Center">
                      <TextBlock FontFamily="{StaticResource Icons}" Text="&#xED14;" FontSize="44" Foreground="#5B8CFF" HorizontalAlignment="Center"/>
                      <TextBlock Text="QR code appears here" Foreground="{StaticResource BrSub}" FontSize="12" Margin="0,12,0,0" HorizontalAlignment="Center"/>
                    </StackPanel>
                    <Border x:Name="QrFrame" Background="White" CornerRadius="12" Margin="6" Visibility="Collapsed">
                      <Image x:Name="QrImg" Stretch="Uniform" Margin="2" RenderOptions.BitmapScalingMode="NearestNeighbor"/>
                    </Border>
                  </Grid>
                </Border>
                <StackPanel Grid.Column="1" Margin="24,0,0,0">
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Text="Add a phone without a cable" Style="{StaticResource H2}" FontSize="17"/>
                    <Border Background="#263DDC97" CornerRadius="7" Padding="8,2" Margin="10,0,0,0" VerticalAlignment="Center">
                      <TextBlock Text="Android 11+" FontSize="11" FontWeight="SemiBold" Foreground="#3DDC97"/>
                    </Border>
                  </StackPanel>
                  <TextBlock Text="Phone and PC must be on the same Wi-Fi. You only do this once per phone." Style="{StaticResource Hint}"/>
                  <Grid Margin="0,14,0,0">
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="28"/>
                      <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <Grid.RowDefinitions>
                      <RowDefinition Height="Auto"/>
                      <RowDefinition Height="Auto"/>
                      <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>
                    <TextBlock Text="1" FontWeight="SemiBold" Foreground="#8FB0FF" Margin="0,0,0,10"/>
                    <TextBlock Grid.Column="1" TextWrapping="Wrap" Margin="0,0,0,10" LineHeight="20" Foreground="#C9CFD8">
                      <Run Text="Settings &gt; About phone: tap "/>
                      <Run Text="OS version" FontWeight="SemiBold" Foreground="#E8EAED"/>
                      <Run Text=" (or Build number) 7 times to unlock Developer options."/>
                    </TextBlock>
                    <TextBlock Grid.Row="1" Text="2" FontWeight="SemiBold" Foreground="#8FB0FF" Margin="0,0,0,10"/>
                    <TextBlock Grid.Row="1" Grid.Column="1" TextWrapping="Wrap" Margin="0,0,0,10" LineHeight="20" Foreground="#C9CFD8">
                      <Run Text="In Developer options, turn on "/>
                      <Run Text="Wireless debugging" FontWeight="SemiBold" Foreground="#E8EAED"/>
                      <Run Text=". Xiaomi, Redmi and POCO: also turn on USB debugging (Security settings) so you can control the phone."/>
                    </TextBlock>
                    <TextBlock Grid.Row="2" Text="3" FontWeight="SemiBold" Foreground="#8FB0FF"/>
                    <TextBlock Grid.Row="2" Grid.Column="1" TextWrapping="Wrap" LineHeight="20" Foreground="#C9CFD8">
                      <Run Text="Click "/>
                      <Run Text="Show QR code" FontWeight="SemiBold" Foreground="#E8EAED"/>
                      <Run Text=" below, then on the phone tap Wireless debugging &gt; "/>
                      <Run Text="Pair device with QR code" FontWeight="SemiBold" Foreground="#E8EAED"/>
                      <Run Text=" and scan it."/>
                    </TextBlock>
                  </Grid>
                  <StackPanel Orientation="Horizontal" Margin="0,18,0,0">
                    <Button x:Name="BtnQrStart" Style="{StaticResource AccentBtn}">
                      <StackPanel Orientation="Horizontal">
                        <TextBlock Style="{StaticResource IconText}" Text="&#xED14;"/>
                        <TextBlock Text="Show QR code"/>
                      </StackPanel>
                    </Button>
                    <Button x:Name="BtnQrCancel" Style="{StaticResource GhostBtn}" Content="Cancel" Margin="8,0,0,0" Visibility="Collapsed"/>
                  </StackPanel>
                  <StackPanel x:Name="QrStatusRow" Orientation="Horizontal" Margin="0,12,0,0" Visibility="Collapsed">
                    <Ellipse x:Name="QrDot" Width="8" Height="8" Fill="#5B8CFF" VerticalAlignment="Center"/>
                    <TextBlock x:Name="QrStatus" Text="" Margin="9,0,0,0" TextWrapping="Wrap" MaxWidth="520" Foreground="#C9CFD8"/>
                  </StackPanel>
                </StackPanel>
              </Grid>
            </Border>

            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <TextBlock Text="Other ways to add a phone" Style="{StaticResource H2}"/>
                <Grid Margin="0,14,0,0">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="0"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="0"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <Border BorderBrush="{StaticResource BrLine}" BorderThickness="0" Padding="0,4,20,4">
                    <StackPanel>
                      <TextBlock FontFamily="{StaticResource Icons}" Text="&#xE88E;" FontSize="20" Foreground="#9DB8FF"/>
                      <TextBlock Text="With a USB cable" FontWeight="SemiBold" Margin="0,10,0,0"/>
                      <TextBlock Text="Turn on USB debugging, plug in, tap Allow on the phone, then click below. Works on any Android." Style="{StaticResource Hint}"/>
                      <Button x:Name="BtnAddUsb" Style="{StaticResource AccentBtn}" Content="Go wireless" HorizontalAlignment="Left" Margin="0,14,0,0"/>
                    </StackPanel>
                  </Border>
                  <Border Grid.Column="2" BorderBrush="{StaticResource BrLine}" BorderThickness="1,0,0,0" Padding="20,4,20,4">
                    <StackPanel>
                      <TextBlock FontFamily="{StaticResource Icons}" Text="&#xE71B;" FontSize="20" Foreground="#9DB8FF"/>
                      <TextBlock Text="Pairing code (no cable)" FontWeight="SemiBold" Margin="0,10,0,0"/>
                      <TextBlock Text="If the QR scan does not work: Wireless debugging &gt; Pair device with pairing code." Style="{StaticResource Hint}"/>
                      <TextBlock Text="IP address and port" Style="{StaticResource Label}"/>
                      <TextBox x:Name="PairAddr"/>
                      <TextBlock Text="6-digit code" Style="{StaticResource Label}"/>
                      <TextBox x:Name="PairCode" MaxLength="6"/>
                      <Button x:Name="BtnPair" Style="{StaticResource AccentBtn}" Content="Pair and connect" HorizontalAlignment="Left" Margin="0,14,0,0"/>
                    </StackPanel>
                  </Border>
                  <Border Grid.Column="4" BorderBrush="{StaticResource BrLine}" BorderThickness="1,0,0,0" Padding="20,4,0,4">
                    <StackPanel>
                      <TextBlock FontFamily="{StaticResource Icons}" Text="&#xE774;" FontSize="20" Foreground="#9DB8FF"/>
                      <TextBlock Text="By IP address" FontWeight="SemiBold" Margin="0,10,0,0"/>
                      <TextBlock Text="For a phone that is already in wireless mode." Style="{StaticResource Hint}"/>
                      <TextBlock Text="Name" Style="{StaticResource Label}"/>
                      <TextBox x:Name="AddName"/>
                      <TextBlock Text="IP address (optional :port)" Style="{StaticResource Label}"/>
                      <TextBox x:Name="AddAddr"/>
                      <Button x:Name="BtnAddIp" Style="{StaticResource AccentBtn}" Content="Save phone" HorizontalAlignment="Left" Margin="0,14,0,0"/>
                    </StackPanel>
                  </Border>
                </Grid>
              </StackPanel>
            </Border>
          </StackPanel>
        </ScrollViewer>

        <!-- ===================== GAME MODE ===================== -->
        <ScrollViewer x:Name="PageGaming" Visibility="Collapsed" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel Margin="32,4,32,32">
            <Border CornerRadius="16" Padding="24" Margin="0,0,0,16" BorderBrush="#3A3F6B" BorderThickness="1"
                    xf:Animations.Primary="{StaticResource AnimPop}">
              <Border.Background>
                <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                  <GradientStop Color="#2B2560" Offset="0"/>
                  <GradientStop Color="#16243F" Offset="1"/>
                </LinearGradientBrush>
              </Border.Background>
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="Auto"/>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <Border Width="64" Height="64" CornerRadius="16" Background="#33FFFFFF" VerticalAlignment="Center">
                  <TextBlock FontFamily="{StaticResource Icons}" Text="&#xE7FC;" FontSize="30" Foreground="#FFFFFD"
                             HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <StackPanel Grid.Column="1" Margin="20,0,20,0" VerticalAlignment="Center">
                  <TextBlock Text="Game Mode" FontSize="22" FontWeight="SemiBold" Foreground="#FFFFFD"/>
                  <TextBlock Text="High frame rate, low latency, and real keyboard, mouse and controller input. Changes here are saved to the Gaming profile."
                             Foreground="#C9CFF5" TextWrapping="Wrap" Margin="0,4,0,0"/>
                  <Grid Margin="0,14,0,0" MaxWidth="420" HorizontalAlignment="Left">
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <TextBlock Text="Phone" Foreground="#C9CFF5" VerticalAlignment="Center" Margin="0,0,12,0"/>
                    <ComboBox x:Name="GameDevice" Grid.Column="1" MinWidth="260"/>
                  </Grid>
                </StackPanel>
                <Button x:Name="BtnGameLaunch" Grid.Column="2" Style="{StaticResource BigAccentBtn}" VerticalAlignment="Center">
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE768;"/>
                    <TextBlock Text="Launch Game Mode"/>
                  </StackPanel>
                </Button>
              </Grid>
            </Border>

            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="16"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Border Style="{StaticResource CardBox}">
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE945;" Foreground="#FFB547" FontSize="16"/>
                    <TextBlock Text="Performance" Style="{StaticResource H2}"/>
                  </StackPanel>
                  <TextBlock Text="Frame rate" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GFps"/>
                  <TextBlock Text="Resolution" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GSize"/>
                  <TextBlock Text="Video quality (bitrate)" Style="{StaticResource Label}"/>
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="80"/>
                    </Grid.ColumnDefinitions>
                    <Slider x:Name="GBitrate" Minimum="2" Maximum="40" TickFrequency="1" IsSnapToTickEnabled="True" LargeChange="2" VerticalAlignment="Center"/>
                    <TextBlock x:Name="GBitrateVal" Grid.Column="1" Text="12 Mbps" HorizontalAlignment="Right" VerticalAlignment="Center" FontWeight="SemiBold"/>
                  </Grid>
                  <TextBlock Text="Video codec" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GCodec"/>
                  <TextBlock Text="Game audio delay" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GAudioBuf"/>
                  <CheckBox x:Name="GAudio" Content="Play game sound on PC" Margin="0,14,0,4"/>
                  <CheckBox x:Name="GPrintFps" Content="Show live FPS on Home"/>
                </StackPanel>
              </Border>
              <Border Grid.Column="2" Style="{StaticResource CardBox}">
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE765;" Foreground="#9DB8FF" FontSize="16"/>
                    <TextBlock Text="Controls" Style="{StaticResource H2}"/>
                  </StackPanel>
                  <TextBlock Text="Keyboard" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GKeyboard"/>
                  <TextBlock Text="Mouse" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GMouse"/>
                  <TextBlock Text="Game controller" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="GGamepad"/>
                  <Border Padding="0" Margin="0,14,0,6">
                    <TextBlock Style="{StaticResource Hint}" Margin="0">
                      <Run Text="Physical mode makes the phone see a real keyboard, mouse or controller, so it works in games that support them. Physical mouse captures your cursor: "/>
                      <Run Text="press Left Alt to release it." FontWeight="SemiBold" Foreground="#E8EAED"/>
                      <Run Text=" scrcpy does not map keys to screen taps."/>
                    </TextBlock>
                  </Border>
                  <CheckBox x:Name="GKeepActive" Content="Keep phone screen on"/>
                  <CheckBox x:Name="GScreenOff" Content="Turn phone screen off (saves battery, mirror keeps working)"/>
                </StackPanel>
              </Border>
            </Grid>

            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <StackPanel Orientation="Horizontal">
                  <TextBlock Style="{StaticResource IconText}" Text="&#xE7F4;" Foreground="#3DDC97" FontSize="16"/>
                  <TextBlock Text="Second screen (virtual display)" Style="{StaticResource H2}"/>
                </StackPanel>
                <TextBlock Text="Run the game on its own display at a PC-friendly size. Your phone screen stays free for other things. Best on Android 13 and newer."
                           Style="{StaticResource Hint}"/>
                <CheckBox x:Name="GVirtual" Content="Play on a separate virtual display" Margin="0,12,0,4"/>
                <Grid>
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="14"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="14"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <StackPanel>
                    <TextBlock Text="Display size" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="GVdSize"/>
                  </StackPanel>
                  <StackPanel Grid.Column="2">
                    <TextBlock Text="UI scale (DPI)" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="GVdDpi"/>
                  </StackPanel>
                  <StackPanel Grid.Column="4" VerticalAlignment="Bottom">
                    <CheckBox x:Name="GFlex" Content="Resize with the window"/>
                  </StackPanel>
                </Grid>
                <TextBlock Text="Game to open (optional)" Style="{StaticResource Label}"/>
                <Grid>
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="14"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                  </Grid.ColumnDefinitions>
                  <TextBox x:Name="GAppPkg"/>
                  <ComboBox x:Name="GApp" Grid.Column="2"/>
                  <Button x:Name="BtnLoadApps" Grid.Column="3" Style="{StaticResource BtnBase}" Content="Load apps" Margin="10,0,0,0"/>
                </Grid>
                <TextBlock Text="Type a package name, pick one from your phone with Load apps, or type ?name to match by app name (for example ?zenless)."
                           Style="{StaticResource Hint}" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
          </StackPanel>
        </ScrollViewer>

        <!-- ===================== RECORDINGS ===================== -->
        <ScrollViewer x:Name="PageMedia" Visibility="Collapsed" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel Margin="32,4,32,32">
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="3*"/>
                <ColumnDefinition Width="16"/>
                <ColumnDefinition Width="2*"/>
              </Grid.ColumnDefinitions>
              <Border Style="{StaticResource CardBox}">
                <StackPanel>
                  <TextBlock Text="Save locations" Style="{StaticResource H2}"/>
                  <TextBlock Text="Recordings" Style="{StaticResource Label}"/>
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBox x:Name="MRecDir" IsReadOnly="True"/>
                    <Button x:Name="BtnRecDir" Grid.Column="1" Style="{StaticResource BtnBase}" Content="Change" Margin="8,0,0,0"/>
                    <Button x:Name="BtnOpenRec" Grid.Column="2" Style="{StaticResource IconBtn}" Content="&#xE838;" Margin="4,0,0,0" ToolTip="Open folder"/>
                  </Grid>
                  <TextBlock Text="Screenshots" Style="{StaticResource Label}"/>
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBox x:Name="MShotDir" IsReadOnly="True"/>
                    <Button x:Name="BtnShotDir" Grid.Column="1" Style="{StaticResource BtnBase}" Content="Change" Margin="8,0,0,0"/>
                    <Button x:Name="BtnOpenShot" Grid.Column="2" Style="{StaticResource IconBtn}" Content="&#xE838;" Margin="4,0,0,0" ToolTip="Open folder"/>
                  </Grid>
                </StackPanel>
              </Border>
              <Border Grid.Column="2" Style="{StaticResource CardBox}">
                <StackPanel>
                  <TextBlock Text="Recording" Style="{StaticResource H2}"/>
                  <TextBlock Text="File format" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="MFormat"/>
                  <TextBlock Text="Stop automatically after" Style="{StaticResource Label}"/>
                  <ComboBox x:Name="MLimit"/>
                  <TextBlock Text="Background recordings always use MKV, so the file stays playable when you press Stop."
                             Style="{StaticResource Hint}" Margin="0,10,0,0"/>
                </StackPanel>
              </Border>
            </Grid>
            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <Grid>
                  <TextBlock Text="Recent captures" Style="{StaticResource H2}"/>
                  <Button x:Name="BtnMediaRefresh" Style="{StaticResource IconBtn}" Content="&#xE72C;" HorizontalAlignment="Right"
                          Margin="0,-8,-8,0" ToolTip="Refresh"/>
                </Grid>
                <TextBlock x:Name="MediaEmpty" Text="No recordings or screenshots yet." Style="{StaticResource Hint}" Margin="0,10,0,0"/>
                <WrapPanel x:Name="MediaList" Margin="0,12,0,0"/>
              </StackPanel>
            </Border>
          </StackPanel>
        </ScrollViewer>

        <!-- ===================== SETTINGS ===================== -->
        <ScrollViewer x:Name="PageSettings" Visibility="Collapsed" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel Margin="32,4,32,32">
            <Border Style="{StaticResource CardBox}">
              <StackPanel>
                <TextBlock Text="Profiles" Style="{StaticResource H2}"/>
                <TextBlock Text="A profile is a set of mirroring options. Pick one to edit it. Changes save automatically." Style="{StaticResource Hint}"/>
                <WrapPanel Margin="0,12,0,0">
                  <ComboBox x:Name="SProfile" Width="260" Margin="0,0,10,0"/>
                  <Button x:Name="BtnPNew" Style="{StaticResource BtnBase}" Margin="0,0,8,0">
                    <StackPanel Orientation="Horizontal">
                      <TextBlock Style="{StaticResource IconText}" Text="&#xE710;"/>
                      <TextBlock Text="New"/>
                    </StackPanel>
                  </Button>
                  <Button x:Name="BtnPDup" Style="{StaticResource BtnBase}" Content="Duplicate" Margin="0,0,8,0"/>
                  <Button x:Name="BtnPRename" Style="{StaticResource BtnBase}" Content="Rename" Margin="0,0,8,0"/>
                  <Button x:Name="BtnPDel" Style="{StaticResource DangerBtn}" Content="Delete"/>
                </WrapPanel>
              </StackPanel>
            </Border>

            <Border Style="{StaticResource CardBox}">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE790;" Foreground="#9DB8FF" FontSize="15"/>
                    <TextBlock Text="Appearance" Style="{StaticResource H2}"/>
                  </StackPanel>
                  <TextBlock Text="Pick a colour theme. The squares show its colours. Apply restarts Scrcpy Flow in the new theme." Style="{StaticResource Hint}"/>
                  <StackPanel x:Name="ThemeSwatch" Orientation="Horizontal" Margin="0,12,0,0"/>
                </StackPanel>
                <StackPanel Grid.Column="1" VerticalAlignment="Center" Margin="16,0,0,0">
                  <TextBlock Text="Theme" Style="{StaticResource Label}" Margin="0,0,0,6"/>
                  <StackPanel Orientation="Horizontal">
                    <ComboBox x:Name="ATheme" Width="200"/>
                    <Button x:Name="BtnApplyTheme" Style="{StaticResource AccentBtn}" Content="Apply" Margin="8,0,0,0" IsEnabled="False"/>
                  </StackPanel>
                </StackPanel>
              </Grid>
            </Border>

            <Border Style="{StaticResource CardBox}">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource IconText}" Text="&#xE945;" Foreground="#C9B4FF" FontSize="15"/>
                    <TextBlock Text="Animations" Style="{StaticResource H2}"/>
                  </StackPanel>
                  <TextBlock x:Name="AnimStatus" Text="" Style="{StaticResource Hint}" Foreground="#C9CFD8"/>
                  <TextBlock Text="Add-ons: XamlFlair (smooth entrance effects) and LottieSharp (Lottie animations, about 20 MB). Replace loading.json or idle.json in the animations folder with any Lottie file you like."
                             Style="{StaticResource Hint}"/>
                </StackPanel>
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="16,0,0,0">
                  <Button x:Name="BtnAddOns" Style="{StaticResource AccentBtn}" Content="Download add-ons" Margin="0,0,8,0"/>
                  <Button x:Name="BtnOpenAnims" Style="{StaticResource BtnBase}" Content="Animations folder"/>
                </StackPanel>
              </Grid>
            </Border>

            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="16"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <StackPanel>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Video" Style="{StaticResource H2}"/>
                    <TextBlock Text="Show" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SSource"/>
                    <TextBlock Text="Resolution" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SSize"/>
                    <TextBlock Text="Quality (bitrate)" Style="{StaticResource Label}"/>
                    <Grid>
                      <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="80"/>
                      </Grid.ColumnDefinitions>
                      <Slider x:Name="SBitrate" Minimum="2" Maximum="40" TickFrequency="1" IsSnapToTickEnabled="True" LargeChange="2" VerticalAlignment="Center"/>
                      <TextBlock x:Name="SBitrateVal" Grid.Column="1" Text="8 Mbps" HorizontalAlignment="Right" VerticalAlignment="Center" FontWeight="SemiBold"/>
                    </Grid>
                    <TextBlock Text="Frame rate limit" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SFps"/>
                    <TextBlock Text="Codec" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SCodec"/>
                    <CheckBox x:Name="SRotLock" Content="Lock rotation to how the phone starts" Margin="0,14,0,0"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Audio" Style="{StaticResource H2}"/>
                    <CheckBox x:Name="SAudio" Content="Play phone sound on PC (Android 11+)" Margin="0,10,0,0"/>
                    <TextBlock Text="Sound source" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SAudioSrc"/>
                    <TextBlock Text="Audio delay" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SAudioBuf"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Virtual display" Style="{StaticResource H2}"/>
                    <CheckBox x:Name="SVirtual" Content="Open on a separate virtual display" Margin="0,10,0,0"/>
                    <TextBlock Text="Size" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SVdSize"/>
                    <TextBlock Text="UI scale (DPI)" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SVdDpi"/>
                    <CheckBox x:Name="SFlex" Content="Resize with the window" Margin="0,12,0,0"/>
                    <TextBlock Text="App to open (package or ?name)" Style="{StaticResource Label}"/>
                    <TextBox x:Name="SStartApp"/>
                  </StackPanel>
                </Border>
              </StackPanel>
              <StackPanel Grid.Column="2">
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Phone" Style="{StaticResource H2}"/>
                    <CheckBox x:Name="SKeepActive" Content="Keep screen on (works over Wi-Fi)" Margin="0,10,0,0"/>
                    <CheckBox x:Name="SStayAwake" Content="Stay awake while charging"/>
                    <CheckBox x:Name="SScreenOff" Content="Turn phone screen off while mirroring"/>
                    <CheckBox x:Name="SPowerOff" Content="Lock the phone when I close the mirror"/>
                    <CheckBox x:Name="SShowTouches" Content="Show touches on the phone"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Input" Style="{StaticResource H2}"/>
                    <CheckBox x:Name="SNoControl" Content="View only (no mouse or keyboard control)" Margin="0,10,0,0"/>
                    <TextBlock Text="Keyboard" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SKeyboard"/>
                    <TextBlock Text="Mouse" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SMouse"/>
                    <TextBlock Text="Game controller" Style="{StaticResource Label}"/>
                    <ComboBox x:Name="SGamepad"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="Window" Style="{StaticResource H2}"/>
                    <CheckBox x:Name="SOnTop" Content="Always on top" Margin="0,10,0,0"/>
                    <CheckBox x:Name="SFullscreen" Content="Start fullscreen (F11 to toggle)"/>
                    <CheckBox x:Name="SBorderless" Content="Borderless window"/>
                    <CheckBox x:Name="SPrintFps" Content="Show live FPS on Home"/>
                    <TextBlock Text="Extra scrcpy options (advanced)" Style="{StaticResource Label}"/>
                    <TextBox x:Name="SExtra" FontFamily="Cascadia Mono, Consolas"/>
                  </StackPanel>
                </Border>
                <Border Style="{StaticResource CardBox}">
                  <StackPanel>
                    <TextBlock Text="App" Style="{StaticResource H2}"/>
                    <TextBlock Text="scrcpy.exe location" Style="{StaticResource Label}"/>
                    <Grid>
                      <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                      </Grid.ColumnDefinitions>
                      <TextBox x:Name="AScrcpy" IsReadOnly="True"/>
                      <Button x:Name="BtnBrowseScrcpy" Grid.Column="1" Style="{StaticResource BtnBase}" Content="Browse" Margin="8,0,0,0"/>
                    </Grid>
                    <CheckBox x:Name="AAutoConnect" Content="Start mirroring my default phone when the app opens" Margin="0,14,0,4"/>
                    <WrapPanel Margin="0,10,0,0">
                      <Button x:Name="BtnRestartAdb" Style="{StaticResource BtnBase}" Content="Restart adb" Margin="0,0,8,0"/>
                      <Button x:Name="BtnOpenScrcpyDir" Style="{StaticResource BtnBase}" Content="Open scrcpy folder" Margin="0,0,8,0"/>
                      <Button x:Name="BtnShortcut" Style="{StaticResource BtnBase}" Content="Add desktop shortcut"/>
                    </WrapPanel>
                    <TextBlock Text="Xiaomi / Redmi / POCO: if clicks and typing do nothing, turn on USB debugging (Security settings) in Developer options."
                               Style="{StaticResource Hint}" Margin="0,12,0,0"/>
                    <TextBlock Text="Scrcpy Flow is an unofficial app built on scrcpy by Genymobile (github.com/Genymobile/scrcpy)."
                               Style="{StaticResource Hint}" Margin="0,8,0,0"/>
                  </StackPanel>
                </Border>
              </StackPanel>
            </Grid>
          </StackPanel>
        </ScrollViewer>
      </Grid>

      <!-- Toast -->
      <Border x:Name="Toast" Grid.Row="1" Visibility="Collapsed" HorizontalAlignment="Center" VerticalAlignment="Bottom"
              Margin="0,0,0,26" Padding="18,11" CornerRadius="12" Background="#262C38" BorderBrush="#3A4150" BorderThickness="1">
        <Border.Effect>
          <DropShadowEffect Color="#000000" BlurRadius="24" ShadowDepth="4" Opacity="0.45"/>
        </Border.Effect>
        <StackPanel Orientation="Horizontal">
          <Ellipse x:Name="ToastDot" Width="9" Height="9" Fill="#5B8CFF" VerticalAlignment="Center"/>
          <TextBlock x:Name="ToastText" Margin="11,0,0,0" Text="" MaxWidth="560" TextWrapping="Wrap"/>
        </StackPanel>
      </Border>
    </Grid>

    <!-- Busy overlay -->
    <Border x:Name="BusyOverlay" Grid.ColumnSpan="2" Background="#B80A0C10" Visibility="Collapsed">
      <Border x:Name="BusyCard" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{StaticResource GrCard}" CornerRadius="16" Padding="34,26"
              BorderBrush="{StaticResource BrLine}" BorderThickness="1" MinWidth="340">
        <StackPanel>
          <Grid x:Name="BusyAnimHost" Width="84" Height="84" HorizontalAlignment="Center" Visibility="Collapsed"/>
          <TextBlock x:Name="BusySpinner" FontFamily="{StaticResource Icons}" Text="&#xE895;" FontSize="30" Foreground="#5B8CFF"
                     HorizontalAlignment="Center" RenderTransformOrigin="0.5,0.5">
            <TextBlock.RenderTransform>
              <RotateTransform/>
            </TextBlock.RenderTransform>
            <TextBlock.Triggers>
              <EventTrigger RoutedEvent="FrameworkElement.Loaded">
                <BeginStoryboard>
                  <Storyboard RepeatBehavior="Forever">
                    <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(RotateTransform.Angle)"
                                     From="0" To="360" Duration="0:0:1.1"/>
                  </Storyboard>
                </BeginStoryboard>
              </EventTrigger>
            </TextBlock.Triggers>
          </TextBlock>
          <TextBlock x:Name="BusyText" Text="Working..." HorizontalAlignment="Center" Margin="0,16,0,0" FontSize="15"
                     TextWrapping="Wrap" MaxWidth="380" TextAlignment="Center"/>
          <TextBlock x:Name="BusySub" Text="This can take a few seconds." Foreground="{StaticResource BrSub}" FontSize="13"
                     HorizontalAlignment="Center" Margin="0,6,0,0" TextWrapping="Wrap" MaxWidth="380" TextAlignment="Center"/>
        </StackPanel>
      </Border>
    </Border>

    <!-- Dialog overlay -->
    <Border x:Name="DlgOverlay" Grid.ColumnSpan="2" Background="#B80A0C10" Visibility="Collapsed">
      <Border x:Name="DlgCard" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{StaticResource GrCard}" CornerRadius="16" Padding="26" Width="440"
              BorderBrush="{StaticResource BrLine}" BorderThickness="1">
        <StackPanel>
          <TextBlock x:Name="DlgTitle" Text="" FontSize="18" FontWeight="SemiBold" TextWrapping="Wrap"/>
          <TextBlock x:Name="DlgMsg" Text="" Foreground="{StaticResource BrSub}" FontSize="13" Margin="0,8,0,0" TextWrapping="Wrap"/>
          <TextBox x:Name="DlgInput" Margin="0,16,0,0"/>
          <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,22,0,0">
            <Button x:Name="DlgCancel" Style="{StaticResource GhostBtn}" Content="Cancel" Padding="16,8" Margin="0,0,8,0"/>
            <Button x:Name="DlgOk" Style="{StaticResource AccentBtn}" Content="OK" Padding="18,8"/>
          </StackPanel>
        </StackPanel>
      </Border>
    </Border>
  </Grid>
</Window>
'@
# =====================================================================
#  Themes. Midnight is the original look; other themes swap its colours
#  when the window is built (keys are Midnight colours, RRGGBB).
# =====================================================================
$Themes = [ordered]@{
    'Midnight' = @{ Dark = $true; Caption = 0x0015110F; Swatch = @('0F1115', '1C212B', '3F6BE6', '7A4FF0'); Map = @{ 'FFFFFC' = 'E8EAED'; 'FFFFFB' = 'A3ACB9' } }
    'Khaki'    = @{ Dark = $false; Caption = 0x00D6E7ED; Swatch = @('EDE7D6', 'F8F4EA', '556B2F', '7B5E34'); Map = @{
        # surfaces
        '0F1115' = 'EDE7D6'; '13161C' = 'E5DDC6'; '181C23' = 'F7F3E8'; '20252F' = 'E9E2CE'
        '11141A' = 'FCFAF4'; '12151B' = 'FCFAF4'; '0E1116' = 'FCFAF4'; '1B1F27' = 'FCFAF4'
        '1C212B' = 'F8F4EA'; '161A21' = 'F2EDE0'; '363F50' = 'D6CBB0'; '22272F' = 'CFC4A8'
        '222838' = 'EEE8D9'; '1B1F28' = 'E9E2D0'; '232A3A' = 'EEE8D9'; '1D222C' = 'EEE8D9'
        '33456F' = 'DDD5B8'; '2E2A52' = 'D5CBAA'; '171B28' = 'E6DFCB'; '111318' = 'E0D8C2'
        '2A3A6C' = 'D9D0B0'; '232B4A' = 'DED6BA'; '26365F' = 'E6DEC6'; '2B2456' = 'DFD5B8'
        '3A4F8A' = 'C2B48C'; '171B22' = 'EFE9DA'; '262C38' = 'FBF8F1'; '252B36' = 'D8CFB6'
        '24304A' = 'E2DAC2'; '2A3140' = 'EAE3D1'; '343B48' = 'C9BE9F'
        # lines
        '2A303B' = 'D3C8AE'; '3C4454' = 'B5A783'; '2F3642' = 'CFC4A8'; '3A4150' = 'BFB291'
        # hero cards stay dark (olive) so their white text keeps working
        '263866' = '59633A'; '1D2344' = '4A5230'; '2C2052' = '5E4E32'; '3A4A7A' = '7A7F52'
        '2B2560' = '5E4E32'; '16243F' = '4A5230'; '3A3F6B' = '7A7F52'
        'B9C3E6' = 'E8E0C4'; 'B4C0E6' = 'E3DBBE'; 'D6DCF5' = 'F1EBD6'; 'C9CFF5' = 'E8E0C4'
        # text
        'E8EAED' = '2B2A22'; 'FFFFFF' = '2B2A22'; 'A3ACB9' = '5E5848'; '9AA3AF' = '6F6855'
        'B7BFCB' = '4E4838'; 'C9CFD8' = '3E3A2E'; 'B9C0CA' = '4A4535'; '6B7380' = '8A8068'
        # accent: olive and khaki brown
        '5B8CFF' = '5C6B2E'; '9DB8FF' = '5C6B2E'; '8FB0FF' = '5C6B2E'; '8B7CFF' = '6B7A35'
        '8B5CFF' = '8A6D3B'; '3F6BE6' = '556B2F'; '7A4FF0' = '7B5E34'; 'C9B4FF' = '7B5E34'
        '6E8BFF' = '7A8A45'; '6A4CFF' = 'B59A5C'; '3D7BFF' = '8A9A5B'
        # status
        '3DDC97' = '24693F'; 'FFB547' = '8A5508'; 'FF5C6C' = 'B23A3A'; 'FF8A95' = 'B23A3A'
        '0A0C10' = '2E2A1F'; 'FFFFFE' = 'FFFFFF'; 'FFFFFD' = 'FFFFFF'; 'FFFFFC' = '2B2A22'; 'FFFFFB' = '5E5848'
    } }
    'Twilight' = @{ Dark = $true; Caption = 0x00361D22; Swatch = @('453C67', '6D67E4', '46C2CB', 'F2F7A1'); Map = @{
        # flat colours (both ends of every gradient get the same value)
        '0F1115' = '221D36'; '13161C' = '1D1930'; '181C23' = '2C2645'; '20252F' = '453C67'
        '11141A' = '1B172D'; '12151B' = '1B172D'; '0E1116' = '1B172D'; '1B1F27' = '2C2645'
        '1C212B' = '2F2849'; '161A21' = '2F2849'; '363F50' = '453C67'; '22272F' = '453C67'
        '222838' = '3A3358'; '1B1F28' = '3A3358'; '232A3A' = '3A3358'; '1D222C' = '3A3358'
        '33456F' = '453C67'; '2E2A52' = '453C67'; '171B28' = '1D1930'; '111318' = '1D1930'
        '2A3A6C' = '453C67'; '232B4A' = '453C67'; '26365F' = '3A3358'; '2B2456' = '3A3358'
        '3A4F8A' = '6D67E4'; '171B22' = '2C2645'; '262C38' = '3A3358'; '252B36' = '2C2645'
        '24304A' = '453C67'; '2A3140' = '3A3358'; '343B48' = '5A5185'
        '2A303B' = '453C67'; '3C4454' = '5E5590'; '2F3642' = '4F4675'; '3A4150' = '5A5185'
        '263866' = '453C67'; '1D2344' = '453C67'; '2C2052' = '453C67'; '3A4A7A' = '6D67E4'
        '2B2560' = '453C67'; '16243F' = '453C67'; '3A3F6B' = '6D67E4'
        'B9C3E6' = 'D9D4F0'; 'B4C0E6' = 'D9D4F0'; 'D6DCF5' = 'F3F1FA'; 'C9CFF5' = 'D9D4F0'
        'E8EAED' = 'F3F1FA'; 'A3ACB9' = 'B9B3D6'; '9AA3AF' = 'A9A2C9'; 'B7BFCB' = 'C9C3E3'
        'C9CFD8' = 'DCD8EE'; 'B9C0CA' = 'C9C3E3'; '6B7380' = '7A7399'
        '5B8CFF' = '46C2CB'; '9DB8FF' = '46C2CB'; '8FB0FF' = 'F2F7A1'; '8B7CFF' = '46C2CB'
        '8B5CFF' = '6560DD'; '3F6BE6' = '6560DD'; '7A4FF0' = '6560DD'; 'C9B4FF' = 'F2F7A1'
        '6E8BFF' = '6D67E4'; '6A4CFF' = '221D36'; '3D7BFF' = '221D36'
        '3DDC97' = '7BE0A6'; 'FFB547' = 'F2F7A1'; 'FF5C6C' = 'FF7A8A'; 'FF8A95' = 'FF9AA6'
        '0A0C10' = '0E0B18'; 'FFFFFC' = 'F3F1FA'; 'FFFFFB' = 'B9B3D6'
    } }
    'Sky' = @{ Dark = $true; Caption = 0x00E86A1F; Swatch = @('2373F4', '578EF5', '65D0F4', 'F2F7A0'); Map = @{
        # flat colours, from the top of the palette (blue background) down to the bottom (yellow buttons)
