if (-not $Themes.Contains([string]$State.Theme)) { $State.Theme = 'Midnight' }
$ThemeMap = $Themes[[string]$State.Theme].Map

function Map-Color([string]$c) {
    # '#RRGGBB' or '#AARRGGBB' -> the same colour in the current theme
    if (-not $ThemeMap.Count -or -not $c -or -not $c.StartsWith('#')) { return $c }
    $h = $c.Substring(1).ToUpperInvariant()
    if ($h.Length -eq 6) {
        if ($ThemeMap.Contains($h)) { return '#' + $ThemeMap[$h] }
    } elseif ($h.Length -eq 8) {
        $rgb = $h.Substring(2)
        if ($rgb -ne 'FFFFFF' -and $ThemeMap.Contains($rgb)) { return '#' + $h.Substring(0, 2) + $ThemeMap[$rgb] }
    }
    return $c
}

function Apply-Theme([string]$Xaml) {
    if (-not $ThemeMap.Count) { return $Xaml }
    return [regex]::Replace($Xaml, '#[0-9A-Fa-f]{8}\b|#[0-9A-Fa-f]{6}\b', { param($m) Map-Color $m.Value })
}

# =====================================================================
#  Build the window
# =====================================================================
function Remove-Flair([string]$t) {
    $t = $t -replace '\s+xmlns:xf="[^"]*"', ''
    $t = [regex]::Replace($t, '(?s)<xf:[^>]*?/>', '')
    $t = [regex]::Replace($t, '<Setter Property="xf:[^"]*" Value="[^"]*"\s*/>', '')
    $t = [regex]::Replace($t, '\s+xf:[A-Za-z.]+="[^"]*"', '')
    return $t
}

Import-AddOns
$XamlText = Apply-Theme $XamlText
$XamlUsed = if ($App.HasFlair) { $XamlText } else { Remove-Flair $XamlText }
try {
    [xml]$XamlDoc = $XamlUsed
    $window = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $XamlDoc))
} catch {
    if (-not $App.HasFlair) { throw }
    # The XamlFlair add-on did not work here: start without it
    Write-Crash $_
    $App.HasFlair = $false
    $App.FlairFailed = $true
    [xml]$XamlDoc = Remove-Flair $XamlText
    $window = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $XamlDoc))
}
$UI = @{}
$nsm = New-Object System.Xml.XmlNamespaceManager($XamlDoc.NameTable)
$nsm.AddNamespace('x', 'http://schemas.microsoft.com/winfx/2006/xaml')
foreach ($node in $XamlDoc.SelectNodes('//*[@x:Name]', $nsm)) {
    $n = $node.GetAttribute('Name', 'http://schemas.microsoft.com/winfx/2006/xaml')
    $el = $window.FindName($n)
    if ($el) { $UI[$n] = $el }
}

$IconFont = New-Object System.Windows.Media.FontFamily('Segoe Fluent Icons, Segoe MDL2 Assets')
$BrushConv = New-Object System.Windows.Media.BrushConverter
function Get-Brush([string]$c) { return $BrushConv.ConvertFromString((Map-Color $c)) }
$Colors = @{ ok = '#3DDC97'; busy = '#5B8CFF'; bad = '#FF5C6C'; warn = '#FFB547'; idle = '#A3ACB9'; info = '#5B8CFF' }
foreach ($k in @($Colors.Keys)) { $Colors[$k] = Map-Color $Colors[$k] }

# =====================================================================
#  Animations (built-in WPF; XamlFlair/Lottie add-ons when installed)
# =====================================================================
# Windows Settings > Accessibility > Visual effects > Animation effects
$App.Motion = $true
try { $App.Motion = [bool][System.Windows.SystemParameters]::ClientAreaAnimation } catch {}

function New-Anim([double]$From, [double]$To, [int]$Ms, [bool]$Ease = $true) {
    $a = New-Object System.Windows.Media.Animation.DoubleAnimation
    $a.From = $From
    $a.To = $To
    $a.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds($Ms))
    if ($Ease) {
        $e = New-Object System.Windows.Media.Animation.CubicEase
        $e.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $a.EasingFunction = $e
    }
    return $a
}

function Play-SlideIn($El, [double]$Dy = 8, [int]$Ms = 220) {
    if (-not $App.Motion) { return }
    try {
        $tt = New-Object System.Windows.Media.TranslateTransform
        $El.RenderTransform = $tt
        $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, (New-Anim 0 1 $Ms))
        $tt.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, (New-Anim $Dy 0 $Ms))
    } catch {}
}

function Play-Pop($El, [int]$Ms = 200) {
    if (-not $App.Motion) { return }
    try {
        $st = New-Object System.Windows.Media.ScaleTransform(0.97, 0.97)
        $El.RenderTransformOrigin = New-Object System.Windows.Point(0.5, 0.5)
        $El.RenderTransform = $st
        $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, (New-Anim 0 1 $Ms))
        $st.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, (New-Anim 0.97 1 $Ms))
        $st.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, (New-Anim 0.97 1 $Ms))
    } catch {}
}

function Play-FadeIn($El, [int]$Ms = 160) {
    if (-not $App.Motion) { return }
    try { $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, (New-Anim 0 1 $Ms)) } catch {}
}

function Set-DotColor($El, [string]$Hex) {
    try {
        $c = [System.Windows.Media.ColorConverter]::ConvertFromString((Map-Color $Hex))
        $b = $El.Fill
        if ($b -isnot [System.Windows.Media.SolidColorBrush]) { $El.Fill = New-Object System.Windows.Media.SolidColorBrush($c); return }
        if ($b.IsFrozen) { $b = $b.Clone(); $El.Fill = $b }
        $a = New-Object System.Windows.Media.Animation.ColorAnimation
        $a.To = $c
        $a.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(350))
        $b.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $a)
    } catch {
        $El.Fill = Get-Brush $Hex
    }
}

function Add-HoverGlow($Bd, [string]$Rest, [string]$Hot) {
    try {
        $Rest = Map-Color $Rest
        $Hot = Map-Color $Hot
        $Bd.BorderBrush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($Rest))
        $Bd.BorderThickness = '1'
        $Bd.Add_MouseEnter({
            param($s, $e)
            $a = New-Object System.Windows.Media.Animation.ColorAnimation
            $a.To = [System.Windows.Media.ColorConverter]::ConvertFromString($Hot)
            $a.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(180))
            $s.BorderBrush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $a)
        }.GetNewClosure())
        $Bd.Add_MouseLeave({
            param($s, $e)
            $a = New-Object System.Windows.Media.Animation.ColorAnimation
            $a.To = [System.Windows.Media.ColorConverter]::ConvertFromString($Rest)
            $a.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(350))
            $s.BorderBrush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $a)
        }.GetNewClosure())
    } catch {}
}

function Start-Pulse($El, [double]$Low = 0.35, [int]$Ms = 900) {
    if (-not $App.Motion) { return }
    try {
        $a = New-Anim 1 $Low $Ms $false
        $a.AutoReverse = $true
        $a.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $a)
    } catch {}
}

function Stop-Pulse($El) {
    try {
        $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $El.Opacity = 1
    } catch {}
}

function Set-Depth($El) {
    # Soft shadow with a real offset, so the main action sits above the card
    try {
        $fx = New-Object System.Windows.Media.Effects.DropShadowEffect
        $fx.Color = [System.Windows.Media.Colors]::Black
        $fx.Direction = 270
        $fx.ShadowDepth = 4
        $fx.BlurRadius = 16
        $fx.Opacity = 0.35
        $El.Effect = $fx
    } catch {}
}

function Add-Entrance($El, [string]$Key = '') {
    if ($Key) {
        if (-not $App.SeenRows) { $App.SeenRows = @{} }
        if ($App.SeenRows.ContainsKey($Key)) { return }
        $App.SeenRows[$Key] = $true
    }
    if (-not $App.Motion) { return }
    if ($App.HasFlair) {
        try {
            $t = 'XamlFlair.Animations' -as [type]
            $t::SetPrimary($El, $window.FindResource('AnimFadeUp'))
            return
        } catch {}
    }
    Play-SlideIn $El 8 220
}

function New-LottieView([string]$File, [double]$Size) {
    if (-not $App.HasLottie) { return $null }
    $path = Join-Path $AnimDir $File
    if (-not (Test-Path -LiteralPath $path)) { return $null }
    try {
        $v = New-Object LottieSharp.WPF.LottieAnimationView
        $v.Width = $Size
        $v.Height = $Size
        $v.RepeatCount = -1
        $v.AutoPlay = $true
        $v.FileName = $path
        return $v
    } catch {
        Write-Crash $_
        return $null
    }
}

# =====================================================================
#  Small UI helpers
# =====================================================================
function Log([string]$Msg, [string]$Kind = 'info') {
    if (-not $Msg) { return }
    $prefix = switch ($Kind) { 'bad' { '[!] ' } 'warn' { '[~] ' } 'ok' { '[ok] ' } default { '' } }
    $ts = (Get-Date).ToString('HH:mm:ss')
    $body = ($Msg.Trim() -replace "\r?\n", "`r`n          ")
    $UI.LogBox.AppendText("$ts  $prefix$body`r`n")
    if ($UI.LogBox.Text.Length -gt 80000) { $UI.LogBox.Text = $UI.LogBox.Text.Substring(40000) }
    $UI.LogBox.ScrollToEnd()
}

function Set-Status([string]$Text, [string]$Kind = 'idle') {
    $UI.StatusText.Text = $Text
    Set-DotColor $UI.StatusDot $Colors[$Kind]
}

function Update-Status {
    $n = @($App.Sessions | Where-Object { -not $_.Ended }).Count
    if ($n -gt 0) {
        $word = if ($n -eq 1) { 'phone' } else { 'phones' }
        Set-Status "Mirroring $n $word" 'ok'
        $UI.SideSessions.Text = "$n running"
        Set-DotColor $UI.MirrorDot $Colors.ok
        if (-not $App.Pulsing) { Start-Pulse $UI.MirrorDot 0.4 1100; $App.Pulsing = $true }
    } else {
        Set-Status 'Ready' 'idle'
        $UI.SideSessions.Text = 'Nothing running'
        Set-DotColor $UI.MirrorDot '#6B7380'
        if ($App.Pulsing) { Stop-Pulse $UI.MirrorDot; $App.Pulsing = $false }
    }
    $UI.SessionCount.Text = "$n"
    $UI.SessionEmpty.Visibility = if ($n -eq 0) { 'Visible' } else { 'Collapsed' }
}

$ToastTimer = New-Object System.Windows.Threading.DispatcherTimer
$ToastTimer.Interval = [TimeSpan]::FromSeconds(4)
$App.ToastSeq = 0
$ToastTimer.Add_Tick({
    $ToastTimer.Stop()
    $App.ToastSeq++
    $seq = $App.ToastSeq
    $app = $App
    $toast = $UI.Toast
    $a = New-Anim 1 0 260 $false
    $a.Add_Completed({ if ($app.ToastSeq -eq $seq) { $toast.Visibility = 'Collapsed' } }.GetNewClosure())
    $UI.Toast.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $a)
})

function Show-Toast([string]$Text, [string]$Kind = 'info') {
    $App.ToastSeq++
    $UI.ToastText.Text = $Text
    Set-DotColor $UI.ToastDot $Colors[$Kind]
    $UI.Toast.Visibility = 'Visible'
    Play-SlideIn $UI.Toast 12 200
    $ToastTimer.Stop()
    $ToastTimer.Start()
}

function Show-Busy([string]$Text, [string]$Sub = 'This can take a few seconds.') {
    $App.BusyDepth++
    $UI.BusyText.Text = $Text
    if ($App.BusyDepth -eq 1) { $UI.BusySub.Text = $Sub }
    if ($UI.BusyOverlay.Visibility -ne 'Visible') {
        $UI.BusyOverlay.Visibility = 'Visible'
        Play-FadeIn $UI.BusyOverlay 160
        Play-Pop $UI.BusyCard 200
    }
    Set-Status $Text 'busy'
    Invoke-UIEvents
}

function Set-BusyText([string]$Text, [string]$Sub = '') {
    $UI.BusyText.Text = $Text
    if ($Sub) { $UI.BusySub.Text = $Sub }
    Set-Status $Text 'busy'
    Invoke-UIEvents
}

function Hide-Busy {
    $App.BusyDepth = [math]::Max(0, $App.BusyDepth - 1)
    if ($App.BusyDepth -eq 0) {
        $UI.BusyOverlay.Visibility = 'Collapsed'
        Update-Status
    }
}

function Show-Dialog([string]$Title, [string]$Message, [bool]$WithInput = $false, [string]$Default = '', [string]$OkText = 'OK') {
    $UI.DlgTitle.Text = $Title
    $UI.DlgMsg.Text = $Message
    $UI.DlgMsg.Visibility = if ($Message) { 'Visible' } else { 'Collapsed' }
    $UI.DlgInput.Visibility = if ($WithInput) { 'Visible' } else { 'Collapsed' }
    $UI.DlgInput.Text = $Default
    $UI.DlgOk.Content = $OkText
    $UI.DlgOverlay.Visibility = 'Visible'
    Play-FadeIn $UI.DlgOverlay 140
    Play-Pop $UI.DlgCard 180
    if ($WithInput) { [void]$UI.DlgInput.Focus(); $UI.DlgInput.SelectAll() } else { [void]$UI.DlgOk.Focus() }
    $App.DlgResult = $null
    $App.DlgFrame = New-Object System.Windows.Threading.DispatcherFrame
    [System.Windows.Threading.Dispatcher]::PushFrame($App.DlgFrame)
    $App.DlgFrame = $null
    $UI.DlgOverlay.Visibility = 'Collapsed'
    return $App.DlgResult
}

function Close-Dialog([bool]$Ok) {
    if ($Ok) { $App.DlgResult = [string]$UI.DlgInput.Text } else { $App.DlgResult = $null }
    if ($App.DlgFrame) { $App.DlgFrame.Continue = $false }
}

# =====================================================================
#  Atomic design builders (see DESIGN.md)
#  Atoms:      New-Text, New-Glyph
#  Molecules:  New-Btn, New-IconBtn, New-Badge, New-IconCircle
#  Organisms:  New-Row, Add-SessionRow, Render-Saved, Render-Detected
# =====================================================================
function New-Text([string]$Text, [double]$Size = 13, $Weight = $null, [string]$Color = '') {
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $Text
    $t.FontSize = $Size
    if ($Weight) { $t.FontWeight = $Weight }
    if ($Color) { $t.Foreground = Get-Brush $Color }
    $t.TextTrimming = 'CharacterEllipsis'
    $t.VerticalAlignment = 'Center'
    return $t
}

function New-Glyph([int]$Code, [double]$Size = 16, [string]$Color = '#E8EAED') {
    $t = New-Object System.Windows.Controls.TextBlock
    $t.FontFamily = $IconFont
    $t.Text = [string][char]$Code
    $t.FontSize = $Size
    $t.Foreground = Get-Brush $Color
    $t.VerticalAlignment = 'Center'
    $t.HorizontalAlignment = 'Center'
    return $t
}

function New-Btn([string]$Text, [int]$Glyph = 0, [string]$Style = 'BtnBase', $Tag = $null, $OnClick = $null) {
    $b = New-Object System.Windows.Controls.Button
    $b.Style = $window.FindResource($Style)
    if ($Glyph -gt 0) {
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Orientation = 'Horizontal'
        $g = New-Glyph $Glyph 13 '#FFFFFF'
        $g.Foreground = $b.Foreground
        $g.Margin = '0,1,8,0'
        [void]$sp.Children.Add($g)
        [void]$sp.Children.Add((New-Text $Text 13))
        $b.Content = $sp
    } else {
        $b.Content = $Text
    }
    $b.Tag = $Tag
    $b.Margin = '6,0,0,0'
    $b.Padding = '12,7'
    if ($OnClick) { $b.Add_Click($OnClick) }
    return $b
}

function New-IconBtn([int]$Glyph, [string]$Tip, $Tag, $OnClick, [string]$Color = '') {
    $b = New-Object System.Windows.Controls.Button
    $b.Style = $window.FindResource('IconBtn')
    $b.Content = [string][char]$Glyph
    $b.ToolTip = $Tip
    $b.Tag = $Tag
    $b.Margin = '2,0,0,0'
    if ($Color) { $b.Foreground = Get-Brush $Color }
    $b.Add_Click($OnClick)
    return $b
}

function New-Badge([string]$Text, [string]$Color) {
    $bd = New-Object System.Windows.Controls.Border
    $bd.CornerRadius = '7'
    $bd.Padding = '8,2'
    $bd.Margin = '0,0,8,0'
    $bd.VerticalAlignment = 'Center'
    $bd.Background = Get-Brush ('#26' + $Color.TrimStart('#'))
    $t = New-Text $Text 11 ([System.Windows.FontWeights]::SemiBold) $Color
    $bd.Child = $t
    return $bd
}

function New-Row {
    $bd = New-Object System.Windows.Controls.Border
    $bd.Background = $window.FindResource('GrRow')
    $bd.CornerRadius = '12'
    $bd.Padding = '14,12'
    $bd.Margin = '0,8,0,0'
    Add-HoverGlow $bd '#002A303B' '#705B8CFF'
    return $bd
}

function New-IconCircle([int]$Glyph, [string]$DotColor = '') {
    $g = New-Object System.Windows.Controls.Grid
    $g.Width = 42; $g.Height = 42
    $g.Margin = '0,0,14,0'
    $c = New-Object System.Windows.Controls.Border
    $c.CornerRadius = '21'
    $c.Background = $window.FindResource('GrIcon')
    $c.Child = (New-Glyph $Glyph 18 '#9DB8FF')
    [void]$g.Children.Add($c)
    if ($DotColor) {
        $e = New-Object System.Windows.Shapes.Ellipse
        $e.Width = 12; $e.Height = 12
        $e.Fill = Get-Brush $DotColor
        $e.Stroke = Get-Brush '#1D222C'
        $e.StrokeThickness = 2
        $e.HorizontalAlignment = 'Right'
        $e.VerticalAlignment = 'Bottom'
        [void]$g.Children.Add($e)
    }
    return $g
}

function Add-Col($grid, [string]$Width) {
    $cd = New-Object System.Windows.Controls.ColumnDefinition
    if ($Width -eq 'Auto') { $cd.Width = [System.Windows.GridLength]::Auto }
    elseif ($Width -eq '*') { $cd.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star) }
    else { $cd.Width = New-Object System.Windows.GridLength([double]$Width) }
    [void]$grid.ColumnDefinitions.Add($cd)
}

function Put($grid, $el, [int]$Col) {
    [System.Windows.Controls.Grid]::SetColumn($el, $Col)
    [void]$grid.Children.Add($el)
}

function Fill-Options($cb, $opts) {
    $cb.Items.Clear()
    foreach ($o in $opts) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $it.Content = [string]$o[1]
        $it.Tag = $o[0]
        [void]$cb.Items.Add($it)
    }
}

function Get-ComboTag($cb) {
    if ($cb.SelectedItem) { return $cb.SelectedItem.Tag }
    return $null
}

function Select-ComboTag($cb, $value) {
    foreach ($it in $cb.Items) {
        if ("$($it.Tag)" -eq "$value") { $cb.SelectedItem = $it; return $true }
    }
    return $false
}

function Format-Size([long]$b) {
    if ($b -ge 1GB) { return ('{0:N1} GB' -f ($b / 1GB)) }
    if ($b -ge 1MB) { return ('{0:N1} MB' -f ($b / 1MB)) }
    return ('{0:N0} KB' -f [math]::Max(1, $b / 1KB))
}

function Format-Elapsed([TimeSpan]$ts) {
    if ($ts.TotalHours -ge 1) { return ('{0}:{1:00}:{2:00}' -f [int][math]::Floor($ts.TotalHours), $ts.Minutes, $ts.Seconds) }
    return ('{0:00}:{1:00}' -f $ts.Minutes, $ts.Seconds)
}


# Friendly text for an adb serial (hides long Wireless-debugging IDs)
function Format-Serial([string]$Serial) {
    if (-not $Serial) { return '' }
    if ($Serial -match '^(\d{1,3}(\.\d{1,3}){3}):(\d+)$') {
        if ($Matches[3] -eq '5555') { return "Wi-Fi  $($Matches[1])" }
        return "Wireless debugging  $($Matches[1])"
    }
    if ($Serial -match '_adb-tls') {
        $hw = Get-HwFromName $Serial
        $d = $null
        if ($hw) { $d = $State.Devices | Where-Object { $_.HwSerial -eq $hw } | Select-Object -First 1 }
        if ($d -and $d.Address) { return "Wireless debugging  $(Get-IpOf $d.Address)" }
        return 'Wireless debugging'
    }
    return 'USB cable'
}

# =====================================================================
#  scrcpy arguments from a profile
# =====================================================================
function Get-ProfileArgs($P) {
    $a = New-Object System.Collections.Generic.List[string]
    $camera = ([string]$P.Source) -like 'camera*'
    if ([int]$P.MaxSize -gt 0) { $a.Add("--max-size=$([int]$P.MaxSize)") }
    $a.Add("--video-bit-rate=$([int]$P.BitRate)M")
    if ([int]$P.MaxFps -gt 0) { $a.Add("--max-fps=$([int]$P.MaxFps)") }
    if ($P.Codec -and $P.Codec -ne 'h264') { $a.Add("--video-codec=$($P.Codec)") }
    if ($camera) {
        $a.Add('--video-source=camera')
        $a.Add('--camera-facing=' + (([string]$P.Source) -replace '^camera-', ''))
    } elseif ($P.RotationLock) {
        $a.Add('--capture-orientation=@')
    }
    if (-not $P.Audio) {
        $a.Add('--no-audio')
    } else {
        if (-not $camera -and $P.AudioSource -and $P.AudioSource -ne 'output') { $a.Add("--audio-source=$($P.AudioSource)") }
        if ([int]$P.AudioBuffer -gt 0) { $a.Add("--audio-buffer=$([int]$P.AudioBuffer)") }
    }
    if ($camera -or $P.NoControl) {
        $a.Add('--no-control')
    } else {
        if ($P.Keyboard -and $P.Keyboard -ne 'sdk') { $a.Add("--keyboard=$($P.Keyboard)") }
        if ($P.Mouse -and $P.Mouse -ne 'sdk') { $a.Add("--mouse=$($P.Mouse)") }
        if ($P.Gamepad -eq 'uhid') { $a.Add('--gamepad=uhid') }
        if ($P.KeepActive -and $App.ScrcpyMajor -ge 4) { $a.Add('--keep-active') }
        if ($P.StayAwake) { $a.Add('--stay-awake') }
        if ($P.ScreenOff) { $a.Add('--turn-screen-off') }
        if ($P.ShowTouches) { $a.Add('--show-touches') }
        if ($P.PowerOffOnClose) { $a.Add('--power-off-on-close') }
    }
    if (-not $camera) {
        if ($P.VirtualDisplay) {
            $spec = ''
            if ($P.VdSize) { $spec = [string]$P.VdSize }
            if ([int]$P.VdDpi -gt 0) { $spec += "/$([int]$P.VdDpi)" }
            if ($spec) { $a.Add("--new-display=$spec") } else { $a.Add('--new-display') }
            if ($P.FlexDisplay -and $App.ScrcpyMajor -ge 4) { $a.Add('--flex-display') }
        }
        if ($P.StartApp) { $a.Add('--start-app=' + ([string]$P.StartApp).Trim()) }
    }
    if ($P.OnTop) { $a.Add('--always-on-top') }
    if ($P.Fullscreen) { $a.Add('--fullscreen') }
    if ($P.Borderless) { $a.Add('--window-borderless') }
    if ($P.PrintFps) { $a.Add('--print-fps') }
    return , $a
}

# =====================================================================
#  Mirroring sessions
# =====================================================================
function New-LineReader($sr) {
    return [pscustomobject]@{ R = $sr; T = $sr.ReadLineAsync(); Done = $false }
}

function Get-RunningFor([string]$Serial) {
    return ($App.Sessions | Where-Object { -not $_.Ended -and $_.Serial -eq $Serial } | Select-Object -First 1)
}

function Start-Session {
    param([string]$Serial, [string]$Name, $Prof, [bool]$Record = $false, [bool]$Background = $false, [string]$DeviceTag = '', [string]$Mode = '')
    if (-not $Mode) { $Mode = if ($Prof.VirtualDisplay) { 'virtual' } else { 'mirror' } }
    $companion = Get-CompanionFor $DeviceTag
    if (Get-RunningFor $Serial) {
        Show-Toast "$Name is already being mirrored." 'warn'
        return
    }
    $tokens = New-Object System.Collections.Generic.List[string]
    $tokens.Add('-s'); $tokens.Add($Serial)
    if (-not $Background) { $tokens.Add("--window-title=$Name") }
    $windowOnly = @('--always-on-top', '--fullscreen', '--window-borderless')
    foreach ($t in (Get-ProfileArgs $Prof)) {
        if ($Background -and ($windowOnly -contains $t)) { continue }
        $tokens.Add($t)
    }
    $recFile = $null
    if ($Record) {
        $dir = [string]$State.RecordDir
        if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
        $fmt = if ($Background) { 'mkv' } else { [string]$State.RecordFormat }
        $recFile = Join-Path $dir ('{0}_{1}.{2}' -f (Safe-Name $Name), (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'), $fmt)
        $tokens.Add("--record=$recFile")
        if ([int]$State.TimeLimit -gt 0) { $tokens.Add("--time-limit=$([int]$State.TimeLimit)") }
        if ($Background) {
            $tokens.Add('--no-window')
            if ($Prof.Audio) { $tokens.Add('--no-audio-playback') }
        }
    }
    $argLine = (@($tokens | ForEach-Object { Quote-Token $_ })) -join ' '
    if ($Prof.ExtraArgs) { $argLine += ' ' + ([string]$Prof.ExtraArgs).Trim() }
    Log "Starting $Name with profile '$($Prof.Name)'"
    Log "scrcpy $argLine"
    try {
        $p = [System.Diagnostics.Process]::Start((New-Psi $App.Scrcpy $argLine $true))
    } catch {
        Log "Could not start scrcpy: $($_.Exception.Message)" 'bad'
        Show-Toast 'Could not start scrcpy. Check Settings > App.' 'bad'
        if ($companion) { Send-PhoneStatus $Serial 'error' $Mode }
        return
    }
    $s = [pscustomobject]@{
        Id = [guid]::NewGuid().ToString(); Serial = $Serial; Name = $Name; ProfileName = $Prof.Name; DeviceTag = $DeviceTag; Mode = $Mode
        Proc = $p; Started = (Get-Date); RecFile = $recFile; Background = $Background; Fps = ''
        Ended = $false; StopRequested = $false; StopAt = $null; ExitAt = $null
        Tail = (New-Object System.Collections.ArrayList); Readers = @()
        UiRow = $null; UiTime = $null; UiFps = $null
    }
    $s.Readers = @((New-LineReader $p.StandardOutput), (New-LineReader $p.StandardError))
    [void]$App.Sessions.Add($s)
    Add-SessionRow $s
    Update-Status
    if ($Background) { Show-Toast "Recording $Name in the background." 'ok' }
    elseif ($Record) { Show-Toast "Mirroring and recording $Name." 'ok' }
    else { Show-Toast "Mirroring $Name." 'ok' }
    if ($Prof.Mouse -eq 'uhid' -and -not $Prof.NoControl) { Log 'Physical mouse is on: press Left Alt to release the cursor from the phone window.' 'warn' }
    if ($companion) { Send-PhoneStatus $Serial 'running' $Mode }
}

function Add-SessionRow($s) {
    $row = New-Row
    $g = New-Object System.Windows.Controls.Grid
    Add-Col $g 'Auto'; Add-Col $g '*'; Add-Col $g 'Auto'; Add-Col $g 'Auto'
    $glyph = if ($s.Background) { 0xE7C8 } else { 0xE8EA }
    Put $g (New-IconCircle $glyph '#3DDC97') 0

    $info = New-Object System.Windows.Controls.StackPanel
    $info.VerticalAlignment = 'Center'
    [void]$info.Children.Add((New-Text $s.Name 14 ([System.Windows.FontWeights]::SemiBold)))
    $sub = "$($s.ProfileName)  $Dot  $(Format-Serial $s.Serial)"
    if ($s.Background) { $sub = "Background recording  $Dot  $sub" }
    $st = New-Text $sub 12 $null '#A3ACB9'
    $st.Margin = '0,2,0,0'
    [void]$info.Children.Add($st)
    Put $g $info 1

    $stats = New-Object System.Windows.Controls.StackPanel
    $stats.Orientation = 'Horizontal'
    $stats.VerticalAlignment = 'Center'
    $stats.Margin = '10,0,10,0'
    if ($s.RecFile) {
        $rec = New-Badge "$Bullet REC" '#FF5C6C'
        [void]$stats.Children.Add($rec)
        Start-Pulse $rec 0.45 700
    }
    $fps = New-Badge '' '#5B8CFF'
    $fps.Visibility = 'Collapsed'
    [void]$stats.Children.Add($fps)
    $time = New-Text '00:00' 13 ([System.Windows.FontWeights]::SemiBold) '#C9CFD8'
    $time.Margin = '4,0,0,0'
    $time.FontFamily = New-Object System.Windows.Media.FontFamily('Cascadia Mono, Consolas')
    [void]$stats.Children.Add($time)
    Put $g $stats 2

    $btns = New-Object System.Windows.Controls.StackPanel
    $btns.Orientation = 'Horizontal'
    $btns.VerticalAlignment = 'Center'
    [void]$btns.Children.Add((New-IconBtn 0xE722 'Screenshot' $s.Id { param($b, $e) Take-SessionShot $b.Tag }))
    [void]$btns.Children.Add((New-Btn 'Stop' 0xE71A 'DangerBtn' $s.Id { param($b, $e) Stop-Session $b.Tag }))
    Put $g $btns 3

    $row.Child = $g
    $s.UiRow = $row
    $s.UiTime = $time
    $s.UiFps = $fps
    Add-Entrance $row
    [void]$UI.SessionList.Children.Add($row)
}

function Stop-Session([string]$Id) {
    $s = $App.Sessions | Where-Object { $_.Id -eq $Id } | Select-Object -First 1
    if (-not $s -or $s.Ended) { return }
    $s.StopRequested = $true
    $s.StopAt = Get-Date
    try {
        if ($s.Proc.HasExited) { return }
        if (-not $s.Background) {
            $s.Proc.Refresh()
            if ($s.Proc.MainWindowHandle -ne [IntPtr]::Zero -and $s.Proc.CloseMainWindow()) {
                Log "Closing $($s.Name)..."
                return
            }
        }
        $s.Proc.Kill()
    } catch {}
}

function Handle-ScrcpyLine($s, [string]$Line) {
    if ($Line -match '^\s*INFO:\s+(\d+)\s+fps') { $s.Fps = $Matches[1]; return }
    [void]$s.Tail.Add($Line)
    if ($s.Tail.Count -gt 40) { $s.Tail.RemoveAt(0) }
    if ($Line -match '^\s*ERROR') { Log "[$($s.Name)] $Line" 'bad' }
    elseif ($Line -match '^\s*WARN') { Log "[$($s.Name)] $Line" 'warn' }
    elseif ($Line -match 'Device:|Recording started|Recording complete|Renderer:') { Log "[$($s.Name)] $($Line.Trim())" }
}

function Finish-Session($s) {
    $s.Ended = $true
    if ($s.UiRow) {
        $row = $s.UiRow
        $list = $UI.SessionList
        $fade = New-Anim 1 0 280 $false
        $fade.Add_Completed({ [void]$list.Children.Remove($row) }.GetNewClosure())
        $row.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
    }
    $App.Sessions.Remove($s)
    $code = 0
    try { $code = $s.Proc.ExitCode } catch {}
    if (Get-CompanionFor $s.DeviceTag) {
        $endState = if ($s.StopRequested -or $code -eq 0) { 'idle' } else { 'error' }
        Send-PhoneStatus $s.Serial $endState $s.Mode
    }
    if ($s.StopRequested -or $code -eq 0) {
        Log "$($s.Name): mirror closed." 'ok'
    } else {
        $tail = @($s.Tail | Where-Object { $_ -match '\S' })
        $lastLines = if ($tail.Count -gt 8) { $tail[($tail.Count - 8)..($tail.Count - 1)] } else { $tail }
        Log "$($s.Name): scrcpy stopped (code $code)." 'bad'
        if ($lastLines.Count) { Log ($lastLines -join "`n") 'bad' }
        $joined = $tail -join "`n"
        if ($joined -match 'Could not find any ADB device|not found|device offline') {
            Log 'The phone is not connected anymore. Reconnect it from Home or Devices.' 'warn'
        } elseif ($joined -match 'Unauthorized|unauthorized') {
            Log 'Tap Allow on the phone (USB debugging prompt), then try again.' 'warn'
        } elseif ($joined -match 'INJECT_EVENTS|injecting|permission') {
            Log 'Xiaomi/Redmi/POCO: turn on "USB debugging (Security settings)" in Developer options.' 'warn'
        } elseif ($joined -match 'encoder|codec') {
            Log 'The phone may not support this codec or size. Try H.264 or a lower resolution in Settings.' 'warn'
        }
        Show-Toast "$($s.Name) stopped. See Activity for details." 'bad'
    }
    if ($s.RecFile) {
        if (Test-Path -LiteralPath $s.RecFile) {
            Log "Recording saved: $($s.RecFile)" 'ok'
            Show-Toast 'Recording saved to Recordings.' 'ok'
            Refresh-Media
        } else {
            Log 'No recording file was written.' 'warn'
        }
    }
    Update-Status
}

function Poll-Sessions {
    foreach ($s in @($App.Sessions)) {
        if ($s.Ended) { continue }
        foreach ($r in $s.Readers) {
            $n = 0
            while (-not $r.Done -and $r.T.IsCompleted -and $n -lt 200) {
                $n++
                $line = $null
                try { $line = $r.T.Result } catch { $r.Done = $true; break }
                if ($null -eq $line) { $r.Done = $true }
                else {
                    Handle-ScrcpyLine $s $line
                    try { $r.T = $r.R.ReadLineAsync() } catch { $r.Done = $true }
                }
            }
        }
        if ($s.StopAt -and -not $s.Proc.HasExited -and ((Get-Date) - $s.StopAt).TotalSeconds -gt 5) {
            try { $s.Proc.Kill() } catch {}
        }
        if ($s.Proc.HasExited) {
            if (-not $s.ExitAt) { $s.ExitAt = Get-Date }
            $pending = @($s.Readers | Where-Object { -not $_.Done }).Count
            if ($pending -eq 0 -or ((Get-Date) - $s.ExitAt).TotalSeconds -gt 2) { Finish-Session $s }
            continue
        }
        $s.UiTime.Text = Format-Elapsed ((Get-Date) - $s.Started)
        if ($s.Fps) {
            $s.UiFps.Child.Text = "$($s.Fps) FPS"
            $s.UiFps.Visibility = 'Visible'
        }
    }
}

# =====================================================================
#  Screenshots
# =====================================================================
function Save-Screenshot([string]$Serial, [string]$Name) {
    $dir = [string]$State.ShotDir
    if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
    $file = Join-Path $dir ('{0}_{1}.png' -f (Safe-Name $Name), (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'))
    $p = [System.Diagnostics.Process]::Start((New-Psi $App.Adb "-s $Serial exec-out screencap -p" $true))
    $fs = [System.IO.File]::Create($file)
    try {
        $copy = $p.StandardOutput.BaseStream.CopyToAsync($fs)
        $errT = $p.StandardError.ReadToEndAsync()
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        while (-not $copy.IsCompleted -and $sw.Elapsed.TotalSeconds -lt 25) { Invoke-UIEvents; Start-Sleep -Milliseconds 25 }
        if (-not $copy.IsCompleted) { try { $p.Kill() } catch {} }
    } finally {
        $fs.Close()
    }
    $len = (Get-Item -LiteralPath $file).Length
    if ($len -lt 200) {
        Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
        Log 'Screenshot failed. Is the phone still connected?' 'bad'
        Show-Toast 'Screenshot failed.' 'bad'
        return
    }
    Log "Screenshot saved: $file" 'ok'
    Show-Toast 'Screenshot saved to Recordings.' 'ok'
    Refresh-Media
}

function Take-SessionShot([string]$Id) {
    $s = $App.Sessions | Where-Object { $_.Id -eq $Id } | Select-Object -First 1
    if ($s) { Save-Screenshot $s.Serial $s.Name }
}

# =====================================================================
#  Connecting
# =====================================================================
function Connect-SavedDevice($Dev) {
    $devs = @(Get-AdbDevices)
    $ip = Get-IpOf $Dev.Address
    foreach ($d in $devs) {
        $match = $false
        if ($ip -and ($d.Serial -eq $Dev.Address -or $d.Serial -like "${ip}:*")) { $match = $true }
        if ($Dev.HwSerial -and ($d.Serial -eq $Dev.HwSerial -or $d.Serial -like "adb-$($Dev.HwSerial)-*")) { $match = $true }
        if ($match) {
            if ($d.State -eq 'device') { return $d.Serial }
            if ($d.State -eq 'unauthorized') {
                Log "$($Dev.Name) is waiting for you: tap Allow on the phone's USB debugging prompt." 'warn'
                return $null
            }
        }
    }
    if (-not $ip -and -not $Dev.HwSerial) {
        Log "$($Dev.Name) has no Wi-Fi address yet. Add it again with the QR code on the Devices page." 'warn'
        return $null
    }

    # 1) Wireless debugging (no cable): the phone announces itself on the network
    Set-BusyText "Looking for $($Dev.Name) on your Wi-Fi..."
    $tried = @()
    for ($round = 0; $round -lt 2; $round++) {
        foreach ($m in @(Get-MdnsServices)) {
            $hit = ($ip -and $m.Ip -eq $ip)
            if ($Dev.HwSerial -and $m.Name -like "adb-$($Dev.HwSerial)-*") { $hit = $true }
            $a2 = "$($m.Ip):$($m.Port)"
            if ($hit -and $tried -notcontains $a2) {
                $tried += $a2
                Set-BusyText "Connecting to $($Dev.Name) ($a2)..."
                $r2 = Invoke-Adb "connect $a2" 12
                if ($r2.Text -match 'connected to') {
                    Log $r2.Text 'ok'
                    if ($m.Ip -ne $ip) { $Dev.Address = $m.Ip; Save-State; Log "$($Dev.Name) has a new IP: $($m.Ip)" }
                    Wait-UI 300
                    return $a2
                }
                if ($r2.Text -match 'authenticat') { Log "$($Dev.Name) needs pairing again: use the QR code on the Devices page." 'warn' }
            }
        }
        if ($tried.Count -eq 0 -and $round -eq 0) { Wait-UI 1500 }
    }

    # 2) Classic wireless mode (set up with a cable, port 5555 or a saved port)
    if ($ip) {
        $addr = Normalize-Address $Dev.Address
        if ($tried -notcontains $addr) {
            Set-BusyText "Connecting to $($Dev.Name) ($addr)..."
            $r = Invoke-Adb "connect $addr" 12
            if ($r.Text -match 'connected to') {
                Log $r.Text 'ok'
                Wait-UI 300
                return $addr
            }
        }
    }
    if ($Dev.Companion) {
        Log "Could not reach $($Dev.Name). On the phone, open Flow Connect (or tap the 'PC connect' quick tile) to turn Wireless debugging on, and check it is on the same Wi-Fi as this PC." 'bad'
    } else {
        Log "Could not reach $($Dev.Name). On the phone, check that Wireless debugging is ON (it turns off after a restart or a Wi-Fi change) and that it is on the same Wi-Fi as this PC." 'bad'
    }
    return $null
}

function Get-DeviceTargets {
    $list = @()
    foreach ($d in $State.Devices) {
        $where = if ($d.Address) { [string]$d.Address } else { 'USB only' }
        $list += [pscustomobject]@{ Tag = "saved:$($d.Id)"; Label = "$($d.Name)   $Dot   $where" }
    }
    foreach ($x in $App.Detected) {
        if ($x.State -eq 'device' -and -not $x.SavedId) {
            $nm = if ($x.Model) { $x.Model } else { $x.Serial }
            $list += [pscustomobject]@{ Tag = "adb:$($x.Serial)"; Label = "$nm   $Dot   $($x.Type), not saved" }
        }
    }
    return $list
}

function Resolve-Target([string]$Tag) {
    if (-not $Tag) { return $null }
    if ($Tag -like 'saved:*') {
        $d = Get-Device $Tag.Substring(6)
        if ($d) { return [pscustomobject]@{ Name = $d.Name; Device = $d; Serial = $null; Tag = $Tag } }
    }
    if ($Tag -like 'adb:*') {
        $ser = $Tag.Substring(4)
        $x = $App.Detected | Where-Object { $_.Serial -eq $ser } | Select-Object -First 1
        $nm = $ser
        if ($x -and $x.Model) { $nm = $x.Model }
        return [pscustomobject]@{ Name = $nm; Device = $null; Serial = $ser; Tag = $Tag }
    }
    return $null
}

function Ensure-Connected($T) {
    if ($T.Serial) {
        $ok = @(Get-AdbDevices | Where-Object { $_.Serial -eq $T.Serial -and $_.State -eq 'device' })
        if ($ok.Count) { return $T.Serial }
        Log "$($T.Name) is no longer connected. Click Scan on the Devices page." 'bad'
        return $null
    }
    return (Connect-SavedDevice $T.Device)
}

function Update-InfoFromPhone([string]$Serial, $T) {
    $info = Get-PhoneInfo $Serial
    if (-not $info) { return }
    $UI.InfoName.Text = $T.Name
    $UI.InfoAndroid.Text = $info.Android
    if ($info.Battery) {
        $UI.InfoBattery.Text = "$($info.Battery)%" + $(if ($info.Charging) { ' (charging)' } else { '' })
    }
    $UI.InfoConn.Text = if ($Serial -match '^\d{1,3}(\.\d{1,3}){3}:\d+$' -or $Serial -match '_adb-tls') { 'Wi-Fi' } else { 'USB' }
    $UI.InfoAddr.Text = (("$($info.Brand) $($info.Model)").Trim() + "   $Dot   " + (Format-Serial $Serial))
    if ($T.Device) {
        $changed = $false
        if (-not $T.Device.Model -and $info.Model) { $T.Device.Model = $info.Model; $changed = $true }
        if (-not $T.Device.HwSerial -and $info.HwSerial) { $T.Device.HwSerial = $info.HwSerial; $changed = $true }
        if ($changed) { Save-State }
    }
}

function Go-Wireless([string]$OnlySerial = '') {
    Set-BusyText 'Looking for a phone on USB...'
    $all = @(Get-AdbDevices)
    $usb = @($all | Where-Object { $_.Type -eq 'USB' })
    if ($OnlySerial) { $usb = @($usb | Where-Object { $_.Serial -eq $OnlySerial }) }
    if ($usb.Count -eq 0) {
        Log 'No phone found on USB. Plug it in, turn on USB debugging, and use a cable that supports data.' 'bad'
        return $null
    }
    $ready = @($usb | Where-Object { $_.State -eq 'device' })
    if ($ready.Count -eq 0) {
        if (@($usb | Where-Object { $_.State -eq 'unauthorized' }).Count) {
            Log 'The phone is asking "Allow USB debugging?". Tap Allow (tick Always allow), then try again.' 'warn'
        } else {
            Log 'The phone shows as offline. Unplug and plug the cable back in.' 'warn'
        }
        return $null
    }
    if ($ready.Count -gt 1) { Log 'More than one phone is plugged in; using the first one.' 'warn' }
    $serial = $ready[0].Serial
    Set-BusyText 'Reading phone details...'
    $info = Get-PhoneInfo $serial
    $ip = Get-PhoneWifiIp $serial
    if (-not $ip) {
        Log 'The phone is not on Wi-Fi. Connect it to the same Wi-Fi as this PC.' 'bad'
        return $null
    }
    Set-BusyText "Switching to Wi-Fi ($ip)..."
    $t = Invoke-Adb "-s $serial tcpip 5555" 15
    if ($t.Text) { Log $t.Text }
    $target = "${ip}:5555"
    $ok = $false
    for ($i = 1; $i -le 6 -and -not $ok; $i++) {
        Wait-UI 1200
        $r = Invoke-Adb "connect $target" 10
        if ($r.Text -match 'connected to') { $ok = $true; Log $r.Text 'ok' }
    }
    if (-not $ok) {
        Log "Could not connect to $target over Wi-Fi. Both must be on the same network (guest Wi-Fi often blocks this)." 'bad'
        return $null
    }
    $hw = if ($info) { $info.HwSerial } else { $serial }
    if (-not $hw) { $hw = $serial }
    $dev = Find-SavedMatch $target $hw
    if (-not $dev) {
        $nm = 'Phone'
        if ($info -and $info.Model) { $nm = $info.Model }
        $dev = New-DeviceObj @{ Name = $nm; Profile = 'Balanced' }
        $State.Devices = @($State.Devices) + $dev
        if (-not $State.DefaultDevice) { $State.DefaultDevice = $dev.Id }
        Log "Saved new phone: $nm" 'ok'
    }
    $dev.Address = $ip
    $dev.HwSerial = $hw
    if ($info -and $info.Model) { $dev.Model = $info.Model }
    Save-State
    Log 'Wireless is ready. You can unplug the cable now.' 'ok'
    return [pscustomobject]@{ Serial = $target; Device = $dev }
}

# =====================================================================
#  Device lists (Devices page + combos)
# =====================================================================
function Scan-Devices {
    $devs = @(Get-AdbDevices)
    $mdns = @(Get-MdnsServices)
    $det = @()
    foreach ($d in $devs) {
        $hw = ''
        if ($d.Type -eq 'USB') { $hw = $d.Serial }
        elseif ($d.Serial -match '_adb-tls') { $hw = Get-HwFromName $d.Serial }
        elseif ($d.State -eq 'device') {
            $r = Invoke-Adb "-s $($d.Serial) shell getprop ro.serialno" 6
            $hw = $r.Out.Trim()
        }
        $saved = Find-SavedMatch $d.Serial $hw
        $sid = ''
        if ($saved) {
            $sid = $saved.Id
            if (-not $saved.HwSerial -and $hw) { $saved.HwSerial = $hw }
            if (-not $saved.Model -and $d.Model) { $saved.Model = $d.Model }
        }
        $det += [pscustomobject]@{ Serial = $d.Serial; State = $d.State; Model = $d.Model; Type = $d.Type; HwSerial = $hw; SavedId = $sid; Ip = ''; Port = '' }
    }
    foreach ($m in $mdns) {
        $already = @($det | Where-Object { $_.Serial -like "$($m.Ip):*" -or $_.Serial -like "$($m.Name)*" })
        if ($already.Count) { continue }
        $hw = Get-HwFromName $m.Name
        $saved = Find-SavedMatch "$($m.Ip):$($m.Port)" $hw
        $sid = ''
        if ($saved) { $sid = $saved.Id }
        $det += [pscustomobject]@{ Serial = $m.Name; State = 'nearby'; Model = ''; Type = 'Nearby'; HwSerial = $hw; SavedId = $sid; Ip = $m.Ip; Port = $m.Port }
    }
    $App.Detected = $det
    Save-State
    Render-Detected
    Render-Saved
    Refresh-DeviceCombos
    $ready = @($det | Where-Object { $_.State -eq 'device' }).Count
    Set-DotColor $UI.AdbDot $Colors.ok
    $UI.AdbText.Text = "adb ready  $Dot  $ready connected"
}

function Render-Detected {
    $UI.DetectList.Children.Clear()
    $UI.DetectEmpty.Visibility = if (@($App.Detected).Count -eq 0) { 'Visible' } else { 'Collapsed' }
    foreach ($x in $App.Detected) {
        $row = New-Row
        $g = New-Object System.Windows.Controls.Grid
        Add-Col $g 'Auto'; Add-Col $g '*'; Add-Col $g 'Auto'
        $glyph = if ($x.Type -eq 'USB') { 0xE88E } else { 0xE701 }
        $dotColor = switch ($x.State) { 'device' { '#3DDC97' } 'unauthorized' { '#FFB547' } 'nearby' { '#5B8CFF' } default { '#FF5C6C' } }
        Put $g (New-IconCircle $glyph $dotColor) 0

        $info = New-Object System.Windows.Controls.StackPanel
        $info.VerticalAlignment = 'Center'
        $title = if ($x.Model) { $x.Model } elseif ($x.Type -eq 'Nearby') { "Phone at $($x.Ip)" } else { $x.Serial }
        [void]$info.Children.Add((New-Text $title 14 ([System.Windows.FontWeights]::SemiBold)))
        $line2 = New-Object System.Windows.Controls.StackPanel
        $line2.Orientation = 'Horizontal'
        $line2.Margin = '0,4,0,0'
        switch ($x.State) {
            'device'       { [void]$line2.Children.Add((New-Badge "Ready $Dot $($x.Type)" '#3DDC97')) }
            'unauthorized' { [void]$line2.Children.Add((New-Badge 'Tap Allow on the phone' '#FFB547')) }
            'nearby'       { [void]$line2.Children.Add((New-Badge 'Wireless debugging' '#5B8CFF')) }
            default        { [void]$line2.Children.Add((New-Badge $x.State '#FF5C6C')) }
        }
        if ($x.SavedId) {
            $sd = Get-Device $x.SavedId
            if ($sd) { [void]$line2.Children.Add((New-Text "Saved as $($sd.Name)" 12 $null '#A3ACB9')) }
        } else {
            $shown = if ($x.Type -eq 'Nearby') { "$($x.Ip):$($x.Port)" } else { Format-Serial $x.Serial }
            [void]$line2.Children.Add((New-Text $shown 12 $null '#A3ACB9'))
        }
        [void]$info.Children.Add($line2)
        Put $g $info 1

        $btns = New-Object System.Windows.Controls.StackPanel
        $btns.Orientation = 'Horizontal'
        $btns.VerticalAlignment = 'Center'
        if ($x.State -eq 'device') {
            [void]$btns.Children.Add((New-Btn 'Mirror' 0xE768 'AccentBtn' $x.Serial { param($b, $e) Mirror-Detected $b.Tag }))
            if ($x.Type -eq 'USB') {
                [void]$btns.Children.Add((New-Btn 'Go wireless' 0xE701 'BtnBase' $x.Serial { param($b, $e) Run-GoWireless $b.Tag $false }))
            }
            if (-not $x.SavedId) {
                [void]$btns.Children.Add((New-Btn 'Save' 0xE74E 'BtnBase' $x.Serial { param($b, $e) Save-Detected $b.Tag }))
            }
        } elseif ($x.State -eq 'nearby') {
            [void]$btns.Children.Add((New-Btn 'Connect' 0xE71B 'AccentBtn' $x.Serial { param($b, $e) Connect-Nearby $b.Tag }))
        }
        Put $g $btns 2
        $row.Child = $g
        Add-Entrance $row ("det:" + $x.Serial + ":" + $x.State)
        [void]$UI.DetectList.Children.Add($row)
    }
}

function Render-Saved {
    $UI.SavedList.Children.Clear()
    $UI.SavedEmpty.Visibility = if (@($State.Devices).Count -eq 0) { 'Visible' } else { 'Collapsed' }
    $UI.HomeEmptyBanner.Visibility = if (@($State.Devices).Count -eq 0) { 'Visible' } else { 'Collapsed' }
    foreach ($d in $State.Devices) {
        $det = $App.Detected | Where-Object { $_.SavedId -eq $d.Id -and $_.State -eq 'device' } | Select-Object -First 1
        $row = New-Row
        $g = New-Object System.Windows.Controls.Grid
        Add-Col $g 'Auto'; Add-Col $g '*'; Add-Col $g '200'; Add-Col $g 'Auto'
        $dotColor = if ($det) { '#3DDC97' } else { '#6B7380' }
        Put $g (New-IconCircle 0xE8EA $dotColor) 0

        $info = New-Object System.Windows.Controls.StackPanel
        $info.VerticalAlignment = 'Center'
        $nameLine = New-Object System.Windows.Controls.StackPanel
        $nameLine.Orientation = 'Horizontal'
        [void]$nameLine.Children.Add((New-Text $d.Name 14 ([System.Windows.FontWeights]::SemiBold)))
        if ($State.DefaultDevice -eq $d.Id) {
            $star = New-Glyph 0xE735 12 '#FFB547'
            $star.Margin = '8,0,0,0'
            [void]$nameLine.Children.Add($star)
        }
        [void]$info.Children.Add($nameLine)
        $parts = @()
        if ($d.Address) { $parts += [string]$d.Address } else { $parts += 'No Wi-Fi address yet' }
        if ($d.Model -and [string]$d.Model -ne [string]$d.Name) { $parts += [string]$d.Model }
        if ($det) { $parts += "connected ($($det.Type))" } else { $parts += 'not connected' }
        $sub = New-Text ($parts -join "  $Dot  ") 12 $null '#A3ACB9'
        $sub.Margin = '0,3,0,0'
        [void]$info.Children.Add($sub)
        Put $g $info 1

        $cb = New-Object System.Windows.Controls.ComboBox
        $cb.Margin = '10,0,6,0'
        $cb.VerticalAlignment = 'Center'
        $cb.ToolTip = 'Profile used for this phone'
        foreach ($p in $State.Profiles) {
            $it = New-Object System.Windows.Controls.ComboBoxItem
            $it.Content = $p.Name
            $it.Tag = $p.Name
            [void]$cb.Items.Add($it)
        }
        [void](Select-ComboTag $cb $d.Profile)
        $cb.Tag = $d.Id
        $cb.Add_SelectionChanged({
            param($c, $e)
            $dv = Get-Device $c.Tag
            $pn = Get-ComboTag $c
            if ($dv -and $pn -and $dv.Profile -ne $pn) {
                $dv.Profile = [string]$pn
                Save-State
                Sync-HomeProfile
                Show-Toast "$($dv.Name) now uses '$pn'." 'ok'
            }
        })
        Put $g $cb 2

        $btns = New-Object System.Windows.Controls.StackPanel
        $btns.Orientation = 'Horizontal'
        $btns.VerticalAlignment = 'Center'
        [void]$btns.Children.Add((New-Btn 'Mirror' 0xE768 'AccentBtn' $d.Id { param($b, $e) Mirror-Saved $b.Tag }))
        $starColor = if ($State.DefaultDevice -eq $d.Id) { '#FFB547' } else { '' }
        [void]$btns.Children.Add((New-IconBtn 0xE734 'Make this my default phone' $d.Id { param($b, $e) Set-DefaultDevice $b.Tag } $starColor))
        $appTip = if ($d.Companion) { 'Flow Connect is installed (click to reinstall)' } else { 'Install phone app (Flow Connect): one-tap connect, stays on after restarts' }
        $appColor = if ($d.Companion) { '#3DDC97' } else { '' }
        [void]$btns.Children.Add((New-IconBtn 0xE896 $appTip $d.Id { param($b, $e) Install-CompanionUi $b.Tag } $appColor))
        [void]$btns.Children.Add((New-IconBtn 0xE70F 'Rename / edit address' $d.Id { param($b, $e) Edit-Device $b.Tag }))
        [void]$btns.Children.Add((New-IconBtn 0xE74D 'Remove' $d.Id { param($b, $e) Remove-Device $b.Tag } '#FF8A95'))
        Put $g $btns 3
        $row.Child = $g
        Add-Entrance $row ("saved:" + $d.Id)
        [void]$UI.SavedList.Children.Add($row)
    }
}

function Fill-DeviceCombo($cb, [string]$SelectTag) {
    $was = $App.Syncing
    $App.Syncing = $true
    try {
        $cb.Items.Clear()
        foreach ($t in (Get-DeviceTargets)) {
            $it = New-Object System.Windows.Controls.ComboBoxItem
            $it.Content = $t.Label
            $it.Tag = $t.Tag
            [void]$cb.Items.Add($it)
        }
        if (-not ($SelectTag -and (Select-ComboTag $cb $SelectTag))) {
            if ($cb.Items.Count -gt 0) { $cb.SelectedIndex = 0 }
        }
    } finally { $App.Syncing = $was }
}

function Refresh-DeviceCombos {
    $tag = [string](Get-ComboTag $UI.HomeDevice)
    if (-not $tag) { $tag = [string]$State.LastDevice }
    if (-not $tag -and $State.DefaultDevice) { $tag = "saved:$($State.DefaultDevice)" }
    Fill-DeviceCombo $UI.HomeDevice $tag
    Fill-DeviceCombo $UI.GameDevice ([string](Get-ComboTag $UI.HomeDevice))
    On-HomeDeviceChanged
}

function Refresh-ProfileCombos {
    $App.Syncing = $true
    try {
        foreach ($cb in @($UI.HomeProfile, $UI.SProfile)) {
            $cur = [string](Get-ComboTag $cb)
            $cb.Items.Clear()
            foreach ($p in $State.Profiles) {
                $it = New-Object System.Windows.Controls.ComboBoxItem
                $label = $p.Name
                if ($p.BuiltIn) { $label = "$($p.Name)" }
                $it.Content = $label
                $it.Tag = $p.Name
                [void]$cb.Items.Add($it)
            }
            if (-not ($cur -and (Select-ComboTag $cb $cur))) { $cb.SelectedIndex = 0 }
        }
        [void](Select-ComboTag $UI.SProfile $App.EditingProfile)
    } finally { $App.Syncing = $false }
}

function Sync-HomeProfile {
    $t = Resolve-Target ([string](Get-ComboTag $UI.HomeDevice))
    if ($t -and $t.Device) {
        $App.Syncing = $true
        try { [void](Select-ComboTag $UI.HomeProfile $t.Device.Profile) } finally { $App.Syncing = $false }
    }
    $UI.InfoProfile.Text = [string](Get-ComboTag $UI.HomeProfile)
}

function On-HomeDeviceChanged {
    $tag = [string](Get-ComboTag $UI.HomeDevice)
    $t = Resolve-Target $tag
    if (-not $t) {
        $UI.InfoName.Text = 'No phone'
        $UI.InfoAddr.Text = 'Add one on the Devices page.'
        $UI.InfoBattery.Text = '-'; $UI.InfoAndroid.Text = '-'; $UI.InfoConn.Text = '-'
        return
    }
    $State.LastDevice = $tag
    $UI.InfoName.Text = $t.Name
    $conn = $null
    if ($t.Device) {
        $parts = @()
        if ($t.Device.Model) { $parts += [string]$t.Device.Model }
        $parts += $(if ($t.Device.Address) { [string]$t.Device.Address } else { 'USB only' })
        $UI.InfoAddr.Text = $parts -join "   $Dot   "
        $conn = $App.Detected | Where-Object { $_.SavedId -eq $t.Device.Id -and $_.State -eq 'device' } | Select-Object -First 1
    } else {
        $UI.InfoAddr.Text = Format-Serial $t.Serial
        $conn = $App.Detected | Where-Object { $_.Serial -eq $t.Serial } | Select-Object -First 1
    }
    $UI.InfoConn.Text = if ($conn) { $conn.Type } else { 'Not connected' }
    $UI.InfoBattery.Text = '-'
    $UI.InfoAndroid.Text = '-'
    Play-FadeIn $UI.InfoName 180
    Play-FadeIn $UI.InfoAddr 180
    Sync-HomeProfile
}

# =====================================================================
#  Actions
# =====================================================================
function Start-FromHome {
    $t = Resolve-Target ([string](Get-ComboTag $UI.HomeDevice))
    if (-not $t) { Show-Toast 'No phone selected. Add one on the Devices page.' 'warn'; return }
    $prof = Get-Profile ([string](Get-ComboTag $UI.HomeProfile))
    Show-Busy "Connecting to $($t.Name)..."
    try {
        $serial = Ensure-Connected $t
        if ($serial) {
            Set-BusyText 'Reading phone info...'
            Update-InfoFromPhone $serial $t
        }
    } finally { Hide-Busy }
    if (-not $serial) { Show-Toast "Could not connect to $($t.Name). See Activity." 'bad'; return }
    Start-Session -Serial $serial -Name $t.Name -Prof $prof -Record ([bool]$UI.HomeRecord.IsChecked) -Background ([bool]($UI.HomeRecord.IsChecked -and $UI.HomeBackground.IsChecked)) -DeviceTag $t.Tag
}

function Run-GoWireless([string]$OnlySerial = '', [bool]$ThenMirror = $true) {
    Show-Busy 'Switching your phone to Wi-Fi...'
    $res = $null
    try { $res = Go-Wireless $OnlySerial } finally { Hide-Busy }
    if (-not $res) { Show-Toast 'Could not go wireless. See Activity on Home.' 'bad'; return }
    Show-Busy 'Updating device list...'
    try { Scan-Devices } finally { Hide-Busy }
    $tag = "saved:$($res.Device.Id)"
    [void](Select-ComboTag $UI.HomeDevice $tag)
    Show-Toast "$($res.Device.Name) is wireless now. You can unplug the cable." 'ok'
    if ($ThenMirror) {
        $prof = Get-Profile $res.Device.Profile
        Start-Session -Serial $res.Serial -Name $res.Device.Name -Prof $prof -DeviceTag $tag
    }
}

function Mirror-Detected([string]$Serial) {
    $x = $App.Detected | Where-Object { $_.Serial -eq $Serial } | Select-Object -First 1
    if (-not $x) { return }
    $name = if ($x.Model) { $x.Model } else { $Serial }
    $profName = [string](Get-ComboTag $UI.HomeProfile)
    $tag = "adb:$Serial"
    if ($x.SavedId) {
        $d = Get-Device $x.SavedId
        if ($d) { $name = $d.Name; $profName = $d.Profile; $tag = "saved:$($d.Id)" }
    }
    Start-Session -Serial $Serial -Name $name -Prof (Get-Profile $profName) -DeviceTag $tag
}

function Mirror-Saved([string]$Id) {
    $d = Get-Device $Id
    if (-not $d) { return }
    $t = Resolve-Target "saved:$Id"
    Show-Busy "Connecting to $($d.Name)..."
    $serial = $null
    try { $serial = Ensure-Connected $t } finally { Hide-Busy }
    if (-not $serial) { Show-Toast "Could not connect to $($d.Name). See Activity on Home." 'bad'; return }
    Start-Session -Serial $serial -Name $d.Name -Prof (Get-Profile $d.Profile) -DeviceTag "saved:$Id"
}

function Save-Detected([string]$Serial) {
    $x = $App.Detected | Where-Object { $_.Serial -eq $Serial } | Select-Object -First 1
    if (-not $x) { return }
    Show-Busy 'Reading phone details...'
    try {
        $info = Get-PhoneInfo $Serial
        $addr = ''
        if ($x.Type -ne 'USB') {
            $addr = Get-IpOf $Serial
            if ($addr -notmatch '^\d{1,3}(\.\d{1,3}){3}$') { $addr = Get-PhoneWifiIp $Serial }
            if ($Serial -match '^\d{1,3}(\.\d{1,3}){3}:(\d+)$' -and $Matches[2] -ne '5555') { $addr = $Serial }
        }
    } finally { Hide-Busy }
    $suggest = if ($info -and $info.Model) { $info.Model } elseif ($x.Model) { $x.Model } else { 'Phone' }
    $name = Show-Dialog 'Save this phone' 'Give it a name you will recognise.' $true $suggest 'Save'
    if ($null -eq $name) { return }
    if (-not $name.Trim()) { $name = $suggest }
    $hw = if ($info -and $info.HwSerial) { $info.HwSerial } else { $x.HwSerial }
    $model = if ($info) { $info.Model } else { $x.Model }
    $dev = New-DeviceObj @{ Name = $name.Trim(); Address = [string]$addr; HwSerial = [string]$hw; Model = [string]$model; Profile = 'Balanced' }
    $State.Devices = @($State.Devices) + $dev
    if (-not $State.DefaultDevice) { $State.DefaultDevice = $dev.Id }
    $x.SavedId = $dev.Id
    Save-State
    Render-Detected; Render-Saved; Refresh-DeviceCombos
    Show-Toast "Saved $($dev.Name)." 'ok'
}

function Connect-Nearby([string]$Name) {
    $x = $App.Detected | Where-Object { $_.Serial -eq $Name } | Select-Object -First 1
    if (-not $x) { return }
    $addr = "$($x.Ip):$($x.Port)"
    Show-Busy "Connecting to $addr..."
    $ok = $false
    try {
        $r = Invoke-Adb "connect $addr" 12
        Log $r.Text
        if ($r.Text -match 'connected to') { $ok = $true; Wait-UI 500; Scan-Devices }
        elseif ($r.Text -match 'authenticat') { Log 'This phone is not paired with this PC yet. Use "Pair without cable" below.' 'warn' }
    } finally { Hide-Busy }
    if ($ok) { Show-Toast 'Connected. Click Save to keep this phone.' 'ok' } else { Show-Toast 'Could not connect. See Activity on Home.' 'bad' }
}

function Set-DefaultDevice([string]$Id) {
    $State.DefaultDevice = $Id
    Save-State
    Render-Saved
    $d = Get-Device $Id
    if ($d) { Show-Toast "$($d.Name) is now your default phone." 'ok' }
}

function Edit-Device([string]$Id) {
    $d = Get-Device $Id
    if (-not $d) { return }
    $n = Show-Dialog 'Rename phone' '' $true $d.Name 'Next'
    if ($null -eq $n) { return }
    if ($n.Trim()) { $d.Name = $n.Trim() }
    $a = Show-Dialog 'Wi-Fi address' 'The phone IP address, for example 192.168.1.23. Add :port only for Wireless debugging. Leave empty for USB only.' $true ([string]$d.Address) 'Save'
    if ($null -ne $a) { $d.Address = $a.Trim() }
    Save-State
    Render-Saved; Render-Detected; Refresh-DeviceCombos
    Show-Toast 'Phone updated.' 'ok'
}

function Remove-Device([string]$Id) {
    $d = Get-Device $Id
    if (-not $d) { return }
    $r = Show-Dialog "Remove $($d.Name)?" 'It is only removed from this list. Nothing changes on the phone.' $false '' 'Remove'
    if ($null -eq $r) { return }
    $State.Devices = @($State.Devices | Where-Object { $_.Id -ne $Id })
    if ($State.DefaultDevice -eq $Id) { $State.DefaultDevice = '' }
    foreach ($x in $App.Detected) { if ($x.SavedId -eq $Id) { $x.SavedId = '' } }
    Save-State
    Render-Saved; Render-Detected; Refresh-DeviceCombos
    Show-Toast "Removed $($d.Name)." 'ok'
}

function Complete-Pairing([string]$Ip, $Before) {
    # After a successful "adb pair": find the phone's connection, connect, and save it
    $connected = $null
    Set-BusyText 'Paired! Connecting to the phone...'
    for ($i = 0; $i -lt 6 -and -not $connected; $i++) {
        Wait-UI 1200
        $now = @(Get-AdbDevices | Where-Object { $_.State -eq 'device' })
        foreach ($d in $now) { if ($d.Serial -like "${Ip}:*") { $connected = $d.Serial } }
        if (-not $connected) {
            foreach ($d in $now) {
                if ($d.Serial -match '_adb-tls' -and @($Before) -notcontains $d.Serial) { $connected = $d.Serial }
            }
        }
        if (-not $connected) {
            foreach ($m in @(Get-MdnsServices)) {
                if ($m.Ip -eq $Ip -and -not $connected) {
                    $c = Invoke-Adb "connect $($m.Ip):$($m.Port)" 10
                    if ($c.Text -match 'connected to') { $connected = "$($m.Ip):$($m.Port)" }
                }
            }
        }
    }
    if (-not $connected) {
        Log 'Paired, but the phone did not answer yet. Keep Wireless debugging open on the phone, then click Scan on the Devices page.' 'warn'
        return $null
    }
    Set-BusyText 'Reading phone details...'
    $info = Get-PhoneInfo $connected
    $hw = if ($info) { $info.HwSerial } else { Get-HwFromName $connected }
    $dev = Find-SavedMatch $connected $hw
    if (-not $dev) {
        $nm = 'Phone'
        if ($info -and $info.Model) { $nm = $info.Model }
        $dev = New-DeviceObj @{ Name = $nm; Profile = 'Balanced' }
        $State.Devices = @($State.Devices) + $dev
        if (-not $State.DefaultDevice) { $State.DefaultDevice = $dev.Id }
    }
    $dev.Address = $Ip
    if ($hw) { $dev.HwSerial = $hw }
    if ($info -and $info.Model) { $dev.Model = $info.Model }
    Save-State
    Log "Paired and connected: $($dev.Name) ($Ip)" 'ok'
    if (-not $dev.Companion -and (Find-CompanionApk)) {
        $ans = Show-Dialog 'Install the phone app too?' "Flow Connect lets $($dev.Name) turn Wireless debugging on with one tap, and keeps it on after restarts - so you never need Developer options again." $false '' 'Install'
        if ($null -ne $ans) { [void](Install-CompanionOn $connected $dev) }
    }
    Scan-Devices
    [void](Select-ComboTag $UI.HomeDevice "saved:$($dev.Id)")
    return $dev
}

function Get-ReadySerials {
    return @(Get-AdbDevices | Where-Object { $_.State -eq 'device' } | ForEach-Object { $_.Serial })
}

function Pair-Phone {
    $pa = $UI.PairAddr.Text.Trim()
    $code = $UI.PairCode.Text.Trim()
    if ($pa -notmatch '^\d{1,3}(\.\d{1,3}){3}:\d+$') { Show-Toast 'Enter the IP:port from the pairing pop-up, e.g. 192.168.1.23:37123' 'warn'; return }
    if ($code -notmatch '^\d{6}$') { Show-Toast 'The pairing code has 6 digits.' 'warn'; return }
    Stop-QrPairing ''
    $dev = $null
    Show-Busy "Pairing with $pa..."
    try {
        $before = Get-ReadySerials
        $r = Invoke-Adb "pair $pa $code" 25
        Log $r.Text
        if ($r.Text -notmatch 'Successfully paired') {
            Log 'Pairing failed. The code and port change every time the pop-up opens - check them and try again.' 'bad'
        } else {
            $UI.PairCode.Text = ''
            $dev = Complete-Pairing (Get-IpOf $pa) $before
        }
    } finally { Hide-Busy }
    if ($dev) { Show-Toast "$($dev.Name) is paired and saved. Press Mirror to start." 'ok' }
    else { Show-Toast 'Pairing did not finish. See Activity on Home.' 'bad' }
}

# ---------------------------------------------------------------- QR pairing
$App.QrActive = $false
$App.QrPolling = $false
$App.QrStarted = $null
$App.QrBaseline = @()
$QrTimer = New-Object System.Windows.Threading.DispatcherTimer
$QrTimer.Interval = [TimeSpan]::FromSeconds(2)

function New-RandomText([int]$Length, [string]$Alphabet) {
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    $bytes = New-Object byte[] $Length
    $rng.GetBytes($bytes)
    $sb = New-Object System.Text.StringBuilder
    foreach ($b in $bytes) { [void]$sb.Append($Alphabet[$b % $Alphabet.Length]) }
    return $sb.ToString()
}

# A brand-new pairing QR (random service name + password) for this pairing attempt only
function New-PairingQr {
    $App.QrName = 'flow-' + (New-RandomText 6 'abcdefghijklmnopqrstuvwxyz0123456789')
    $App.QrPass = New-RandomText 12 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789'
    $payload = "WIFI:T:ADB;S:$($App.QrName);P:$($App.QrPass);;"
    $mods = [StudioQr]::EncodeText($payload)
    $n = [StudioQr]::SizeOf()
    $scale = 8
    $quiet = 2
    $pixels = [StudioQr]::Render($mods, $n, $scale, $quiet)
    $w = ($n + 2 * $quiet) * $scale
    $bmp = [System.Windows.Media.Imaging.BitmapSource]::Create($w, $w, 96, 96, [System.Windows.Media.PixelFormats]::Gray8, $null, $pixels, $w)
    $bmp.Freeze()
    return $bmp
}

function Set-QrStatus([string]$Text, [string]$Kind = 'busy') {
    $UI.QrStatusRow.Visibility = if ($Text) { 'Visible' } else { 'Collapsed' }
    $UI.QrStatus.Text = $Text
    $UI.QrDot.Fill = Get-Brush $Colors[$Kind]
}

function Start-QrPairing {
    if ($App.QrActive) { return }
    if (-not $QrReady) {
        Set-QrStatus 'QR pairing is not available on this PC. Use the pairing code below instead.' 'warn'
        return
    }
    try { $UI.QrImg.Source = New-PairingQr } catch {
        Write-Crash $_
        Set-QrStatus 'Could not create the QR code. Use the pairing code below instead.' 'bad'
        return
    }
    $UI.QrPlaceholder.Visibility = 'Collapsed'
    $UI.QrFrame.Visibility = 'Visible'
    $UI.BtnQrStart.Visibility = 'Collapsed'
    $UI.BtnQrCancel.Visibility = 'Visible'
    Set-QrStatus 'Waiting for your phone to scan the code...' 'busy'
    Set-Status 'Waiting for QR scan' 'busy'
    $App.QrBaseline = @(Get-MdnsPairing | ForEach-Object { $_.Name } | Where-Object { $_ -ne $App.QrName })
    $App.QrStarted = Get-Date
    $App.QrActive = $true
    $QrTimer.Start()
    Log 'QR pairing started. On the phone: Developer options > Wireless debugging > Pair device with QR code.'
}

function Stop-QrPairing([string]$Message = '', [string]$Kind = 'idle') {
    $QrTimer.Stop()
    $App.QrActive = $false
    $UI.QrImg.Source = $null
    $UI.QrFrame.Visibility = 'Collapsed'
    $UI.QrPlaceholder.Visibility = 'Visible'
    $UI.BtnQrStart.Visibility = 'Visible'
    $UI.BtnQrCancel.Visibility = 'Collapsed'
    Set-QrStatus $Message $Kind
    Update-Status
}

function Poll-QrPairing {
    if (-not $App.QrActive -or $App.QrPolling) { return }
    $App.QrPolling = $true
    try {
        $secs = ((Get-Date) - $App.QrStarted).TotalSeconds
        if ($secs -gt 180) {
            Stop-QrPairing 'Timed out. Click Show QR code to try again.' 'warn'
            return
        }
        $svc = @(Get-MdnsPairing)
        if (-not $App.QrActive) { return }
        $hit = $svc | Where-Object { $_.Name -eq $App.QrName } | Select-Object -First 1
        if (-not $hit) { $hit = $svc | Where-Object { $App.QrBaseline -notcontains $_.Name } | Select-Object -First 1 }
        if (-not $hit) {
            if ($secs -gt 30) {
                Set-QrStatus 'Still waiting... Make sure the phone is on the same Wi-Fi, and if Windows asked about adb in a firewall pop-up, click Allow.' 'warn'
            }
            return
        }
        Stop-QrPairing "Phone found at $($hit.Ip). Pairing..." 'busy'
        $dev = $null
        Show-Busy "Phone found at $($hit.Ip). Pairing..."
        try {
            $before = Get-ReadySerials
            $r = Invoke-Adb "pair $($hit.Ip):$($hit.Port) $($App.QrPass)" 25
            Log $r.Text
            if ($r.Text -match 'Successfully paired') {
                $dev = Complete-Pairing $hit.Ip $before
            } else {
                Log 'Pairing was refused. Close the scanner on the phone and try again.' 'bad'
            }
        } finally { Hide-Busy }
        if ($dev) {
            Set-QrStatus "$($dev.Name) is paired and saved. Go to Home and press Start mirroring." 'ok'
            Show-Toast "$($dev.Name) added - no cable needed!" 'ok'
        } else {
            Set-QrStatus 'Pairing did not finish. Click Show QR code to try again.' 'bad'
        }
    } finally { $App.QrPolling = $false }
}

$QrTimer.Add_Tick({ Poll-QrPairing })

# ---------------------------------------------------------------- Flow Connect (phone app)
$CompanionPkg = 'com.scrcpystudio.connect'

# The phone app's source folder: FlowConnect (new name) or StudioConnect (older copies)
function Get-CompanionDir {
    foreach ($n in 'FlowConnect', 'StudioConnect') {
        $d = Join-Path $Here $n
        if (Test-Path -LiteralPath (Join-Path $d 'build.ps1')) { return $d }
    }
    return (Join-Path $Here 'FlowConnect')
}

function Find-CompanionApk {
    $cdir = Get-CompanionDir
    $cands = @(
        (Join-Path $Here 'FlowConnect.apk'),
        (Join-Path $Here 'StudioConnect.apk'),
        (Join-Path $cdir 'app\build\outputs\apk\debug\app-debug.apk'),
        (Join-Path $cdir 'app\build\outputs\apk\release\app-release.apk')
    )
    $found = @($cands | Where-Object { Test-Path -LiteralPath $_ } | ForEach-Object { Get-Item -LiteralPath $_ } | Sort-Object LastWriteTime -Descending)
    if ($found.Count -gt 0) { return $found[0].FullName }
    $dir = Join-Path $cdir 'app\build\outputs\apk'
    if (Test-Path -LiteralPath $dir) {
        $f = Get-ChildItem -LiteralPath $dir -Filter '*.apk' -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -notlike '*unsigned*' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if ($f) { return $f.FullName }
    }
    return $null
}

function Install-CompanionOn([string]$Serial, $Dev) {
    # Call while the busy overlay is showing. Returns $true when the app is installed and unlocked.
    $apk = Find-CompanionApk
    if (-not $apk) {
        Log "The phone app (Flow Connect) is not built yet. Run 'Build Flow Connect.bat' in the $(Split-Path (Get-CompanionDir) -Leaf) folder." 'warn'
        return $false
    }
    $name = if ($Dev) { $Dev.Name } else { $Serial }
    Set-BusyText "Installing Flow Connect on $name..."
    $r = Invoke-Adb "-s $Serial install -r `"$apk`"" 180
    if ($r.Text -notmatch 'Success') {
        Log $r.Text 'bad'
        if ($r.Text -match 'USER_RESTRICTED|INSTALL_CANCELED') {
            Log 'Xiaomi/Redmi/POCO: turn on "Install via USB" in Developer options (and allow the prompt on the phone), then try again.' 'warn'
        }
        return $false
    }
    Set-BusyText 'Unlocking one-tap connect...'
    $g = Invoke-Adb "-s $Serial shell pm grant $CompanionPkg android.permission.WRITE_SECURE_SETTINGS" 20
    if ($g.Text -match 'Exception|Error|denied|not') {
        Log $g.Text 'bad'
        Log 'Android did not allow the permission. Xiaomi/Redmi/POCO: turn on "USB debugging (Security settings)" in Developer options, then click Install phone app again.' 'warn'
        return $false
    }
    [void](Invoke-Adb "-s $Serial shell am start -n $CompanionPkg/.MainActivity" 15)
    Wait-UI 600
    [void](Invoke-Adb "-s $Serial shell am broadcast -a com.scrcpystudio.connect.SETUP -n $CompanionPkg/.SetupReceiver -f 0x20 --ez keep_on true" 15)
    if ($Dev) {
        $Dev.Companion = $true
        Save-State
    }
    Log "Flow Connect is installed on $name. Wireless debugging now turns itself back on, and the phone has a 'PC connect' quick tile." 'ok'
    return $true
}

function Test-CompanionNeedsBuild {
    # True when the phone app's source code is newer than the built app (or no app was built yet)
    $cdir = Get-CompanionDir
    $src = Join-Path $cdir 'app'
    if (-not (Test-Path -LiteralPath (Join-Path $cdir 'build.ps1'))) { return $false }
    $apk = Find-CompanionApk
    if (-not $apk) { return $true }
    $apkTime = (Get-Item -LiteralPath $apk).LastWriteTime
    $newest = Get-ChildItem -LiteralPath $src -Recurse -File -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -notlike '*\build\*' } |
        Sort-Object LastWriteTime -Descending | Select-Object -First 1
    return ($newest -and $newest.LastWriteTime -gt $apkTime)
}

function Build-Companion {
    # Runs the phone app's build.ps1 in its own window so you can watch it. Returns $true on success.
    $script = Join-Path (Get-CompanionDir) 'build.ps1'
    Log 'Building the phone app (Flow Connect). A build window opens - leave it running.'
    $p = Start-Process powershell.exe -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$script`"") -PassThru
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    while (-not $p.HasExited) {
        $mins = [int][math]::Floor($sw.Elapsed.TotalMinutes)
        $secs = $sw.Elapsed.Seconds
        Set-BusyText ("Building the phone app... {0}:{1:00}" -f $mins, $secs) 'The first build takes 10-20 minutes, later builds about a minute. Progress shows in the build window.'
        Wait-UI 500
        if ($sw.Elapsed.TotalMinutes -gt 45) { break }
    }
    if (-not $p.HasExited) { Log 'The build is taking too long - check the build window.' 'bad'; return $false }
    if ($p.ExitCode -ne 0 -or (Test-CompanionNeedsBuild)) {
        Log 'The phone app build failed. Look at the build window for the red error text.' 'bad'
        return $false
    }
    Log 'Phone app built.' 'ok'
    return $true
}

function Install-CompanionUi([string]$Id) {
    $d = Get-Device $Id
    if (-not $d) { return }
    if (Test-CompanionNeedsBuild) {
        $r = Show-Dialog 'Build the new phone app first?' "The phone app has changes that are not built yet. Scrcpy Flow will build it now (a window opens; the first time takes 10-20 minutes), then install it on $($d.Name)." $false '' 'Build and install'
        if ($null -eq $r) { return }
        $built = $false
        Show-Busy 'Building the phone app...' 'The first build takes 10-20 minutes, later builds about a minute. Progress shows in the build window.'
        try { $built = Build-Companion } finally { Hide-Busy }
        if (-not $built) { Show-Toast 'The phone app could not be built. See Activity on Home.' 'bad'; return }
    }
    if (-not (Find-CompanionApk)) {
        [void](Show-Dialog 'Build the phone app first' "Run 'Build Flow Connect.bat' in the $(Split-Path (Get-CompanionDir) -Leaf) folder next to Scrcpy Flow. It downloads what it needs and builds the app. Then click the download button again." $false '' 'OK')
        return
    }
    $ok = $false
    Show-Busy "Connecting to $($d.Name)..."
    try {
        $serial = Ensure-Connected (Resolve-Target "saved:$Id")
        if ($serial) { $ok = Install-CompanionOn $serial $d }
    } finally { Hide-Busy }
    if ($ok) { Render-Saved; Show-Toast "Flow Connect installed on $($d.Name)." 'ok' }
    else { Show-Toast 'Could not install the phone app. See Activity on Home.' 'bad' }
}

function Add-ByIp {
    $n = $UI.AddName.Text.Trim()
    $a = $UI.AddAddr.Text.Trim()
    if ($a -notmatch '^\d{1,3}(\.\d{1,3}){3}(:\d+)?$') { Show-Toast 'Enter an IP like 192.168.1.23 (optionally :port).' 'warn'; return }
    if (-not $n) { $n = 'Phone' }
    $dev = New-DeviceObj @{ Name = $n; Address = $a; Profile = 'Balanced' }
    $State.Devices = @($State.Devices) + $dev
    if (-not $State.DefaultDevice) { $State.DefaultDevice = $dev.Id }
    Save-State
    $UI.AddName.Text = ''; $UI.AddAddr.Text = ''
    Render-Saved; Refresh-DeviceCombos
    Show-Toast "Saved $n." 'ok'
}

function Shot-FromHome {
    $t = Resolve-Target ([string](Get-ComboTag $UI.HomeDevice))
    if (-not $t) { Show-Toast 'No phone selected.' 'warn'; return }
    $running = $App.Sessions | Where-Object { -not $_.Ended -and $_.DeviceTag -eq $t.Tag } | Select-Object -First 1
    if ($running) { Save-Screenshot $running.Serial $t.Name; return }
    Show-Busy "Connecting to $($t.Name)..."
    $serial = $null
    try {
        $serial = Ensure-Connected $t
        if ($serial) { Set-BusyText 'Taking screenshot...'; Save-Screenshot $serial $t.Name }
    } finally { Hide-Busy }
    if (-not $serial) { Show-Toast "Could not connect to $($t.Name)." 'bad' }
}

function Refresh-PhoneInfo {
    $t = Resolve-Target ([string](Get-ComboTag $UI.HomeDevice))
    if (-not $t) { return }
    Show-Busy "Reading $($t.Name)..."
    try {
        $serial = Ensure-Connected $t
        if ($serial) { Update-InfoFromPhone $serial $t }
    } finally { Hide-Busy }
    if (-not $serial) { Show-Toast "$($t.Name) is not reachable right now." 'warn' }
}

function Launch-Game {
    $t = Resolve-Target ([string](Get-ComboTag $UI.GameDevice))
    if (-not $t) { Show-Toast 'No phone selected. Add one on the Devices page.' 'warn'; return }
    $prof = Get-Profile 'Gaming'
    Show-Busy "Connecting to $($t.Name)..."
    $serial = $null
    try { $serial = Ensure-Connected $t } finally { Hide-Busy }
    if (-not $serial) { Show-Toast "Could not connect to $($t.Name). See Activity on Home." 'bad'; return }
    Start-Session -Serial $serial -Name $t.Name -Prof $prof -DeviceTag $t.Tag
}

function Load-Apps {
    $t = Resolve-Target ([string](Get-ComboTag $UI.GameDevice))
    if (-not $t) { Show-Toast 'No phone selected.' 'warn'; return }
    Show-Busy 'Reading installed apps...'
    $pk = @()
    try {
        $serial = Ensure-Connected $t
        if ($serial) {
            $r = Invoke-Adb "-s $serial shell pm list packages -3" 20
            $pk = @($r.Out -split "\r?\n" | Where-Object { $_ -match '^package:' } | ForEach-Object { ($_ -replace '^package:', '').Trim() } | Sort-Object)
        }
    } finally { Hide-Busy }
    if ($pk.Count -eq 0) { Show-Toast 'No apps found (is the phone connected?).' 'warn'; return }
    $App.Syncing = $true
    try {
        $UI.GApp.Items.Clear()
        foreach ($p in $pk) {
            $it = New-Object System.Windows.Controls.ComboBoxItem
            $it.Content = $p
            $it.Tag = $p
            [void]$UI.GApp.Items.Add($it)
        }
    } finally { $App.Syncing = $false }
    $UI.GApp.IsDropDownOpen = $true
    Show-Toast "Found $($pk.Count) apps. Pick your game." 'ok'
}

