$SMap = @(
    @('SSource', 'Source', 'Source'), @('SSize', 'MaxSize', 'Size'), @('SBitrate', 'BitRate'), @('SFps', 'MaxFps', 'Fps'),
    @('SCodec', 'Codec', 'Codec'), @('SRotLock', 'RotationLock'),
    @('SAudio', 'Audio'), @('SAudioSrc', 'AudioSource', 'AudioSrc'), @('SAudioBuf', 'AudioBuffer', 'AudioBuf'),
    @('SVirtual', 'VirtualDisplay'), @('SVdSize', 'VdSize', 'VdSize'), @('SVdDpi', 'VdDpi', 'VdDpi'), @('SFlex', 'FlexDisplay'), @('SStartApp', 'StartApp'),
    @('SKeepActive', 'KeepActive'), @('SStayAwake', 'StayAwake'), @('SScreenOff', 'ScreenOff'), @('SPowerOff', 'PowerOffOnClose'), @('SShowTouches', 'ShowTouches'),
    @('SNoControl', 'NoControl'), @('SKeyboard', 'Keyboard', 'Keyboard'), @('SMouse', 'Mouse', 'Mouse'), @('SGamepad', 'Gamepad', 'Gamepad'),
    @('SOnTop', 'OnTop'), @('SFullscreen', 'Fullscreen'), @('SBorderless', 'Borderless'), @('SPrintFps', 'PrintFps'), @('SExtra', 'ExtraArgs')
)
$GMap = @(
    @('GFps', 'MaxFps', 'GFps'), @('GSize', 'MaxSize', 'GSize'), @('GBitrate', 'BitRate'), @('GCodec', 'Codec', 'Codec'),
    @('GAudioBuf', 'AudioBuffer', 'AudioBuf'), @('GAudio', 'Audio'), @('GPrintFps', 'PrintFps'),
    @('GKeyboard', 'Keyboard', 'Keyboard'), @('GMouse', 'Mouse', 'Mouse'), @('GGamepad', 'Gamepad', 'Gamepad'),
    @('GKeepActive', 'KeepActive'), @('GScreenOff', 'ScreenOff'),
    @('GVirtual', 'VirtualDisplay'), @('GVdSize', 'VdSize', 'VdSize'), @('GVdDpi', 'VdDpi', 'VdDpi'), @('GFlex', 'FlexDisplay'), @('GAppPkg', 'StartApp')
)
$SliderLabel = @{ SBitrate = 'SBitrateVal'; GBitrate = 'GBitrateVal' }

function Read-Ctl($c) {
    if ($c -is [System.Windows.Controls.ComboBox]) { return (Get-ComboTag $c) }
    if ($c -is [System.Windows.Controls.CheckBox]) { return [bool]$c.IsChecked }
    if ($c -is [System.Windows.Controls.Slider]) { return [int][math]::Round($c.Value) }
    if ($c -is [System.Windows.Controls.TextBox]) { return [string]$c.Text }
    return $null
}

function Write-Ctl($c, $v) {
    if ($c -is [System.Windows.Controls.ComboBox]) { if (-not (Select-ComboTag $c $v)) { $c.SelectedIndex = -1 } }
    elseif ($c -is [System.Windows.Controls.CheckBox]) { $c.IsChecked = [bool]$v }
    elseif ($c -is [System.Windows.Controls.Slider]) { $c.Value = [double]$v }
    elseif ($c -is [System.Windows.Controls.TextBox]) { $c.Text = [string]$v }
}

function Update-SliderLabel($c) {
    if ($c -is [System.Windows.Controls.Slider] -and $SliderLabel.ContainsKey($c.Name)) {
        $UI[$SliderLabel[$c.Name]].Text = "$([int][math]::Round($c.Value)) Mbps"
    }
}

function Load-Map([string]$Prefix) {
    $map = if ($Prefix -eq 'G') { $GMap } else { $SMap }
    $pname = if ($Prefix -eq 'G') { 'Gaming' } else { $App.EditingProfile }
    $p = Get-Profile $pname
    if (-not $p) { return }
    $App.Loading = $true
    try {
        foreach ($e in $map) {
            $c = $UI[$e[0]]
            Write-Ctl $c $p.($e[1])
            Update-SliderLabel $c
        }
    } finally { $App.Loading = $false }
}

function On-Field($c) {
    Update-SliderLabel $c
    if ($App.Loading) { return }
    $parts = ([string]$c.Tag).Split('|')
    if ($parts.Count -lt 2) { return }
    $prefix = $parts[0]; $key = $parts[1]
    $pname = if ($prefix -eq 'G') { 'Gaming' } else { $App.EditingProfile }
    $p = Get-Profile $pname
    if (-not $p) { return }
    $v = Read-Ctl $c
    if ($null -eq $v) { return }
    $p.$key = $v
    Save-State
    if ($prefix -eq 'S' -and $pname -eq 'Gaming') { Load-Map 'G' }
    if ($prefix -eq 'G' -and $App.EditingProfile -eq 'Gaming') { Load-Map 'S' }
}

function Init-Map([string]$Prefix, $Map) {
    foreach ($e in $Map) {
        $c = $UI[$e[0]]
        if (-not $c) { continue }
        if ($e.Count -ge 3 -and $e[2]) { Fill-Options $c $Opt[$e[2]] }
        $c.Tag = "$Prefix|$($e[1])"
        if ($c -is [System.Windows.Controls.ComboBox]) { $c.Add_SelectionChanged({ param($sender, $ev) On-Field $sender }) }
        elseif ($c -is [System.Windows.Controls.CheckBox]) { $c.Add_Click({ param($sender, $ev) On-Field $sender }) }
        elseif ($c -is [System.Windows.Controls.Slider]) { $c.Add_ValueChanged({ param($sender, $ev) On-Field $sender }) }
        elseif ($c -is [System.Windows.Controls.TextBox]) { $c.Add_TextChanged({ param($sender, $ev) On-Field $sender }) }
    }
}

function Select-EditProfile([string]$Name) {
    $App.EditingProfile = $Name
    Refresh-ProfileCombos
    Load-Map 'S'
    $p = Get-Profile $Name
    $UI.BtnPDel.IsEnabled = -not $p.BuiltIn
    $UI.BtnPRename.IsEnabled = -not $p.BuiltIn
}

function Test-ProfileName([string]$n) {
    if (-not $n.Trim()) { Show-Toast 'Please type a name.' 'warn'; return $false }
    if ($State.Profiles | Where-Object { $_.Name -eq $n.Trim() }) { Show-Toast 'A profile with that name already exists.' 'warn'; return $false }
    return $true
}

function New-ProfileFromUi([bool]$Copy) {
    $src = Get-Profile $App.EditingProfile
    $suggest = if ($Copy) { "$($src.Name) copy" } else { 'My profile' }
    $n = Show-Dialog $(if ($Copy) { 'Duplicate profile' } else { 'New profile' }) 'Name for the new profile:' $true $suggest 'Create'
    if ($null -eq $n -or -not (Test-ProfileName $n)) { return }
    $base = if ($Copy) { $src } else { Get-Profile 'Balanced' }
    $p = New-ProfileData $n.Trim() $false $base
    $State.Profiles = @($State.Profiles) + $p
    Save-State
    Select-EditProfile $p.Name
    Render-Saved
    Show-Toast "Created '$($p.Name)'." 'ok'
}

function Rename-ProfileUi {
    $p = Get-Profile $App.EditingProfile
    if ($p.BuiltIn) { return }
    $n = Show-Dialog 'Rename profile' '' $true $p.Name 'Rename'
    if ($null -eq $n -or $n.Trim() -eq $p.Name -or -not (Test-ProfileName $n)) { return }
    $old = $p.Name
    $p.Name = $n.Trim()
    foreach ($d in $State.Devices) { if ($d.Profile -eq $old) { $d.Profile = $p.Name } }
    Save-State
    Select-EditProfile $p.Name
    Render-Saved
    Sync-HomeProfile
}

function Remove-ProfileUi {
    $p = Get-Profile $App.EditingProfile
    if ($p.BuiltIn) { Show-Toast 'Built-in profiles cannot be deleted.' 'warn'; return }
    $r = Show-Dialog "Delete '$($p.Name)'?" 'Phones using it will switch to Balanced.' $false '' 'Delete'
    if ($null -eq $r) { return }
    $State.Profiles = @($State.Profiles | Where-Object { $_.Name -ne $p.Name })
    foreach ($d in $State.Devices) { if ($d.Profile -eq $p.Name) { $d.Profile = 'Balanced' } }
    Save-State
    Select-EditProfile 'Balanced'
    Render-Saved
    Sync-HomeProfile
}

