function Open-Folder([string]$Dir) {
    if (-not (Test-Path -LiteralPath $Dir)) { [void](New-Item -ItemType Directory -Path $Dir -Force) }
    Start-Process explorer.exe -ArgumentList "`"$Dir`""
}

function Pick-Folder([string]$Current) {
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.ShowNewFolderButton = $true
    if ($Current -and (Test-Path -LiteralPath $Current)) { $d.SelectedPath = $Current }
    if ($d.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { return $d.SelectedPath }
    return $null
}

function Refresh-Media {
    $UI.MediaList.Children.Clear()
    $files = @()
    foreach ($dir in (@([string]$State.RecordDir, [string]$State.ShotDir) | Select-Object -Unique)) {
        if ($dir -and (Test-Path -LiteralPath $dir)) {
            $files += @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { @('.mp4', '.mkv', '.png') -contains $_.Extension.ToLower() })
        }
    }
    $files = @($files | Sort-Object LastWriteTime -Descending | Select-Object -First 48)
    $UI.MediaEmpty.Visibility = if ($files.Count -eq 0) { 'Visible' } else { 'Collapsed' }
    foreach ($f in $files) {
        $tile = New-Object System.Windows.Controls.Border
        $tile.Width = 208
        $tile.Margin = '0,0,14,14'
        $tile.CornerRadius = '12'
        $tile.Background = $window.FindResource('GrStat')
        Add-HoverGlow $tile '#FF2A303B' '#FF6E8BFF'
        $tile.Cursor = [System.Windows.Input.Cursors]::Hand
        $tile.ToolTip = "Open $($f.Name)"
        $tile.Tag = $f.FullName
        $sp = New-Object System.Windows.Controls.StackPanel

        $thumb = New-Object System.Windows.Controls.Border
        $thumb.Height = 118
        $thumb.CornerRadius = '11,11,0,0'
        $thumb.Background = Get-Brush '#12151B'
        $thumb.ClipToBounds = $true
        $isPng = $f.Extension.ToLower() -eq '.png'
        if ($isPng) {
            try {
                $bi = New-Object System.Windows.Media.Imaging.BitmapImage
                $bi.BeginInit()
                $bi.UriSource = New-Object System.Uri($f.FullName)
                $bi.DecodePixelHeight = 236
                $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $bi.EndInit()
                $img = New-Object System.Windows.Controls.Image
                $img.Source = $bi
                $img.Stretch = 'Uniform'
                $img.Margin = '0,6,0,6'
                $thumb.Child = $img
            } catch { $thumb.Child = (New-Glyph 0xE722 30 '#5B8CFF') }
        } else {
            $vg = New-Object System.Windows.Controls.Grid
            [void]$vg.Children.Add((New-Glyph 0xE714 34 '#5B8CFF'))
            $ext = New-Badge $f.Extension.TrimStart('.').ToUpper() '#9DB8FF'
            $ext.HorizontalAlignment = 'Left'; $ext.VerticalAlignment = 'Top'; $ext.Margin = '10,10,0,0'
            [void]$vg.Children.Add($ext)
            $thumb.Child = $vg
        }
        [void]$sp.Children.Add($thumb)

        $meta = New-Object System.Windows.Controls.Grid
        $meta.Margin = '12,10,6,10'
        Add-Col $meta '*'; Add-Col $meta 'Auto'
        $txt = New-Object System.Windows.Controls.StackPanel
        $nm = New-Text $f.Name 12 ([System.Windows.FontWeights]::SemiBold)
        [void]$txt.Children.Add($nm)
        $sub = New-Text ("{0}  $Dot  {1}" -f $f.LastWriteTime.ToString('d MMM, HH:mm'), (Format-Size $f.Length)) 12 $null '#A3ACB9'
        $sub.Margin = '0,2,0,0'
        [void]$txt.Children.Add($sub)
        Put $meta $txt 0
        $mb = New-Object System.Windows.Controls.StackPanel
        $mb.Orientation = 'Horizontal'
        $b1 = New-IconBtn 0xE838 'Show in folder' $f.FullName { param($b, $e) $e.Handled = $true; Start-Process explorer.exe -ArgumentList "/select,`"$($b.Tag)`"" }
        $b1.Padding = '6'
        $b2 = New-IconBtn 0xE74D 'Move to Recycle Bin' $f.FullName { param($b, $e) $e.Handled = $true; Remove-Capture $b.Tag } '#FF8A95'
        $b2.Padding = '6'
        [void]$mb.Children.Add($b1)
        [void]$mb.Children.Add($b2)
        Put $meta $mb 1
        [void]$sp.Children.Add($meta)
        $tile.Child = $sp
        $tile.Add_MouseLeftButtonUp({
            param($t, $e)
            if ($e.OriginalSource -is [System.Windows.Controls.TextBlock] -and $e.OriginalSource.FontFamily.Source -like '*Icons*') { return }
            try { Start-Process -FilePath ([string]$t.Tag) } catch { Show-Toast 'Could not open the file.' 'bad' }
        })
        Add-Entrance $tile ("media:" + $f.FullName)
        [void]$UI.MediaList.Children.Add($tile)
    }
}

function Remove-Capture([string]$Path) {
    $r = Show-Dialog 'Move to Recycle Bin?' (Split-Path $Path -Leaf) $false '' 'Delete'
    if ($null -eq $r) { return }
    try {
        [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)
        Show-Toast 'Moved to Recycle Bin.' 'ok'
    } catch { Show-Toast 'Could not delete the file.' 'bad' }
    Refresh-Media
}

# =====================================================================
#  Animation add-ons: download from nuget.org into .\libs.new
# =====================================================================
$TfmOrder = @('net48', 'net472', 'net471', 'net47', 'net462', 'net461', 'net46', 'net452', 'net451', 'net45', 'net40',
    'netstandard2.0', 'netstandard1.6', 'netstandard1.5', 'netstandard1.4', 'netstandard1.3', 'netstandard1.2', 'netstandard1.1', 'netstandard1.0')

function Get-TfmRank([string]$Tfm) {
    $t = ([string]$Tfm).ToLower().Trim()
    if ($t -eq '') { return 900 }
    if ($t -match '^\.netframework(\d)\.(\d)(?:\.(\d))?$') { $t = 'net' + $Matches[1] + $Matches[2] + $Matches[3] }
    elseif ($t -match '^\.netstandard(\d+\.\d+)$') { $t = 'netstandard' + $Matches[1] }
    $i = [array]::IndexOf($TfmOrder, $t)
    return $i
}

function Test-SkipPackage([string]$Id) {
    $l = $Id.ToLower()
    if ($l -match '^(netstandard\.library|microsoft\.netcore\.|microsoft\.sourcelink|microsoft\.build\.|microsoft\.netframework\.referenceassemblies|runtime\.)') { return $true }
    if ($l -match '^(skiasharp|harfbuzzsharp)\.nativeassets\.' -and $l -notmatch '\.win32$') { return $true }
    if ($l.StartsWith('system.')) {
        $keep = @('system.memory', 'system.buffers', 'system.numerics.vectors', 'system.runtime.compilerservices.unsafe',
            'system.threading.tasks.extensions', 'system.reactive', 'system.text.json', 'system.text.encodings.web',
            'system.collections.immutable', 'system.diagnostics.diagnosticsource', 'system.io.pipelines', 'system.drawing.common')
        return -not ($keep -contains $l)
    }
    return $false
}

function Get-Url([string]$Url, [string]$OutFile) {
    $wc = New-Object System.Net.WebClient
    $wc.Headers.Add('User-Agent', 'Scrcpy-Flow')
    $t = $wc.DownloadFileTaskAsync($Url, $OutFile)
    while (-not $t.IsCompleted) { Invoke-UIEvents; Start-Sleep -Milliseconds 30 }
    if ($t.IsFaulted) { throw $t.Exception.GetBaseException() }
}

function Install-AddOns {
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $work = Join-Path $env:TEMP ('scrcpystudio_addons_' + [guid]::NewGuid().ToString('N'))
    $newLib = Join-Path $Here 'libs.new'
    if (Test-Path -LiteralPath $newLib) { Remove-Item -LiteralPath $newLib -Recurse -Force }
    [void](New-Item -ItemType Directory -Path (Join-Path $newLib 'native') -Force)
    [void](New-Item -ItemType Directory -Path $work -Force)

    $queue = New-Object System.Collections.Queue
    foreach ($p in $AddOnPackages) { $queue.Enqueue(@($p[0], $p[1])) }
    $seen = @{}
    $count = 0
    try {
        while ($queue.Count -gt 0) {
            $item = $queue.Dequeue()
            $id = [string]$item[0]
            $ver = [string]$item[1]
            $key = $id.ToLower()
            if (-not $id -or $seen.ContainsKey($key) -or (Test-SkipPackage $id)) { continue }
            $seen[$key] = $true
            $count++
            Set-BusyText "Downloading add-ons ($count): $id $ver"
            $url = "https://www.nuget.org/api/v2/package/$id"
            if ($ver) { $url += "/$ver" }
            $pkg = Join-Path $work "$key.zip"
            Get-Url $url $pkg
            $dir = Join-Path $work $key
            [System.IO.Compression.ZipFile]::ExtractToDirectory($pkg, $dir)

            $libRoot = Join-Path $dir 'lib'
            if (Test-Path -LiteralPath $libRoot) {
                $best = $null; $bestRank = 999
                foreach ($d in @(Get-ChildItem -LiteralPath $libRoot -Directory)) {
                    $r = Get-TfmRank $d.Name
                    if ($r -ge 0 -and $r -lt $bestRank) { $bestRank = $r; $best = $d }
                }
                if ($best) {
                    foreach ($f in @(Get-ChildItem -LiteralPath $best.FullName -Filter '*.dll')) {
                        Copy-Item -LiteralPath $f.FullName -Destination $newLib -Force
                    }
                }
            }
            $nat = Join-Path $dir 'runtimes\win-x64\native'
            if (Test-Path -LiteralPath $nat) {
                foreach ($f in @(Get-ChildItem -LiteralPath $nat -Filter '*.dll')) {
                    Copy-Item -LiteralPath $f.FullName -Destination (Join-Path $newLib 'native') -Force
                }
            }

            $nuspec = Get-ChildItem -LiteralPath $dir -Filter '*.nuspec' | Select-Object -First 1
            if ($nuspec) {
                [xml]$doc = Get-Content -LiteralPath $nuspec.FullName -Raw
                $groups = @($doc.SelectNodes("//*[local-name()='dependencies']/*[local-name()='group']"))
                $deps = @()
                if ($groups.Count -gt 0) {
                    $bestG = $null; $bestRank = 999
                    foreach ($g in $groups) {
                        $r = Get-TfmRank ([string]$g.GetAttribute('targetFramework'))
                        if ($r -ge 0 -and $r -lt $bestRank) { $bestRank = $r; $bestG = $g }
                    }
                    if ($bestG) { $deps = @($bestG.SelectNodes("*[local-name()='dependency']")) }
                } else {
                    $deps = @($doc.SelectNodes("//*[local-name()='dependencies']/*[local-name()='dependency']"))
                }
                foreach ($dep in $deps) {
                    $dv = [string]$dep.GetAttribute('version')
                    $m = [regex]::Match($dv, '\d+(\.\d+)*(-[0-9A-Za-z.-]+)?')
                    $v2 = ''
                    if ($m.Success) { $v2 = $m.Value }
                    $queue.Enqueue(@([string]$dep.GetAttribute('id'), $v2))
                }
            }
        }
    } finally {
        Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    }
    if (-not (Test-Path -LiteralPath (Join-Path $newLib 'XamlFlair.WPF.dll')) -or -not (Test-Path -LiteralPath (Join-Path $newLib 'LottieSharp.dll'))) {
        throw 'The add-on files were not found in the downloaded packages.'
    }
    return $count
}

function Restart-Studio {
    $window.Close()
    if ($window.IsVisible) { return }   # closing was cancelled
    Start-Process powershell.exe -ArgumentList @('-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', "`"$MyScript`"")
}

function Update-AnimStatus {
    $f = if ($App.HasFlair) { 'XamlFlair: on' } elseif ($App.FlairFailed -or (Test-Path -LiteralPath (Join-Path $LibDir 'XamlFlair.WPF.dll'))) { 'XamlFlair: could not start (see scrcpy-flow.log)' } else { 'XamlFlair: not installed' }
    $l = if ($App.HasLottie) { 'LottieSharp: on' } elseif (Test-Path -LiteralPath (Join-Path $LibDir 'LottieSharp.dll')) { 'LottieSharp: could not start (see scrcpy-flow.log)' } else { 'LottieSharp: not installed' }
    $UI.AnimStatus.Text = "Built-in animations: on   $Dot   $f   $Dot   $l"
    $UI.BtnAddOns.Content = if ($App.HasFlair -and $App.HasLottie) { 'Re-download add-ons' } else { 'Download add-ons' }
}

