        $UI.SessionIdleHost.Visibility = 'Visible'
    }
}

# =====================================================================
#  Phone app bridge: "Start on PC" requests from Flow Connect
# =====================================================================
$BridgeUri = 'content://com.scrcpystudio.connect.bridge'
$App.BridgeBusy = $false
$App.BridgeTick = 0
$App.BridgeWarned = @{}

function Get-CompanionLinks {
    $comp = @($State.Devices | Where-Object { $_.Companion })
    if ($comp.Count -eq 0) { return @() }
    $devs = @(Get-AdbDevices | Where-Object { $_.State -eq 'device' })
    $out = @()
    foreach ($d in $comp) {
        $ip = Get-IpOf $d.Address
        $hw = [string]$d.HwSerial
        $match = $devs | Where-Object {
            ($hw -and ($_.Serial -eq $hw -or $_.Serial -like "adb-$hw-*")) -or ($ip -and $_.Serial -like "${ip}:*")
        } | Select-Object -First 1
        $ser = $null
        if ($match) { $ser = $match.Serial }
        $out += [pscustomobject]@{ Device = $d; Serial = $ser }
    }
    return $out
}

function Try-AutoConnect($Dev) {
    $ip = Get-IpOf $Dev.Address
    foreach ($m in @(Get-MdnsServices)) {
        $hit = ($ip -and $m.Ip -eq $ip)
        if ($Dev.HwSerial -and $m.Name -like "adb-$($Dev.HwSerial)-*") { $hit = $true }
        if ($hit) {
            $r = Invoke-Adb "connect $($m.Ip):$($m.Port)" 8
            if ($r.Text -match 'connected to') {
                Log "$($Dev.Name) is back on Wi-Fi - connected automatically." 'ok'
                if ($m.Ip -ne $ip) { $Dev.Address = $m.Ip; Save-State }
                return
            }
        }
    }
}

function Send-PhoneStatus([string]$Serial, [string]$StateName, [string]$Mode) {
    if (-not $Serial) { return }
    if (-not $Mode) { $Mode = 'mirror' }
    [void](Invoke-Adb "-s $Serial shell content insert --uri $BridgeUri/status --bind state:s:$StateName --bind mode:s:$Mode" 6)
}

function Get-CompanionFor([string]$DeviceTag) {
    if ($DeviceTag -like 'saved:*') {
        $d = Get-Device $DeviceTag.Substring(6)
        if ($d -and $d.Companion) { return $d }
    }
    return $null
}

function Handle-PhoneRequest($Dev, [string]$Serial, [string]$Action, [string]$Mode) {
    if ($Mode -ne 'virtual') { $Mode = 'mirror' }
    $what = if ($Mode -eq 'virtual') { 'second screen' } else { 'phone screen' }
    if ($Action -eq 'stop') {
        Log "$($Dev.Name) asked to stop mirroring."
        $running = $App.Sessions | Where-Object { -not $_.Ended -and ($_.Serial -eq $Serial -or $_.DeviceTag -eq "saved:$($Dev.Id)") }
        if (@($running).Count -gt 0) {
            foreach ($s in @($running)) { Stop-Session $s.Id }
        } else {
            Send-PhoneStatus $Serial 'idle' $Mode
        }
        return
    }
    if ($Action -ne 'start') { return }
    Log "$($Dev.Name) asked to start mirroring ($what)." 'ok'
    $already = $App.Sessions | Where-Object { -not $_.Ended -and ($_.Serial -eq $Serial -or $_.DeviceTag -eq "saved:$($Dev.Id)") } | Select-Object -First 1
    if ($already) {
        Send-PhoneStatus $Serial 'running' $already.Mode
        Show-Toast "$($Dev.Name) is already being mirrored." 'warn'
        return
    }
    Send-PhoneStatus $Serial 'starting' $Mode
    $prof = Get-Profile $Dev.Profile
    if ($Mode -eq 'virtual') {
        $prof = New-ProfileData "$($prof.Name) + second screen" $false $prof
        $prof.VirtualDisplay = $true
    }
    Start-Session -Serial $Serial -Name $Dev.Name -Prof $prof -DeviceTag "saved:$($Dev.Id)" -Mode $Mode
}

function Poll-PhoneRequests {
    if ($App.BridgeBusy -or $App.BusyDepth -gt 0 -or $App.InTick -or $App.DlgFrame) { return }
    $App.BridgeBusy = $true
    try {
        $App.BridgeTick++
        foreach ($l in @(Get-CompanionLinks)) {
            if (-not $l.Serial) {
                if ($App.BridgeTick % 3 -eq 0) { Try-AutoConnect $l.Device }
                continue
            }
            $r = Invoke-Adb "-s $($l.Serial) shell content query --uri $BridgeUri/request" 6
            if ($r.Text -match 'Could not find provider|Unknown URI|Permission Denial|SecurityException') {
                if (-not $App.BridgeWarned.ContainsKey($l.Device.Id)) {
                    $App.BridgeWarned[$l.Device.Id] = $true
                    Log "To use 'Start on PC' from $($l.Device.Name), update the phone app: Devices > download button on that phone." 'warn'
                }
                continue
            }
            if ($r.Out -match 'action=(\w+)') {
                $action = $Matches[1]
                $mode = 'mirror'
                if ($r.Out -match 'mode=(\w+)') { $mode = $Matches[1] }
                Handle-PhoneRequest $l.Device $l.Serial $action $mode
            }
        }
    } catch {
        Write-Crash $_
    } finally {
        $App.BridgeBusy = $false
    }
}

$BridgeTimer = New-Object System.Windows.Threading.DispatcherTimer
$BridgeTimer.Interval = [TimeSpan]::FromSeconds(3)
$BridgeTimer.Add_Tick({ Poll-PhoneRequests })

