# Errors inside button handlers: report instead of crashing
$window.Dispatcher.Add_UnhandledException({
    param($s, $e)
    $e.Handled = $true
    $App.BusyDepth = 1
    Hide-Busy
    $ex = $e.Exception
    $where = ''
    try { if ($ex.ErrorRecord -and $ex.ErrorRecord.InvocationInfo) { $where = " (line $($ex.ErrorRecord.InvocationInfo.ScriptLineNumber))" } } catch {}
    Write-Crash $ex
    Log "Unexpected error: $($ex.Message)$where" 'bad'
    Show-Toast 'Something went wrong. Details are in Activity on Home.' 'bad'
})

# Dark title bar and icon
$window.Add_SourceInitialized({
    try {
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
        $th = $Themes[[string]$State.Theme]
        $on = if ($th.Dark) { 1 } else { 0 }
        [void][StudioNative]::DwmSetWindowAttribute($hwnd, 20, [ref]$on, 4)
        [void][StudioNative]::DwmSetWindowAttribute($hwnd, 19, [ref]$on, 4)
        $cap = [int]$th.Caption
        [void][StudioNative]::DwmSetWindowAttribute($hwnd, 35, [ref]$cap, 4)
    } catch {}
})

$window.Add_Closing({
    param($s, $e)
    $running = @($App.Sessions | Where-Object { -not $_.Ended })
    if ($running.Count -gt 0) {
        $r = [System.Windows.MessageBox]::Show(
            "$($running.Count) mirror(s) still running.`n`nYes = close them too`nNo = keep them open",
            'Scrcpy Flow', [System.Windows.MessageBoxButton]::YesNoCancel, [System.Windows.MessageBoxImage]::Question)
        if ($r -eq [System.Windows.MessageBoxResult]::Cancel) { $e.Cancel = $true; return }
        if ($r -eq [System.Windows.MessageBoxResult]::Yes) { foreach ($x in $running) { Stop-Session $x.Id } }
    }
    $Timer.Stop()
    $QrTimer.Stop()
    $BridgeTimer.Stop()
    Save-State
})

