$window.Add_ContentRendered({
    Log 'Welcome to Scrcpy Flow.'
    if ($App.HasFlair -or $App.HasLottie) { Log "Animation add-ons: XamlFlair $(if ($App.HasFlair) { 'on' } else { 'off' }), LottieSharp $(if ($App.HasLottie) { 'on' } else { 'off' })." }
    Log "scrcpy folder: $($App.ScrcpyDir)"
    if (-not (Test-Path -LiteralPath $App.Adb)) {
        Log 'adb.exe is missing from the scrcpy folder. Re-extract the scrcpy zip.' 'bad'
        $UI.AdbDot.Fill = Get-Brush $Colors.bad
        $UI.AdbText.Text = 'adb.exe missing'
        return
    }
    Show-Busy 'Starting adb...'
    try {
        [void](Start-AdbServer)
        $v = Invoke-Tool $App.Scrcpy '--version' 10
        if ($v.Text -match 'scrcpy\s+v?(\d+)\.(\d+)(\.\d+)?') {
            $App.ScrcpyMajor = [int]$Matches[1]
            $App.ScrcpyVersion = "$($Matches[1]).$($Matches[2])$($Matches[3])"
        }
        $UI.SideVersion.Text = "powered by scrcpy $($App.ScrcpyVersion)"
        if ($App.ScrcpyMajor -lt 4) {
            Log "You have scrcpy $($App.ScrcpyVersion). 'Keep screen on' and 'Resize with the window' need scrcpy 4.0+ and will be skipped." 'warn'
        }
        Set-BusyText 'Looking for phones...'
        Scan-Devices
    } finally { Hide-Busy }
    $Timer.Start()
    $BridgeTimer.Start()
    $n = @($App.Detected | Where-Object { $_.State -eq 'device' }).Count
    if ($n -gt 0) { Log "$n phone(s) connected right now." 'ok' }
    elseif (@($State.Devices).Count -gt 0) { Log 'Pick your phone and press Start mirroring.' }
    else { Log 'First time? Click Add phone above - you can add your phone by scanning a QR code, no cable needed.' }
    if ($State.AutoConnect -and $State.DefaultDevice -and (Get-Device $State.DefaultDevice)) {
        [void](Select-ComboTag $UI.HomeDevice "saved:$($State.DefaultDevice)")
        Start-FromHome
    }
})

[void]$window.ShowDialog()

} catch {
    Write-Crash $_
    try {
        [void][System.Windows.MessageBox]::Show("Scrcpy Flow could not start:`n`n$($_.Exception.Message)`n`nDetails were saved to scrcpy-flow.log next to the app.", 'Scrcpy Flow')
    } catch {}
}
